import{i as e,n as t}from"./lab-DknU2nQy.js";import{t as n}from"./exam-BEHpgZdM.js";var r=[{id:`sumproduct`,group:`Model and optimise`,title:`Totals, expected values and weighted averages (SUMPRODUCT)`,spot:`Quantities times prices, values times probabilities, or shares times rates, added up into one number.`,cues:[`total cost`,`total revenue`,`subtotal`,`receipt`,`expected value`,`expected revenue`,`expected cost`,`expected number`,`expected profit`,`weighted average`,`weighted`,`blended`,`probability of each`,`per unit`,`unit price`,`quantity`,`quantities`,`share of`,`proportion of`],steps:[`Find the two (or more) ranges that pair up item by item: quantity with price, value with probability, share with rate.`,`Check they have the same shape and length (both down a column, or both along a row).`,`Write =SUMPRODUCT(range1,range2). Anchor the ranges with $ if the formula will be filled.`,`For an expected value, check the probabilities add up to 1 with =SUM(...).`,`For a weighted average, divide by the total weight.`,`For a condition (only North, only Type A), multiply by a comparison inside SUMPRODUCT.`],formulas:[{label:`Receipt subtotal`,f:`=SUMPRODUCT(C5:C10,D5:D10)`,where:`C5:C10 quantities, D5:D10 unit prices`},{label:`Expected value`,f:`=SUMPRODUCT(A2:A6,B2:B6)`,where:`A2:A6 outcomes, B2:B6 probabilities (sum to 1)`},{label:`Weighted average`,f:`=SUMPRODUCT(B2:B6,C2:C6)/SUM(C2:C6)`,where:`B values, C weights (group sizes, volumes)`},{label:`Total with one condition`,f:`=SUMPRODUCT((B2:B61="North")*E2:E61)`,where:`B region, E revenue`},{label:`Total with two conditions`,f:`=SUMPRODUCT((B2:B61="North")*(C2:C61>=24)*E2:E61)`},{label:`Cost of a mix row by row, fill down`,f:`=SUMPRODUCT($E$3:$F$3,E6:F6)`,where:`E3:F3 unit costs (locked), E6:F6 this row's amounts`}],pitfalls:[`Ranges of different sizes, or one row and one column, return #VALUE!.`,`AVERAGE is wrong when items carry different weights (passengers per group, units per order): use SUMPRODUCT / SUM.`,`Use the same units in both ranges (MB vs GB, minutes vs day fractions).`],techniques:[`SUMPRODUCT totals and weighted/expected values`]},{id:`bracket`,group:`Model and optimise`,title:`Band or tier lookups: discount, rate or fee by amount`,spot:`A table of bands (below $500, $500 to $1,499, ... or 0-2 hours, 2-4 hours) and you need the rate for an amount that falls inside a band.`,cues:[`band`,`bands`,`bracket`,`brackets`,`tier`,`tiers`,`tiered`,`and above`,`or more`,`up to`,`below`,`between`,`discount rate`,`commission`,`depending on`,`depends on the amount`,`price break`,`price list`,`grade`,`rate table`,`lower bound`,`lower bounds`],steps:[`If the bands are printed as text, build a numeric lower-bound column: the smallest amount of each band, in ascending order, starting at 0 (or the lowest possible value).`,`Put the rate (or fee) in the column to the right of the lower bounds.`,`Look up with an approximate match: VLOOKUP(...,TRUE), LOOKUP or INDEX/MATCH type 1.`,`Anchor the table with $ before filling down.`,`Test a value exactly on a boundary (e.g. 500) and one just below: they must land in different bands.`,`For hours or minutes stored as times, convert first and round: ROUND(duration*24,6).`],formulas:[{label:`VLOOKUP approximate`,f:`=VLOOKUP(D27,$G$5:$H$9,2,TRUE)`,where:`D27 amount, G5:G9 lower bounds (ascending), H5:H9 rates`},{label:`LOOKUP (two vectors)`,f:`=LOOKUP(D27,$G$5:$G$9,$H$5:$H$9)`},{label:`INDEX/MATCH type 1`,f:`=INDEX($H$5:$H$9,MATCH(D27,$G$5:$G$9,1))`},{label:`Amount after discount`,f:`=D27*(1-D28)`,where:`D28 the looked-up discount rate`},{label:`Hourly band from a duration`,f:`=VLOOKUP(ROUND((C5-B5)*24,6),$G$4:$H$8,2,TRUE)`,where:`B5 start time, C5 end time, G lower bounds in hours`}],pitfalls:[`Lower bounds must be ascending, and must start at 0: an amount below the first bound returns #N/A.`,`FALSE (exact match) returns #N/A for every amount between the bounds.`,`"More than $500" means 500 itself is in the lower band; "$500 and above" means 500 starts the upper band.`,`Use the right amount: before or after discount, per item or per order, as the question states.`],techniques:[`Approximate-match lookup on a bracket table (VLOOKUP TRUE / LOOKUP / INDEX-MATCH 1)`,`Building lookup/step tables (lower bounds, increments, CRF)`]},{id:`exact-lookup`,group:`Model and optimise`,title:`Exact and two-way lookups (codes, matrices, INDEX/MATCH)`,spot:`Find a price, rate or fare from a table by a code or name, or from a grid by row key and column key.`,cues:[`look up`,`lookup`,`code`,`product code`,`item code`,`id`,`from the table`,`matrix`,`fare matrix`,`origin`,`destination`,`row and column`,`corresponding`,`two-way`,`two way`,`zone`],steps:[`Decide the match type: codes and names are exact (FALSE / 0); numeric bands are approximate (TRUE / 1).`,`One key: VLOOKUP(key,table,col,FALSE), or INDEX/MATCH when the key is not the first column.`,`Two keys (row and column): INDEX(grid, MATCH(row key, row labels, 0), MATCH(col key, column labels, 0)).`,`If the row and column numbers are already known (origin 2, destination 3): INDEX(grid,row,col).`,`Anchor the table ranges, leave the key cell relative, fill down.`],formulas:[{label:`Exact VLOOKUP`,f:`=VLOOKUP(B18,$A$5:$D$14,3,FALSE)`,where:`B18 code, A5:D14 menu, price in its 3rd column`},{label:`INDEX/MATCH exact`,f:`=INDEX($C$5:$C$14,MATCH(B18,$A$5:$A$14,0))`},{label:`Two-way INDEX/MATCH`,f:`=INDEX($G$12:$J$14,MATCH(D29,$F$12:$F$14,1),MATCH(D26,$G$11:$J$11,0))`,where:`G12:J14 grid, F12:F14 row bands, G11:J11 column labels`},{label:`Two-way with VLOOKUP`,f:`=VLOOKUP(D29,$F$12:$J$14,MATCH(D26,$F$11:$J$11,0),TRUE)`},{label:`Matrix by position`,f:`=INDEX($B$3:$E$6,C10,D10)`,where:`C10 row number, D10 column number`},{label:`XLOOKUP`,f:`=XLOOKUP(B18,$A$5:$A$14,$C$5:$C$14)`}],pitfalls:[`col_index_num counts from the first column of the table range, not from column A.`,`#N/A means the key was not found: check spelling, spaces and numbers stored as text.`,`Swapping the row and column MATCH gives a wrong cell or #REF!.`],techniques:[`Two-way INDEX/MATCH lookup`,`INDEX by row/column number (matrix lookup)`]},{id:`if-logic`,group:`Model and optimise`,title:`Rules and eligibility (IF, AND, OR, IFS)`,spot:`A charge, discount or flag applies only when conditions hold: "if the customer spends at least ... and ...".`,cues:[`eligible`,`eligibility`,`qualify`,`qualifies`,`only if`,`only when`,`at least`,`more than`,`less than`,`no more than`,`otherwise`,`unless`,`both`,`either`,`flag`,`yes or no`,`condition`,`conditions`,`rule`,`add-on`,`bonus`],steps:[`Write each condition as a comparison: "at least" is >=, "more than" is >, "no more than" is <=, "less than" is <.`,`All conditions must hold: AND(...). Any one is enough: OR(...). Mix them: AND(a, OR(b, c)).`,`Wrap in IF(condition, value if true, value if false).`,`Several outcomes: nested IF or IFS with TRUE as the last catch-all.`,`Text results and text comparisons go in double quotes.`],formulas:[{label:`Two conditions`,f:`=IF(AND(B2>=100,C2>=5),"Yes","No")`},{label:`Either condition`,f:`=IF(OR(B2>=500,D2="Gold"),B2*5%,0)`},{label:`Mixed AND / OR`,f:`=IF(AND(B2>100,OR(C2="N",D2>=5)),$H$1,0)`},{label:`Discount only on a weekday`,f:`=IF(AND(WEEKDAY(A2,2)<=5,B2>=50),B2*$H$2,0)`,where:`A2 date, B2 spend, H2 rate`},{label:`Several outcomes (IFS)`,f:`=IFS(B2<50,0,B2<100,5%,TRUE,10%)`},{label:`Cap between limits`,f:`=IFS(C6<$C$3,0,C6>$E$3,100,TRUE,C6)`}],pitfalls:[`Boundary words decide >= vs >: read "at least", "more than", "up to" carefully.`,`Typing "Yes " with a trailing space or a different case can break later lookups.`,`Compare dates with DATE(y,m,d) or a date cell, not with text like "1/1/2026".`],techniques:[`IF with AND/OR multi-condition rules`]},{id:`dates`,group:`Model and optimise`,title:`Dates and calendar rules (WEEKDAY, MONTH, TODAY, DATE)`,spot:`Rules about the day of the week, the month, birthdays, days between two dates, due or overdue items.`,cues:[`date`,`dates`,`weekday`,`weekend`,`day of the week`,`birthday`,`month`,`this month`,`today`,`days between`,`number of days`,`due date`,`overdue`,`expiry`,`expires`,`monday`,`sunday`,`saturday`,`anniversary`],steps:[`Dates are day numbers, so subtracting two dates gives days, and adding a number adds days.`,`Pull parts out with YEAR, MONTH, DAY and WEEKDAY; rebuild a date with DATE(y,m,d).`,`Use WEEKDAY(date,2) so Monday = 1 ... Sunday = 7 (the default WEEKDAY(date) has Sunday = 1).`,`Combine with IF/AND for the rule, and format date answers as dates.`],formulas:[{label:`Day of week (Mon = 1)`,f:`=WEEKDAY(A2,2)`},{label:`Is a weekend`,f:`=WEEKDAY(A2,2)>5`},{label:`Birthday this month`,f:`=MONTH(B2)=MONTH(TODAY())`},{label:`Days between`,f:`=C2-B2`},{label:`Age in whole years (approx.)`,f:`=INT((TODAY()-B2)/365.25)`},{label:`Rebuild a date`,f:`=DATE(YEAR(A2),MONTH(A2)+1,1)`,where:`first day of next month`},{label:`Due in 30 days`,f:`=A2+30`},{label:`Day name as text`,f:`=TEXT(A2,"ddd")`}],pitfalls:[`WEEKDAY without a second argument counts Sunday as 1.`,`TODAY() changes every day: if the question fixes a date, reference that cell instead.`,`A result showing as 45,000-something is a date that needs a date format.`],techniques:[`Date functions (TODAY, MONTH, WEEKDAY, date differences)`]},{id:`time-arith`,group:`Model and optimise`,title:`Clock times, durations and unit conversion (x24, /1440, /86400)`,spot:`Start and end times, durations charged per hour, minutes or seconds added to a clock time, or MB to GB style conversions.`,cues:[`hh:mm`,`hh:mm:ss`,`clock`,`time of day`,`start time`,`end time`,`finish time`,`duration`,`hours`,`minutes`,`seconds`,`per hour`,`hourly`,`per minute`,`convert`,`conversion`,`mb`,`gb`,`day fraction`,`session`],steps:[`Excel stores a time as a fraction of a day: 1 hour = 1/24, 1 minute = 1/1440, 1 second = 1/86400.`,`Duration in hours = (end - start) * 24; in minutes * 1440; in seconds * 86400.`,`To add minutes or seconds to a clock time, divide them first: + m/1440, + s/86400, or + TIME(h,m,s).`,`Before matching an hour band, round: ROUND((end-start)*24,6).`,`Format clock answers as hh:mm:ss; totals above 24 hours as [h]:mm:ss.`,`Other unit conversions: use exactly the factor the question gives (1000 MB per GB unless it says 1024).`],formulas:[{label:`Duration in hours`,f:`=(C5-B5)*24`},{label:`Charge by the hour, prorated by the minute`,f:`=(C5-B5)*24*E5`,where:`E5 hourly rate`},{label:`Add minutes to a time`,f:`=B5+D5/1440`},{label:`Add seconds to a time`,f:`=B5+D5/86400`},{label:`Build a time`,f:`=TIME(9,30,0)`},{label:`Step a time column by 10 seconds`,f:`=A5+TIME(0,0,10)`},{label:`Hours, minutes of a time`,f:`=HOUR(B5)   =MINUTE(B5)`},{label:`Across midnight`,f:`=MOD(C5-B5,1)`},{label:`MB to GB`,f:`=B2/1000`}],pitfalls:[`Adding 10 to a time adds 10 days, not 10 minutes.`,`A duration shown as 0.0625 is 1.5 hours as a day fraction: multiply by 24 or format it as a time.`,`Floating-point error at band edges: ROUND(x*24,6) before a lookup.`],techniques:[`Time arithmetic (durations, x24, /1440, /86400)`,`Unit conversion (MB to GB, seconds/minutes to day fractions)`]},{id:`capacity`,group:`Model and optimise`,title:`Capacity, shortages, leftovers and block counts (MIN, MAX, ROUNDUP)`,spot:`Sales limited by stock, seats limited by capacity, overflow turned away, or a count of packs, trucks or blocks with the cheaper option chosen.`,cues:[`capacity`,`seats`,`limited`,`cannot exceed`,`at most`,`turned away`,`rejected`,`shortage`,`lost sales`,`leftover`,`unsold`,`surplus`,`overflow`,`trucks`,`blocks`,`packs of`,`boxes`,`cheaper`,`whichever is cheaper`,`whichever is lower`,`minimum of`,`enough`],steps:[`What actually happens is the smaller of what is wanted and what is available: MIN(demand, capacity).`,`What is left over or turned away can never be negative: MAX(0, difference).`,`Counting containers (trucks, packs, blocks of hours) always rounds up: ROUNDUP(amount / size, 0).`,`Cheaper of two pricing options: MIN(option 1, option 2), each computed in its own cell first.`,`Flows over periods: end = start + in - out, and the next period starts from this end.`],formulas:[{label:`Units sold`,f:`=MIN(B5,C5)`,where:`B5 demand, C5 stock`},{label:`Unsold stock`,f:`=MAX(0,C5-B5)`},{label:`Lost sales`,f:`=MAX(0,B5-C5)`},{label:`Trucks needed`,f:`=ROUNDUP(B5/$C$2,0)`,where:`C2 truck capacity`},{label:`Blocks of hours needed`,f:`=ROUNDUP((C5-B5)*24/$F$2,0)`,where:`F2 hours per block`},{label:`Cheaper option`,f:`=MIN(G5,H5)`,where:`G5 hourly charge, H5 block charge`},{label:`End-of-period stock`,f:`=B5+C5-D5`,where:`start + arrivals - departures`}],pitfalls:[`ROUND instead of ROUNDUP undercounts trucks or blocks.`,`Forgetting MAX(0, ...) gives negative leftovers or rejections.`,`Within one period, apply the steps in the order the story gives them (arrive, cap, serve, leave).`],techniques:[`Capacity and flow-balance logic with MIN/MAX`,`ROUNDUP block counts and MIN for the cheaper option`]},{id:`trend`,group:`Model and optimise`,title:`Straight-line forecast (TREND, trendline equation)`,spot:`Past values over time (or against another driver) and you must predict a future value or state the equation of the line.`,cues:[`forecast`,`trend`,`predict`,`prediction`,`projection`,`project`,`straight line`,`straight-line`,`linear`,`trendline`,`equation`,`next year`,`extrapolate`,`regression`,`history`,`historical`],steps:[`Known y = the values to forecast (sales); known x = the driver (year, month number, deposits).`,`Write =TREND(known_y, known_x, new_x) and anchor the history ranges so the formula fills to later periods.`,`For the equation: insert a scatter chart of the history, add a linear trendline, tick Display Equation on chart (y = mx + c).`,`FORECAST.LINEAR(new_x, known_y, known_x) gives the same number.`],formulas:[{label:`Forecast, fill down`,f:`=TREND($B$2:$B$11,$A$2:$A$11,A12)`,where:`B2:B11 history, A2:A11 periods, A12 new period`},{label:`Fill across several series`,f:`=TREND(E$27:E$36,$C$27:$C$36,$C37)`,where:`each column a series, C the driver`},{label:`Same with FORECAST.LINEAR`,f:`=FORECAST.LINEAR(A12,$B$2:$B$11,$A$2:$A$11)`}],pitfalls:[`TREND takes y first, then x; swapping them gives a wrong line.`,`Unanchored history ranges slide down as you fill, giving a different line in each row.`,`AutoFill on two numbers extends a straight line but stores values, not formulas.`],techniques:[`Linear trend forecasting (TREND / trendline)`]},{id:`anchoring`,group:`Model and optimise`,title:`Fill-safe formulas and two-way grids ($ anchoring)`,spot:`One formula must be filled down a column, across a row, or over a whole grid (price by quantity, a ready reckoner).`,cues:[`fill down`,`fill across`,`fill right`,`copy down`,`copy the formula`,`grid`,`ready reckoner`,`for each combination`,`every row`,`each row`,`each column`,`table of values`,`mixed reference`],steps:[`Parameters used everywhere: lock both ($B$2).`,`Grid with row labels in a column and column labels in a row: lock the column of the row label ($A5) and the row of the column label (B$4).`,`Press F4 while the cursor is in a reference to cycle B2 > $B$2 > B$2 > $B2.`,`Test: fill the formula, then click a far cell and check it still points at the right inputs.`],formulas:[{label:`Fixed parameter`,f:`=B5*$B$2`},{label:`Two-way grid`,f:`=$A5*B$4`,where:`A5:A20 quantities, B4:H4 prices`},{label:`Ratio fill down and across`,f:`=$C9/E9`}],pitfalls:[`A missing $ gives the right answer in the first cell and wrong answers after filling. Markers check the anchors.`,`Over-anchoring ($A$5) makes every row reuse row 5.`],techniques:[`Absolute/mixed references so formulas fill down/right`]},{id:`goal-seek`,group:`Model and optimise`,title:`Find the input that hits a target (Goal Seek)`,spot:`One input must be found so that one output equals a given number: break-even price, latest finish time for a budget, required rate.`,cues:[`break-even`,`breakeven`,`break even`,`goal seek`,`so that`,`such that`,`required to`,`needed to`,`target`,`exactly`,`what value`,`what price`,`latest`,`how long can`,`how many must`,`equal to`,`zero profit`],steps:[`Make sure the output is a formula that depends on the input cell, and the input cell holds a typed value.`,`Data > What-If Analysis > Goal Seek.`,`Set cell: the output formula. To value: the target number. By changing cell: the input.`,`OK, then check the result and plug it back in. Record all three settings and the answer.`,`With step functions (bands, ROUNDUP), type a starting value close to the expected answer first.`],formulas:[{label:`Break-even units (closed form check)`,f:`=D5/((1-C5)*B5)`,where:`D5 fixed cost, C5 cost ratio, B5 price`}],tool:[`Data > What-If Analysis > Goal Seek`,`Set cell: output formula (e.g. D20 profit)`,`To value: target (e.g. 0)`,`By changing cell: input value (e.g. B4 price)`],pitfalls:[`The changing cell must not contain a formula.`,`Goal Seek finds one solution near the start value; for a best (max/min) value use Solver.`,`If a time is the answer, format the changing cell as hh:mm:ss before reporting.`],answer:`Set cell D20 to value 0 by changing B4; result B4 = 12.35.`,techniques:[`Goal Seek`]},{id:`solver`,group:`Model and optimise`,title:`Optimise with Solver (maximise or minimise under constraints)`,spot:`Choose several quantities, shares or prices to get the largest profit or lowest cost while respecting limits.`,cues:[`maximise`,`maximize`,`minimise`,`minimize`,`maximum profit`,`minimum cost`,`optimal`,`optimum`,`best mix`,`how many of each`,`allocate`,`allocation`,`budget`,`subject to`,`constraint`,`constraints`,`whole number`,`whole numbers`,`integer`,`solver`,`cheapest combination`,`largest`,`lowest cost`,`at least`,`no more than`],steps:[`Decision cells: one cell per quantity to choose, holding a typed start value (0 or 1).`,`Objective: one formula cell (usually SUMPRODUCT of decisions and unit profits or costs).`,`Constraints: for each limit, a formula cell for the used amount next to the limit cell (e.g. hours used <= hours available).`,`Data > Solver: Set Objective, Max or Min, By Changing the decision cells.`,`Add constraints as range comparisons (H5:H8 <= J5:J8), plus int for whole numbers.`,`Tick Make Unconstrained Variables Non-Negative. Engine: Simplex LP if the model is linear.`,`Solve, Keep Solver Solution, then record the settings and the optimal values.`],formulas:[{label:`Objective (profit)`,f:`=SUMPRODUCT(B4:D4,B5:D5)`,where:`B4:D4 decisions, B5:D5 unit profits`},{label:`Resource used, fill down`,f:`=SUMPRODUCT($B$4:$D$4,B8:D8)`,where:`B8:D8 resource per unit`},{label:`Remainder share as a formula`,f:`=1-SUM(B4:C4)`,where:`keeps shares summing to 100% without an extra constraint`}],tool:[`Data > Solver`,`Set Objective: profit cell; To: Max (or Min for cost)`,`By Changing Variable Cells: decision range, e.g. $B$4:$D$4`,`Subject to: $H$8:$H$10 <= $J$8:$J$10 ; $B$4:$D$4 = integer (if whole numbers) ; other limits as ranges`,`Make Unconstrained Variables Non-Negative: ticked`,`Solving Method: Simplex LP (linear); GRG Nonlinear (smooth non-linear); Evolutionary (IF, lookups, MIN/MAX of decisions)`,`Options > Integer Optimality (%) = 0 for integer models`],pitfalls:[`"Linearity conditions are not satisfied": the model has IF, VLOOKUP, MIN/MAX or decision x decision. Fix the band the answer must be in (replace the lookup by that band's rate) and confirm the answer stays in it, or switch engine.`,`Changing cells must be values, not formulas.`,`Integer Optimality left at 1% can stop short of the true integer optimum.`,`GRG can stop at a local optimum: re-run from a different start.`],answer:`Objective: max $D$20. Changing: $B$4:$D$4. Constraints: $H$8:$H$10 <= $J$8:$J$10, $B$4:$D$4 = integer, non-negative. Engine: Simplex LP. Optimal: B4 = 12, C4 = 0, D4 = 30, profit $4,560.`,techniques:[`Solver optimisation (objective, changing cells, constraints)`,`Integer constraints in Solver`,`Linearising a model for Solver (fix step-lookups, choose engine)`]},{id:`what-if`,group:`Model and optimise`,title:`Scenarios and sensitivity (Data Table on a model)`,spot:`Show how an output changes as one or two inputs take a list of values, or compare named scenarios.`,cues:[`what if`,`what-if`,`sensitivity`,`scenario`,`scenarios`,`for each value`,`for each of`,`different prices`,`different values`,`vary`,`varies`,`compare`,`two-way table`,`data table`,`range of values`,`how does`,`how would`],steps:[`One input: list its values down a column; one cell up and one to the right, link to the output (=D20). Several outputs can sit across that top row.`,`Select the block (values plus the formula row) and run Data > What-If Analysis > Data Table.`,`One input down a column: Column input cell = the model's input cell; Row input cell empty.`,`Two inputs: output link in the top-left corner, one input's values across the top row, the other's down the first column; set both Row and Column input cells.`,`Read the table, then answer the question in words (which value is best, where it crosses zero).`],formulas:[{label:`Top-row link to the output`,f:`=D20`},{label:`Best value from a one-way table`,f:`=INDEX(A6:A15,MATCH(MAX(B6:B15),B6:B15,0))`,where:`A input values, B results`}],tool:[`Select the whole block (input values plus the formula row/column)`,`Data > What-If Analysis > Data Table`,`Row input cell: the input whose values run across the top (blank for a column table)`,`Column input cell: the input whose values run down the side`],pitfalls:[`The input cells must be on the same sheet as the table.`,`Selecting only the values (not the formula row) gives an error or an empty table.`,`Large tables are slow: File > Options > Formulas > Automatic except for data tables, then F9.`],techniques:[`What-if / scenario analysis by changing inputs`]},{id:`interpret`,group:`Model and optimise`,title:`Written answers: explain, compare, recommend`,spot:`A part asks you to explain a result, compare two options, recommend a decision or say whether a change is worth it.`,cues:[`explain`,`comment`,`recommend`,`recommendation`,`should`,`why`,`justify`,`interpret`,`discuss`,`advise`,`is it worth`,`worthwhile`,`would you`,`describe`,`state`,`conclude`,`insight`],steps:[`Answer the question in the first words: Yes / No / Option B is better.`,`Quote the numbers from your model with units (average profit $215 vs $198 over 1,000 replications).`,`Give the reason: the driver behind the difference (capacity binds, the discount drops at 500, utilisation near 100%).`,`Add one assumption or limitation if relevant (simulation results vary; the table assumes ...).`,`Keep it to 2-4 sentences in the cell or text box the template gives.`],formulas:[],pitfalls:[`A number without a conclusion earns little: say what it means for the decision.`,`For simulations, quote the average and how many replications it came from, not a single run.`],answer:`Yes. With the larger lounge average daily revenue rises from $1,820 to $1,905 (1,000 replications each), because fewer passengers are turned away. Beyond 60 places the gain stops: the buses' seats, not the lounge, become the limit.`,techniques:[`Written interpretation of model results`]},{id:`tvm`,group:`Finance`,title:`Loans, savings and investment value (PMT, PV, FV, RATE, NPER, NPV, IRR)`,spot:`Repayments on a loan, savings growing to a goal, a lump sum versus a payment stream, or whether a project is worth it.`,cues:`loan.instalment.installment.monthly payment.repayment.mortgage.interest.interest rate.annual rate.compounded.present value.future value.lump sum.npv.net present value.irr.internal rate.discount rate.worth today.annuity.savings.retirement.invest.investment.cash flow.cash flows.payback`.split(`.`),steps:[`Match the rate to the period: annual rate/12 for months, and periods = years*12.`,`Sign convention: money you receive is +, money you pay is -. PMT on a positive loan returns a negative payment.`,`Payments at the start of each period: type = 1 (last argument).`,`NPV discounts its first value by one period: put the time-0 cash flow outside, NPV(rate, CF1:CFn) + CF0.`,`IRR takes the whole stream including time 0.`,`Lump sum vs payments: compare the lump sum with the PV of the payments at the given rate.`],formulas:[{label:`Monthly loan payment`,f:`=PMT(B2/12,B3*12,B4)`,where:`B2 annual rate, B3 years, B4 loan (returns negative)`},{label:`Payment with a balloon`,f:`=PMT(5%/12,60,140000,-10000)`},{label:`PV of payments at the start of each month`,f:`=PV(3%/12,9,-3500,-600,1)`},{label:`FV of a deposit plus yearly top-ups`,f:`=FV(6.5%,10,-8000,-50000)`},{label:`Rate needed`,f:`=RATE(10,-8000,-50000,250000)`},{label:`Periods needed`,f:`=NPER(8%,-8000,-50000,250000)`},{label:`NPV with an investment today`,f:`=NPV(B10,C15:C24)+C14`,where:`C14 time-0 flow (negative), C15:C24 years 1-10`},{label:`IRR`,f:`=IRR(C14:C24)`},{label:`PV of one cash flow by hand`,f:`=M14/(1+L$10)^L14`},{label:`Monthly stream vs lump sum`,f:`=PV(B2/12,B3,-B4)-B5`,where:`B2 annual rate, B3 number of months, B4 monthly amount, B5 lump sum today; positive means the stream is worth more`}],pitfalls:[`Annual rate with monthly periods (or the reverse) gives a wildly wrong answer.`,`Including the time-0 flow inside NPV discounts it one period too many.`,`RATE and NPER need opposite signs on money in and money out, else #NUM!.`],techniques:[`Time value of money (NPV vs lump sum)`]}],i=[{id:`discrete-rv`,group:`Simulation`,title:`Discrete random variable from a probability table (CRF + LOOKUP(RAND()))`,spot:`A table of values with probabilities or frequencies (customers per interval, group size, demand) and you must draw a random value from it.`,cues:[`probability distribution`,`with probability`,`probabilities`,`probability`,`frequency`,`frequencies`,`chance`,`historical`,`cumulative`,`crf`,`cumulative probability`,`discrete`,`per interval`,`group size`,`number of customers`,`number of visitors`,`percent of`,`distribution table`],steps:[`List the values in ascending order with their probabilities (from frequencies: frequency / SUM(frequencies)).`,`Build the cumulative (CRF) column as LOWER bounds: the first row is 0, each next row adds the probability above it.`,`Draw with =LOOKUP(RAND(), CRF column, value column), both ranges anchored.`,`Check the probabilities sum to 1 and the last CRF value is 1 minus the last probability.`,`If the question gives pre-drawn random numbers, use that cell instead of RAND().`],formulas:[{label:`Probability from frequency`,f:`=B2/SUM($B$2:$B$6)`},{label:`CRF first row`,f:`0`},{label:`CRF next rows, fill down`,f:`=C2+B2`,where:`C2 CRF above, B2 probability above`},{label:`CRF as a running SUM`,f:`=SUM($L$6:L6)`},{label:`Draw a value`,f:`=LOOKUP(RAND(),$C$2:$C$6,$A$2:$A$6)`,where:`C CRF lower bounds, A values`},{label:`Same with VLOOKUP`,f:`=VLOOKUP(RAND(),$C$2:$D$6,2,TRUE)`,where:`C CRF, D values to its right`}],pitfalls:[`Starting the CRF at the first probability instead of 0 shifts every value by one row.`,`Probabilities that do not add up to 1 leave a gap or overlap at the top.`,`Unanchored ranges slide as you fill down.`],techniques:[`Discrete random variable via CRF table + LOOKUP(RAND())`,`Building lookup/step tables (lower bounds, increments, CRF)`]},{id:`continuous-rv`,group:`Simulation`,title:`Random draws: uniform, normal, exponential, binomial, yes/no`,spot:`The question names a distribution: uniformly between a and b, normally distributed with mean and sd, exponential gaps with a mean, n trials each with chance p.`,cues:`uniformly.uniform.equally likely.between.normally distributed.normal distribution.normal.mean.standard deviation.exponential.exponentially.inter-arrival.interarrival.time between arrivals.binomial.each of.independently.probability p.never below.at least 1 minute.random.randomly.at random.coin.dice.die`.split(`.`),steps:[`Pick the generator for the named distribution (list below).`,`Convert units first: a mean of 3 minutes added to a clock time is 3/1440.`,`Add a floor if the question says "never below": MAX(floor, draw).`,`Round to whole units only when the quantity is a count: ROUND(draw,0).`,`Guard binomial draws when n can be 0: IF(n>0, CRITBINOM(n,p,RAND()), 0).`],formulas:[{label:`Uniform a to b (continuous)`,f:`=$B$1+RAND()*($B$2-$B$1)`},{label:`Uniform whole number a to b`,f:`=RANDBETWEEN(1,6)`},{label:`Normal`,f:`=NORMINV(RAND(),$B$1,$B$2)`,where:`B1 mean, B2 standard deviation`},{label:`Normal with a floor of 1 minute`,f:`=MAX(1/1440,NORMINV(RAND(),$B$1/1440,$B$2/1440))`},{label:`Normal count, rounded, never negative`,f:`=MAX(0,ROUND(NORMINV(RAND(),$B$1,$B$2),0))`},{label:`Exponential (mean m)`,f:`=-$B$1*LN(RAND())`,where:`=-$B$1*LN(1-RAND()) is the same distribution`},{label:`Exponential gap in minutes as a time`,f:`=-$B$1/1440*LN(RAND())`},{label:`Binomial: successes out of n`,f:`=CRITBINOM($B$1,$B$2,RAND())`,where:`B1 n, B2 p; BINOM.INV is the newer name`},{label:`Binomial guarded for n = 0`,f:`=IF(C5>0,CRITBINOM(C5,D5,RAND()),0)`},{label:`Yes/no event with chance p`,f:`=IF(RAND()<$B$1,1,0)`}],pitfalls:[`NORMINV can return negative values: floor it with MAX if the quantity cannot be negative.`,`Mixing minutes with day fractions: an exponential mean of 4 minutes added to 09:00 must be 4/1440.`,`Each RAND() is a separate draw: two RAND() calls in one formula are two different numbers.`],techniques:[`Uniform random draws (RANDBETWEEN position, a+RAND()*(b-a))`,`Normal random variable (NORMINV) with a floor via MAX`,`Exponential inter-arrival times (-mean*LN(RAND()))`,`Binomial random variable (CRITBINOM / BINOM.INV)`,`Bernoulli event (RAND() < p)`]},{id:`resample`,group:`Simulation`,title:`Random picks and resampling from data`,spot:`Draw from observed data rather than a named distribution, or pick a random row, door, slot or item.`,cues:[`resample`,`resampling`,`from the data`,`observed`,`sample of`,`past records`,`records`,`pick at random`,`randomly selected`,`random row`,`randomly chosen`,`percentile`,`empirical`],steps:[`Continuous values from data: PERCENTILE(data, RAND()).`,`Discrete values from data (any one of the n observations): SMALL(data, RANDBETWEEN(1,n)) or INDEX(data, RANDBETWEEN(1,n)).`,`A random cell in a table: INDEX(table, RANDBETWEEN(1,rows), RANDBETWEEN(1,cols)).`],formulas:[{label:`Continuous resample`,f:`=PERCENTILE($C$12:$C$997,RAND())`},{label:`Discrete resample`,f:`=SMALL($C$12:$C$997,RANDBETWEEN(1,$C$8))`,where:`C8 number of observations (=COUNT(...))`},{label:`Random row of a list`,f:`=INDEX($A$2:$A$41,RANDBETWEEN(1,40))`},{label:`Random cell of a grid`,f:`=INDEX($L$15:$M$18,RANDBETWEEN(1,4),RANDBETWEEN(1,2))`}],pitfalls:[`PERCENTILE interpolates between observations; use SMALL or INDEX when only observed values are allowed.`,`The n in RANDBETWEEN must match the number of data values.`],techniques:[`Uniform random draws (RANDBETWEEN position, a+RAND()*(b-a))`]},{id:`replications`,group:`Simulation`,title:`Replications and averages with a Data Table (Monte Carlo)`,spot:`Run the random model many times (100, 1,000 replications) and report an average, a probability or a comparison.`,cues:[`replication`,`replications`,`replicate`,`simulate`,`simulation`,`simulated`,`runs`,`trials`,`100 times`,`1000 times`,`1,000 times`,`120 times`,`on average`,`average over`,`estimate`,`estimated`,`probability that`,`how often`,`expected`,`monte carlo`,`data table`],steps:[`Build ONE replication of the model with RAND() inputs, and one output cell (profit, average wait, stock left).`,`Put trial numbers 1..N down a column. In the row above, one cell to the right, link to the output (=H29). Several outputs can sit across that row.`,`Select the whole block (trial numbers plus the link row) > Data > What-If Analysis > Data Table.`,`Row input cell: empty. Column input cell: any BLANK cell that the model does not use.`,`Summarise the column: AVERAGE for the mean, COUNTIF(...)/N for a probability, STDEV for spread.`,`To compare a parameter (pen size 60 vs 150): change it, press F9, read the new average; or build a two-way table with the parameter values across the top and the parameter cell as Row input.`,`Report the method (N replications, the table range, input cells) and the average. Answers are accepted within a range.`],formulas:[{label:`Link above the table`,f:`=H29`,where:`H29 the model's output for one run`},{label:`Average of the replications`,f:`=AVERAGE(D36:D155)`},{label:`Probability of an event`,f:`=COUNTIF(D36:D155,">0")/COUNT(D36:D155)`},{label:`Spread`,f:`=STDEV(D36:D155)`},{label:`Two-way: parameter across the top`,f:`corner =H29; row input cell = parameter cell; column input cell = blank cell`}],tool:[`Select trial numbers plus the link row, e.g. C35:D155`,`Data > What-If Analysis > Data Table`,`Row input cell: (empty)`,`Column input cell: a blank unused cell, e.g. $L$30`,`If it recalculates slowly: Formulas > Calculation Options > Automatic Except for Data Tables, then F9`],pitfalls:[`Using a model input as the Column input cell overwrites it with 1, 2, 3 ...: it must be blank and unused.`,`Averaging the inputs and feeding them into the model is wrong when the output is non-linear (MIN, MAX, IF): replicate the output itself.`,`The link row (D35) is the current run, not a replication: average only the table body.`,`Simulated averages change on every F9; quote them as estimates.`],answer:`120 replications: Data Table on C35:D155, Row input blank, Column input L30, link D35 = H31. Average left in pen = AVERAGE(D36:D155), about 7.9 (varies by run).`,techniques:[`Data Table for Monte Carlo replications (blank input cell)`,`Replicate the full output (E[f(X)] is not f(E[X]))`]},{id:`flows`,group:`Simulation`,title:`Stock and flows between locations (SUMIF departures and arrivals)`,spot:`Bikes, umbrellas or stock move between locations along routes; count departures and arrivals, end stock, surplus and rebalancing cost.`,cues:[`locations`,`stations`,`route`,`routes`,`origin`,`destination`,`departures`,`arrivals`,`remaining`,`end of day`,`end-of-period`,`stock`,`inventory`,`rebalancing`,`rebalance`,`surplus`,`moved back`,`carried over`,`bikes`,`trips`],steps:[`One row per route: origin, destination, potential riders n, probability p, simulated trips (CRITBINOM).`,`Departures from a location: SUMIF over the origin column. Arrivals: SUMIF over the destination column.`,`End stock = start - departures + arrivals.`,`Surplus over a target: MAX(0, end - target); shortage: MAX(0, target - end).`,`Revenue from a fare matrix: INDEX(fares, origin no, destination no) times trips, summed with SUMPRODUCT.`,`Replicate profit (not average stocks) with a Data Table.`],formulas:[{label:`Trips on a route`,f:`=IF(C5>0,CRITBINOM(C5,D5,RAND()),0)`},{label:`Departures from a location`,f:`=SUMIF($A$5:$A$16,G5,$E$5:$E$16)`,where:`A origins, G5 location, E trips`},{label:`Arrivals at a location`,f:`=SUMIF($B$5:$B$16,G5,$E$5:$E$16)`,where:`B destinations`},{label:`End stock`,f:`=H5-I5+J5`,where:`start - departures + arrivals`},{label:`Surplus to move back`,f:`=MAX(0,K5-$L$2)`},{label:`Fare for a route`,f:`=INDEX($N$5:$Q$8,A5,B5)`,where:`A5, B5 location numbers`}],pitfalls:[`Swapping origin and destination in SUMIF flips departures and arrivals.`,`Cost on MAX(0, ...) is non-linear: averaging stocks first understates it.`,`Check the simulated average trips against n x p.`],techniques:[`Conditional aggregation (SUMIF/COUNTIF with criteria strings)`,`Binomial random variable (CRITBINOM / BINOM.INV)`,`INDEX by row/column number (matrix lookup)`]},{id:`single-server`,group:`Queues`,title:`Single-server queue (arrival, start, end, wait)`,spot:`Customers arrive one at a time to one counter, cashier or machine; build the row-by-row queue and measure waiting.`,cues:[`queue`,`queues`,`queueing`,`queuing`,`arrive`,`arrives`,`arrival`,`arrivals`,`service time`,`served`,`serve`,`counter`,`cashier`,`one server`,`single server`,`single`,`first come`,`first-come`,`waiting time`,`wait`,`waits`,`idle`,`start of service`,`end of service`],steps:[`Columns: customer, inter-arrival time, arrival time, service time, service start, service end, wait, time in system.`,`Times are day fractions: convert minutes with /1440 (or draw them already divided).`,`First customer: arrival = opening time + gap; start = arrival.`,`Next customers: arrival = previous arrival + gap; start = MAX(arrival, previous end); end = start + service.`,`Wait = start - arrival; time in system = end - arrival; server idle = start - previous end.`,`Fill the second row down, then summarise (see the queue measures pattern).`],formulas:[{label:`Arrival time`,f:`=E14+C15`,where:`E14 previous arrival, C15 gap`},{label:`Service start`,f:`=MAX(E15,G14)`,where:`E15 arrival, G14 previous end`},{label:`Service end`,f:`=F15+D15`,where:`F15 start, D15 service time`},{label:`Wait`,f:`=F15-E15`},{label:`Time in system`,f:`=G15-E15`},{label:`Exponential gap as a time`,f:`=-$C$4*LN(RAND())`,where:`C4 mean gap already as a time (e.g. 0:04:48)`}],pitfalls:[`Adding minutes to clock times without /1440.`,`Start = arrival (without MAX) ignores the queue.`,`Format time columns hh:mm:ss and wait columns hh:mm:ss or as minutes (*1440).`],techniques:[`Queue performance measures (weighted wait, % within threshold, utilisation)`,`Exponential inter-arrival times (-mean*LN(RAND()))`],examples:[`w6-single-server-booth`]},{id:`multi-server`,group:`Queues`,title:`Several servers sharing one queue (COUNTIF + LARGE)`,spot:`Two or more counters, stations or tellers serve one shared line; find when each customer starts.`,cues:[`servers`,`stations`,`counters`,`tellers`,`two counters`,`sharing one queue`,`several counters`,`several stations`,`two servers`,`three servers`,`several`,`c servers`,`pooled`,`shared queue`,`one queue`,`single line`,`number in system`,`in the system`,`next free`,`multi-server`,`multiple servers`],steps:[`Number in system when this customer arrives: COUNTIF of earlier END times greater than this arrival.`,`If that number is less than c (servers free), service starts on arrival.`,`Otherwise service starts at the c-th largest earlier end time: LARGE(earlier ends, c).`,`End = start + service; wait = start - arrival.`,`The expanding ranges ($G$14:G14) grow by one row as you fill down.`],formulas:[{label:`Number in system at arrival`,f:`=COUNTIF($G$14:G14,">"&E15)`,where:`G end times above this row, E15 arrival`},{label:`Service start with c servers`,f:`=IF(J15<$G$4,E15,LARGE($G$14:G14,$G$4))`,where:`J15 number in system, G4 servers c`},{label:`Utilisation with c servers`,f:`=SUM(D15:D99)/(G4*(G8-G14))`,where:`D service times, G8 last end, G14 opening time`}],pitfalls:[`MAX(arrival, LARGE(...)) fails for the first c customers: LARGE returns #NUM! when fewer than c end times exist. Keep the IF.`,`The COUNTIF criterion needs ">"&cell, not ">E15".`,`Anchor only the top of the expanding range: $G$14:G14.`],techniques:[`Multi-server queue (COUNTIF system length + LARGE c-th end time)`]},{id:`queue-measures`,group:`Queues`,title:`Queue performance measures (average wait, % served quickly, utilisation)`,spot:`Report how well the queue performs: average or maximum wait, share waiting under a threshold, server utilisation, average number in system.`,cues:[`average wait`,`average waiting`,`mean wait`,`percentage of customers`,`proportion of customers`,`share of customers`,`within`,`more than 5 minutes`,`less than`,`utilisation`,`utilization`,`busy`,`idle time`,`longest wait`,`maximum wait`,`average number`,`served within`,`service level`,`per passenger`,`weighted`],steps:[`Average wait in minutes: AVERAGE(wait column) * 1440.`,`Share waiting at most t minutes: COUNTIF(wait, "<="&t/1440) / COUNT(wait).`,`Utilisation: total service time / (number of servers x time span).`,`Groups of different sizes: weight the wait by group size with SUMPRODUCT / SUM.`,`Compare designs with replications (Data Table) and say which performs better.`],formulas:[{label:`Average wait (minutes)`,f:`=AVERAGE(H15:H99)*1440`},{label:`Share served within 5 minutes`,f:`=COUNTIF(H15:H99,"<="&5/1440)/COUNT(H15:H99)`},{label:`Share waiting more than t (cell)`,f:`=COUNTIF(H15:H99,">"&$B$3/1440)/COUNT(H15:H99)`,where:`B3 threshold in minutes`},{label:`Per-passenger average wait`,f:`=SUMPRODUCT(H15:H99,C15:C99)/SUM(C15:C99)`,where:`C group sizes`},{label:`Utilisation (one server)`,f:`=SUM(D15:D99)/(MAX(G15:G99)-$E$14)`,where:`E14 opening time`},{label:`Average number in system`,f:`=SUMPRODUCT(((J15:J98+1)+J16:J99)/2,C16:C99)/(E8-E14)`,where:`course formula: J number in system at arrival, C inter-arrival gaps, E8 =MAX(E14:E99) last arrival, E14 opening time`},{label:`Longest wait`,f:`=MAX(H15:H99)`}],pitfalls:[`A threshold in minutes must be divided by 1440 when the waits are times.`,`Plain AVERAGE over groups gives a per-group, not per-person, wait.`,`Utilisation above 100% means the formula counts something twice (e.g. reneged customers).`],techniques:[`Queue performance measures (weighted wait, % within threshold, utilisation)`,`Conditional aggregation (SUMIF/COUNTIF with criteria strings)`]},{id:`balk-renege`,group:`Queues`,title:`Balking and reneging (customers who leave)`,spot:`Customers refuse to join when the line is too long (balk) or leave after waiting too long (renege).`,cues:[`balk`,`balks`,`balking`,`customers balk`,`balk if`,`balk limit`,`renege after`,`renege limit`,`renege`,`reneges`,`reneging`,`leave if`,`leaves if`,`gives up`,`give up`,`queue too long`,`refuse to join`,`will not join`,`patience`,`tolerate`,`turned away`],steps:[`System length at arrival L: COUNTIF of earlier end times greater than this arrival.`,`Balk: if L is above the balk limit, the customer leaves: potential start = "".`,`Otherwise the c-server rule gives the potential start; potential wait = start - arrival.`,`Renege: if the potential wait exceeds the limit, no actual start ("").`,`End time: served customers end at start + service; renegers leave at arrival + limit (BR-M).`,`Proportions: balk = (arrivals - joined) / arrivals; renege = (joined - served) / joined.`],formulas:[{label:`System length at arrival`,f:`=COUNTIF($I$14:I14,">"&E15)`},{label:`Potential start (balk + c servers)`,f:`=IF(L15>F$4,"",IF(L15>=I$4,LARGE(I$14:I14,I$4),$E15))`,where:`F4 balk limit, I4 servers`},{label:`Potential wait`,f:`=IF(F15="","",F15-E15)`},{label:`Actual start (renege)`,f:`=IF(F15="","",IF(G15>$G$4,"",F15))`,where:`G4 renege limit as a time`},{label:`End time (BR-M)`,f:`=IF(F15="","",IF(G15>$G$4,E15+$G$4,H15+D15))`},{label:`Balk proportion`,f:`=(COUNT(E15:E99)-COUNT(F15:F99))/COUNT(E15:E99)`},{label:`Renege proportion`,f:`=(COUNT(F15:F99)-COUNT(H15:H99))/COUNT(F15:F99)`}],pitfalls:[`Giving renegers a full service end time inflates the system length and makes later customers balk.`,`COUNT and AVERAGE skip "" cells, so use "" (not 0) for customers who left.`],techniques:[],examples:[`w6-repair-balk-renege`]},{id:`batch-queue`,group:`Queues`,title:`Time-stepped batch service (buses, trams, shuttles each interval)`,spot:`A vehicle leaves every fixed interval with limited seats; people arrive per interval, wait in a limited area, board, are left behind or turned away.`,cues:[`every 6 minutes`,`every 10 minutes`,`every 15 minutes`,`bus`,`buses`,`shuttle`,`tram`,`trams`,`departs`,`departure`,`scheduled`,`fixed interval`,`fixed intervals`,`batch`,`per interval`,`left behind`,`holding pen`,`lounge`,`waiting area`,`boarded`,`board`,`seats`],steps:[`One row per departure; row 0 holds the starting state (nobody waiting).`,`Arrivals this interval: LOOKUP(RAND(), CRF, values).`,`Waiting = arrivals + left behind by the previous vehicle, capped by the waiting-area size: MIN(..., cap).`,`Turned away = MAX(arrivals + left behind - cap, 0).`,`Boarded = MIN(seats, waiting); left behind = waiting - boarded.`,`Revenue = boarded x fare. Departure time = scheduled time + boarded x loading seconds / 86400.`,`Summaries over all rows, then replicate with a Data Table.`],formulas:[{label:`Arrivals in the interval`,f:`=LOOKUP(RAND(),$N$6:$N$9,$M$6:$M$9)`},{label:`In the waiting area`,f:`=MIN(D7+G6,$G$2)`,where:`D7 arrivals, G6 left behind last time, G2 capacity`},{label:`Boarded`,f:`=MIN($D$2,E7)`,where:`D2 seats`},{label:`Left behind`,f:`=E7-F7`},{label:`Turned away`,f:`=MAX(D7+G6-$G$2,0)`},{label:`Actual departure time`,f:`=C7+F7*INDEX($L$15:$M$18,RANDBETWEEN(1,4),RANDBETWEEN(1,2))/86400`,where:`C7 scheduled time; loading seconds per rider from a table`}],pitfalls:[`Referencing this row's left-behind inside this row's waiting formula is circular: use the row above.`,`Seconds added to a clock time must be divided by 86400.`,`Count the turned-away from arrivals plus those already waiting, before the cap.`],techniques:[`Time-stepped batch-service queue simulation`]},{id:`filters`,group:`Data tools`,title:`Filtering and extracting records (AutoFilter, Advanced Filter, criteria)`,spot:`List or count the records that meet conditions, extract them to another place, or get unique values.`,cues:[`filter`,`filters`,`autofilter`,`advanced filter`,`criteria`,`criteria range`,`extract`,`list the`,`records`,`show only`,`copy to another location`,`unique`,`unique records`,`meets`,`matching`],steps:[`Criteria range: copy the list's headers exactly; put conditions under them.`,`Same row = AND; separate rows = OR. A blank criteria cell means any value.`,`Exact text: ="=North" (plain North means "begins with North"). Numbers: >=24, <>0.`,`Data > Advanced: List range (with headers), Criteria range (headers + condition rows only), Filter in place or Copy to another location, Unique records only if asked.`,`A count or total of the same records by formula: COUNTIF, SUMIF or SUMPRODUCT with conditions.`],formulas:[{label:`Exact text criterion`,f:`="=North"`},{label:`Date criterion from a cell`,f:`=">="&TEXT(H4,"d MMM yyyy")`},{label:`Count with two conditions`,f:`=SUMPRODUCT((B9:B68="North")*(E9:E68>=24))`},{label:`Total with one condition`,f:`=SUMIF(B9:B68,"North",K9:K68)`}],tool:[`Data > Advanced`,`List range: $A$8:$K$68 (headers included)`,`Criteria range: $A$1:$B$2 (headers plus condition rows; no blank row)`,`Action: Filter the list in-place, or Copy to another location: $M$8`,`Unique records only: if asked`],pitfalls:[`A blank row inside the criteria range lets every record through.`,`Header text must match the list exactly (spaces too).`,`Two conditions on the same field on one row need the field header twice (Amount, Amount).`],techniques:[],examples:[`w10-advfilter-and-or`,`w10-advfilter-dates-wildcards`,`w10-advfilter-computed-unique`,`w10-autofilter-number-filters`,`w10-fleet-service-alerts`]},{id:`pivot`,group:`Data tools`,title:`Summaries by category (PivotTable, SUMIF, SUMPRODUCT)`,spot:`Totals, counts or averages broken down by region, month, channel or product; shares of a total.`,cues:[`summarise`,`summarize`,`summary`,`by region`,`by region and`,`revenue by`,`total revenue by`,`by month`,`by channel`,`by product`,`by category`,`total by`,`count by`,`average by`,`pivot`,`pivottable`,`breakdown`,`share of total`,`percentage of total`,`per category`],steps:[`Click inside the list > Insert > PivotTable > New or existing worksheet.`,`Drag the category to Rows (and a second one to Columns if asked), the measure to Values.`,`Value Field Settings: Sum, Count or Average; Show Values As > % of Grand Total for shares.`,`Months from dates: add a helper column =TEXT(date,"yyyy-mm") or =MONTH(date) and use it as the row field.`,`Cross-check one total with SUMIF or SUMPRODUCT.`],formulas:[{label:`Month helper`,f:`=TEXT(C9,"yyyy-mm")`},{label:`Category total`,f:`=SUMIF($B$9:$B$68,M5,$K$9:$K$68)`},{label:`Two-way total by formula`,f:`=SUMPRODUCT(($B$9:$B$68=$M6)*($D$9:$D$68=N$5)*$K$9:$K$68)`}],tool:[`Insert > PivotTable (list range with headers)`,`Rows: category field; Columns: second field (optional)`,`Values: measure, Value Field Settings > Sum / Count / Average`,`Show Values As: % of Grand Total (for shares)`],pitfalls:[`Count of a numeric field when Sum was asked (Excel defaults to Count if a column has blanks or text).`,`Refresh the PivotTable after changing the data.`],techniques:[],examples:[`w10-pivot-orders`,`w10-pivot-month-helper`,`w10-pivot-value-settings`,`w10-sumproduct-region-status`,`w10-room-bookings-report`]}],a=[`Model and optimise`,`Finance`,`Simulation`,`Queues`,`Data tools`],o=[...r,...i],s=e=>` ${e.toLowerCase().replace(/(?<!\d)\.|\.(?!\d)/g,` `).replace(/[^a-z0-9%$<>=.+*/-]+/g,` `).replace(/\s+/g,` `)} `,c=new Map;for(let e of o)for(let t of new Set(e.cues.map(s)))c.set(t,(c.get(t)??0)+1);function l(e,t=o){let n=s(e);if(n.trim().length<2)return[];let r=[];for(let e of t){let t=e.cues.filter(e=>n.includes(s(e)));if(t.length===0)continue;let i=t.reduce((e,t)=>e+t.split(` `).length/(c.get(s(t))??1),0);r.push({pattern:e,score:i,matched:t})}return r.sort((e,t)=>t.score-e.score||t.matched.length-e.matched.length)}var u=e=>`Mock Exam ${e.replace(`mock-`,``).toUpperCase()}`,d=[...e.flatMap(e=>e.questions.map(t=>({ex:t.exercise,source:`${u(e.id)} ${t.id.toUpperCase()}`,marks:t.marks}))),...t.map(e=>({ex:e,source:e.week===`EXAM`?`Exam-style lab`:`${e.week} lab`}))],f=e=>d.find(t=>t.ex.id===e),p=e=>e.replace(/`/g,``),m=e=>e===null?`(blank)`:String(typeof e==`number`?Math.round(e*1e6)/1e6:e),h=(e,t=8)=>{let n=e.slice(0,t).map(([e,t])=>`${e}: ${t}`);return e.length>t&&n.push(`... and ${e.length-t} more cells in the same pattern`),n},g=e=>e.split(`:`)[0];function _(e){let t=e.toolSetup??{};switch(e.tool){case`goalseek`:return[`Data > What-If Analysis > Goal Seek`,`Set cell: ${t.setCell}`,`To value: ${t.toValue}`,`By changing cell: ${t.changingCell}`];case`solver`:{let e=t.constraints??[];return[`Data > Solver`,`Set Objective: ${t.objective}   To: ${t.sense===`max`?`Max`:t.sense===`min`?`Min`:`Value of ${t.valueOf}`}`,`By Changing Variable Cells: ${t.changing}`,...e.map(e=>`Subject to: ${e.lhs} ${e.relation===`int`?`= integer`:e.relation===`bin`?`= binary`:`${e.relation} ${e.rhs}`}`),`Make Unconstrained Variables Non-Negative: ${t.nonNegative===!1?`unticked`:`ticked`}`,`Solving Method: ${t.engine===`grg`?`GRG Nonlinear`:`Simplex LP`}`]}case`datatable`:return[`Select ${t.range}`,`Data > What-If Analysis > Data Table`,`Row input cell: ${t.rowInput??`(empty)`}`,`Column input cell: ${t.colInput??`(empty)`}`];case`advfilter`:return[`Data > Advanced`,`List range: ${t.list}`,`Criteria range: ${t.criteria}`,t.copyTo?`Copy to: ${t.copyTo}`:`Filter the list in place`,`Unique records only: ${t.unique?`yes`:`no`}`];case`pivot`:{let e=t.config??{};return[`Insert > PivotTable from ${t.source} into ${t.target}`,`Rows: ${(e.rows??[]).join(`, `)||`(none)`}`,`Columns: ${(e.columns??[]).join(`, `)||`(none)`}`,...(e.values??[]).map(e=>`Values: ${e.agg} of ${e.field}${e.show&&e.show!==`value`?` shown as ${e.show}`:``}`),...(e.filters??[]).map(e=>`Filter: ${e.field} = ${e.include.join(`, `)}`)]}case`autofilter`:{let e=t.columns??[],n={eq:`=`,ne:`<>`,gt:`>`,ge:`>=`,lt:`<`,le:`<=`};return[`Select ${t.range} > Data > Filter`,...e.map(e=>e.filter.type===`values`?`${e.column}: tick only ${(e.filter.values??[]).join(`, `)}`:`${e.column}: Number Filters > Custom: ${(e.filter.rules??[]).map(e=>`${n[e.op]??e.op} ${e.value}`).join(` ${(e.filter.join??`and`).toUpperCase()} `)}`)]}case`sort`:{let e=t.levels??[];return[`Select ${t.range} > Data > Sort (My data has headers: ${t.headers?`ticked`:`unticked`})`,...e.map((e,t)=>`${t===0?`Sort by`:`Then by`} ${e.column}: ${e.order===`custom`?`Custom List ${e.list}`:e.order===`desc`?`Largest to Smallest / Z to A`:`Smallest to Largest / A to Z`}`)]}default:return Object.keys(t).length?[`${e.tool}: ${JSON.stringify(t)}`]:[]}}function v(e){let t=[];if(e.kind===`vba`&&e.vba)return e.vba.solution.split(`
`);if(e.kind===`explain`)return typeof e.answer==`string`?[e.answer]:[];if(e.kind===`tool`&&t.push(..._(e)),e.solutions)t.push(...h(Object.entries(e.solutions)));else if(e.solution){let n=e.cells.includes(`:`)?` (fill to ${e.cells})`:``;t.push(`${g(e.cells)||`Answer`}${n}: ${e.solution}`)}return e.kind===`value`&&e.answer!==void 0&&!e.solution&&!e.solutions&&(e.answer!==null&&typeof e.answer==`object`?t.push(...h(Object.entries(e.answer).map(([e,t])=>[e,m(t)]))):t.push(`${e.cells}: ${m(e.answer)}`)),e.random&&t.push(`Expected ${e.random.stat===`p`?`share`:e.random.stat} about ${m(e.random.target)} (simulated, varies by run)`),t}function y(e,t=8){let n=new Set(e.examples??[]);return d.filter(t=>n.has(t.ex.id)||(t.ex.techniques??[]).some(t=>e.techniques.includes(t))).sort((e,t)=>Number(n.has(t.ex.id))-Number(n.has(e.ex.id))||t.ex.level-e.ex.level).slice(0,t)}function b(e){let t=e.techniques;return n.papers.flatMap(e=>e.questions.flatMap(n=>n.parts.filter(e=>e.techniques.some(e=>t.includes(e))).map(t=>({paper:e.title,question:n.id.toUpperCase(),label:t.label,marks:t.marks,focus:t.focus}))))}var x=[{id:`sumproduct-receipt-subtotal`,topic:`sumproduct`,question:`A Tiong Bahru bakery receipt lists five items. In D11 compute the subtotal, in D12 the GST at the rate in G2, and in D13 the total payable.`,layout:`Item names in B5:B9, quantities in C5:C9 (2, 1, 3, 6, 2), unit prices in D5:D9 ($4.50, $6.80, $2.20, $1.60, $3.90). GST rate in G2 (9%).`,formulas:[{cell:`D11`,formula:`=SUMPRODUCT(C5:C9,D5:D9)`,note:`quantity x price on each line, added up`},{cell:`D12`,formula:`=D11*G2`},{cell:`D13`,formula:`=D11+D12`}],steps:[`Pair the quantity column with the unit-price column: same rows, same length.`,`D11: =SUMPRODUCT(C5:C9,D5:D9).`,`GST = subtotal x rate cell; total = subtotal + GST.`,`Format all three as currency with 2 decimals.`],pitfalls:[`SUM(C5:C9)*SUM(D5:D9) is not the subtotal: it multiplies every quantity by every price.`,`If the template says GST is rounded to cents, use =ROUND(D11*G2,2).`],answer:`D11 = $39.80, D12 = $3.58 (3.582 unrounded), D13 = $43.38.`},{id:`sumproduct-production-plan-cost`,topic:`sumproduct`,question:`A Tuas sauce factory plans four weeks of output for four sauces. In G8 compute the production cost of week 1 and fill it down to G11 for weeks 2 to 4. In G12 compute the total cost of the plan.`,layout:`Unit cost of each sauce in C5:F5 ($12, $18, $25, $9). Planned units, one row per week, in C8:F11 (week 1: 100, 50, 20, 200). Week labels in B8:B11.`,formulas:[{cell:`G8 (fill to G8:G11)`,formula:`=SUMPRODUCT($C$5:$F$5,C8:F8)`,note:`unit-cost row locked, this week row moves`},{cell:`G12`,formula:`=SUM(G8:G11)`}],steps:[`Unit costs sit in one row, the plan in rows below: both 4 columns wide.`,`G8: =SUMPRODUCT($C$5:$F$5,C8:F8). Lock the cost row, leave the plan row relative.`,`Fill G8 down to G11, then sum G8:G11 in G12.`,`Click G11 and check it reads $C$5:$F$5 and C11:F11.`],pitfalls:[`Without $ on C5:F5 the cost row slides down to empty rows and weeks 2 to 4 come out wrong.`,`Both ranges must have the same shape (1 row x 4 columns).`],answer:`Week 1: G8 = 100x12 + 50x18 + 20x25 + 200x9 = $4,400. G12 is the sum of the four weekly costs.`},{id:`sumproduct-expected-value`,topic:`sumproduct`,question:`A Sentosa drinks kiosk earns a different daily profit depending on the weather. In E10 compute the expected daily profit from the probability table, and in E11 check that the probabilities add up to 1.`,layout:`Weather outcomes in B5:B8 (Sunny, Cloudy, Light rain, Heavy rain), daily profit in C5:C8 ($1,400, $900, $450, $200), probabilities in D5:D8 (0.35, 0.30, 0.25, 0.10).`,formulas:[{cell:`E10`,formula:`=SUMPRODUCT(C5:C8,D5:D8)`,note:`each outcome x its probability, added up`},{cell:`E11`,formula:`=SUM(D5:D8)`}],steps:[`Pair each outcome with its probability (same rows).`,`Expected value = SUMPRODUCT(outcomes, probabilities).`,`Check the probabilities sum to exactly 1.`],pitfalls:[`AVERAGE(C5:C8) treats every weather type as equally likely.`,`Probabilities typed as 35 instead of 0.35 or 35% give 100 times the answer.`],answer:`E10 = 490 + 270 + 112.50 + 20 = $892.50; E11 = 1.`},{id:`sumproduct-weighted-average-per-person`,topic:`sumproduct`,question:`A hawker food-tour company sold five group bookings at different per-person prices. In D11 compute the average price paid per person (not per booking).`,layout:`People per booking in C5:C9 (2, 6, 4, 1, 7), price per person in D5:D9 ($45, $38, $40, $50, $36).`,formulas:[{cell:`D11`,formula:`=SUMPRODUCT(C5:C9,D5:D9)/SUM(C5:C9)`,note:`total revenue / total people`}],steps:[`Total revenue = SUMPRODUCT(people, price per person).`,`Total people = SUM(people).`,`Weighted average = revenue / people.`],pitfalls:[`=AVERAGE(D5:D9) gives $41.80, the average per booking: it weights the solo traveller the same as the group of 7.`],answer:`Revenue $780 over 20 people: D11 = $39.00 per person.`},{id:`sumproduct-conditional-total`,topic:`sumproduct`,question:`A bubble-tea chain logs 60 transactions. In H5 compute the total revenue of the outlet named in G5 and fill down to H8 for the outlets in G6:G8. In I5 count the transactions of that outlet and fill down to I8.`,layout:`Transaction list: outlet name in B5:B64, revenue in E5:E64. Outlets to summarise in G5:G8 (Jurong, Tampines, Bugis, Woodlands).`,formulas:[{cell:`H5 (fill to H5:H8)`,formula:`=SUMPRODUCT(($B$5:$B$64=G5)*$E$5:$E$64)`,note:`the comparison is 1 on matching rows, 0 elsewhere`},{cell:`H5 (alternative)`,formula:`=SUMIF($B$5:$B$64,G5,$E$5:$E$64)`},{cell:`I5 (fill to I5:I8)`,formula:`=COUNTIF($B$5:$B$64,G5)`}],steps:[`Write the condition as a whole-column comparison with the criterion cell: ($B$5:$B$64=G5).`,`Multiply by the values to add (*$E$5:$E$64) and wrap in SUMPRODUCT.`,`Lock the data ranges, leave G5 relative, fill down.`,`Check: if every outlet is listed, H5:H8 adds up to SUM(E5:E64).`],pitfalls:[`=SUMPRODUCT($B$5:$B$64=G5,$E$5:$E$64) with a comma returns 0: TRUE/FALSE only become 1/0 when multiplied.`,`Text criteria must match exactly, including stray spaces.`],answer:`One revenue total and one count per outlet in H5:I8.`},{id:`sumproduct-two-conditions`,topic:`sumproduct`,question:`From an online grocer order log, compute in H5 the total value of orders that came through the channel in H3 and were worth at least the amount in H4. In H6 count those orders.`,layout:`Order log: channel in C5:C204 ("App", "Web", "Phone"), order value in E5:E204. Criteria: channel in H3 (App), minimum value in H4 ($50).`,formulas:[{cell:`H5`,formula:`=SUMPRODUCT((C5:C204=H3)*(E5:E204>=H4)*E5:E204)`},{cell:`H6`,formula:`=SUMPRODUCT((C5:C204=H3)*(E5:E204>=H4))`},{cell:`H5 (alternative, not taught)`,formula:`=SUMIFS(E5:E204,C5:C204,H3,E5:E204,">="&H4)`}],steps:[`One bracket per condition: (C5:C204=H3) and (E5:E204>=H4).`,`Multiply the brackets (both must hold). Multiply by E5:E204 to add values; leave it out to count.`,`"At least" is >=; "more than" would be >.`],pitfalls:[`For OR (either condition) add the brackets and test >0, so a row meeting both is not counted twice: =SUMPRODUCT(((C5:C204="App")+(E5:E204>=100)>0)*E5:E204).`,`All ranges must cover the same rows (5 to 204).`],answer:`H5 = value of App orders of $50 or more; H6 = how many there are (H5/H6 is their average).`},{id:`bracket-text-bands-discount`,topic:`bracket`,question:`A furniture showroom gives a discount based on the subtotal, with bands printed as text in F5:F9. (i) In E5:E9 build the numeric lower bound of each band. (ii) In D20 look up the discount rate for the subtotal in D19. (iii) In D21 compute the discount and in D22 the amount payable.`,layout:`Band text in F5:F9: "Below $100", "$100 to $299.99", "$300 to $599.99", "$600 to $999.99", "$1,000 and above". Discount rates in G5:G9 (0%, 3%, 5%, 8%, 12%). Lower bounds to build in E5:E9. Subtotal in D19 ($452.60).`,formulas:[{cell:`D20`,formula:`=VLOOKUP(D19,$E$5:$G$9,3,TRUE)`,note:`approximate match on the lower bounds; the rate is column 3 counted from E`},{cell:`D20 (alternative)`,formula:`=LOOKUP(D19,$E$5:$E$9,$G$5:$G$9)`},{cell:`D21`,formula:`=D19*D20`},{cell:`D22`,formula:`=D19-D21`}],steps:[`Type the smallest amount of each band in E5:E9: 0, 100, 300, 600, 1000 (ascending, starting at 0).`,`D20: VLOOKUP the subtotal in E5:G9 with TRUE, column 3.`,`Discount = subtotal x rate; payable = subtotal - discount (or =D19*(1-D20)).`,`Test the edges: 299.99 must give 3%, 300 must give 5%.`],pitfalls:[`FALSE (exact match) returns #N/A for any subtotal that is not exactly a lower bound.`,`Lower bounds typed as text break the lookup: type plain numbers.`,`Column 2 returns the band text, not the rate.`],answer:`E5:E9 = 0, 100, 300, 600, 1000. For $452.60: D20 = 5%, D21 = $22.63, D22 = $429.97.`},{id:`bracket-commission-tier`,topic:`bracket`,question:`A property agency pays each agent commission on ALL of their monthly sales at the rate of the tier the sales fall in. In D5 compute the commission for the agent in row 5 and fill down to D30.`,layout:`Monthly sales in C5:C30. Tier table: lower bounds G5:G8 (0, 20000, 50000, 100000), rates H5:H8 (2%, 3.5%, 5%, 6.5%). A tier starts at its lower bound ("$50,000 or more earns 5%").`,formulas:[{cell:`D5 (fill to D5:D30)`,formula:`=C5*VLOOKUP(C5,$G$5:$H$8,2,TRUE)`},{cell:`D5 (alternative)`,formula:`=C5*INDEX($H$5:$H$8,MATCH(C5,$G$5:$G$8,1))`}],steps:[`Check the tier table is ascending and starts at 0.`,`Look up the rate with VLOOKUP(...,TRUE) on the locked table.`,`Multiply the whole sales figure by that rate; fill down.`,`Test 49,999 and 50,000.`],pitfalls:[`This is NOT progressive. If the wording is "5% on the part above $50,000", use base + (sales - bound) x rate (see the progressive tax question).`,`An unlocked G5:H8 slides down and returns #N/A lower in the column.`],answer:`$49,999 earns 3.5% = $1,749.97 (1,749.965); $50,000 earns 5% = $2,500.`},{id:`bracket-shipping-weight-up-to`,topic:`bracket`,question:`An online seller charges shipping by weight: up to 1 kg $4.50; over 1 kg up to 3 kg $7.80; over 3 kg up to 5 kg $11.20; over 5 kg up to 10 kg $16.00; over 10 kg $25.00. Build the lower bounds in H5:H9, then in E6 compute the fee for the parcel in row 6 and fill down to E40.`,layout:`Parcel weights in kg in D6:D40, recorded to the nearest gram (3 decimals). Fee table: lower bounds to build in H5:H9, fees in I5:I9 ($4.50, $7.80, $11.20, $16.00, $25.00).`,formulas:[{cell:`E6 (fill to E6:E40)`,formula:`=VLOOKUP(D6,$H$5:$I$9,2,TRUE)`,note:`H5:H9 = 0, 1.001, 3.001, 5.001, 10.001`},{cell:`E6 (alternative)`,formula:`=IFS(D6<=1,$I$5,D6<=3,$I$6,D6<=5,$I$7,D6<=10,$I$8,TRUE,$I$9)`}],steps:[`"Up to 1 kg" includes 1 kg, so the next band starts just above 1.`,`With weights to the gram, type lower bounds 0, 1.001, 3.001, 5.001, 10.001 in H5:H9.`,`VLOOKUP(...,TRUE) on the locked table; fill down.`,`Test 1.000 kg ($4.50) and 1.001 kg ($7.80).`],pitfalls:[`Lower bounds 0, 1, 3, 5, 10 put exactly 1 kg in the $7.80 band: wrong for "up to" wording.`,`If weights can have more decimals, use the IFS version with <= on the upper limits.`],answer:`3.000 kg pays $7.80; 3.250 kg pays $11.20; 10.000 kg pays $16.00.`},{id:`bracket-grade-by-score`,topic:`bracket`,question:`A culinary school awards a grade from the final score. In D5 return the grade for the student in row 5 and fill down to D60. In I5 count the students with the grade in H5 and fill down to I9.`,layout:`Final scores (0 to 100, may have one decimal) in C5:C60. Grade table: minimum scores in G5:G9 (0, 50, 65, 75, 85), grades in H5:H9 ("F", "D", "C", "B", "A").`,formulas:[{cell:`D5 (fill to D5:D60)`,formula:`=VLOOKUP(C5,$G$5:$H$9,2,TRUE)`},{cell:`D5 (alternative)`,formula:`=LOOKUP(C5,$G$5:$G$9,$H$5:$H$9)`},{cell:`D5 (nested IF alternative)`,formula:`=IF(C5>=85,"A",IF(C5>=75,"B",IF(C5>=65,"C",IF(C5>=50,"D","F"))))`},{cell:`I5 (fill to I5:I9)`,formula:`=COUNTIF($D$5:$D$60,H5)`}],steps:[`Minimum scores ascending from 0, grades beside them.`,`Approximate VLOOKUP (TRUE) on the locked table; fill down.`,`Count each grade with COUNTIF over the locked grade column.`],pitfalls:[`If scores must be rounded first ("74.5 counts as 75"), look up ROUND(C5,0).`,`A table sorted A to F (descending scores) breaks the approximate match.`],answer:`84.9 gives "B", 85 gives "A", 49.5 gives "F" (unless rounding is specified).`},{id:`bracket-price-break-all-units`,topic:`bracket`,question:`A packaging supplier uses all-units price breaks: one unit price, set by the order quantity, applies to the whole order. In C5 look up the unit price for the quantity in C4 and in C6 compute the order cost.`,layout:`Order quantity in C4 (260). Price-break table: minimum quantities F5:F8 (1, 100, 250, 500), unit prices G5:G8 ($2.40, $2.10, $1.95, $1.80).`,formulas:[{cell:`C5`,formula:`=VLOOKUP(C4,$F$5:$G$8,2,TRUE)`},{cell:`C6`,formula:`=C4*C5`}],steps:[`Approximate-match lookup on the minimum-quantity column.`,`All units at that price: cost = quantity x unit price.`,`Check a quantity just below a break (249) and on it (250).`],pitfalls:[`If the lower price applies only to units above the break (incremental), cost is built band by band, not quantity x one price.`,`A quantity of 0 returns #N/A because the first bound is 1.`],answer:`260 units: C5 = $1.95, C6 = $507.00. Note 240 units cost $504.00 but 250 cost only $487.50.`},{id:`bracket-progressive-tax`,topic:`bracket`,question:`Compute income tax with a progressive (marginal) table. (i) In H5 compute the base tax of each bracket and fill down to H9. (ii) In D5 compute the tax on the income in C5 and fill down to D40. (iii) In E5 compute the effective tax rate and fill down to E40.`,layout:`Chargeable incomes in C5:C40. Tax table: lower bounds G4:G9 (0, 20000, 30000, 40000, 80000, 120000), base tax H4:H9 (tax on income equal to the lower bound; H4 typed 0), marginal rates I4:I9 (0%, 2%, 3.5%, 7%, 11.5%, 15%).`,formulas:[{cell:`H5 (fill to H5:H9)`,formula:`=H4+(G5-G4)*I4`,note:`base of the previous bracket + its full width x its rate`},{cell:`D5 (fill to D5:D40)`,formula:`=VLOOKUP(C5,$G$4:$I$9,2,TRUE)+(C5-VLOOKUP(C5,$G$4:$I$9,1,TRUE))*VLOOKUP(C5,$G$4:$I$9,3,TRUE)`,note:`base + (income - lower bound) x marginal rate`},{cell:`E5 (fill to E5:E40)`,formula:`=IF(C5>0,D5/C5,0)`}],steps:[`Base tax: H5 = H4 + (G5 - G4) x I4, filled down.`,`VLOOKUP(...,TRUE) on G4:I9: column 1 = lower bound, 2 = base tax, 3 = rate.`,`Tax = base + (income - lower bound) x marginal rate.`,`Check by hand: 65,000 gives 550 + 25,000 x 7% = 2,300.`],pitfalls:[`Income x marginal rate (65,000 x 7% = 4,550) overstates the tax: the rate applies only above the lower bound.`,`Lock $G$4:$I$9 in all three VLOOKUPs.`],answer:`H4:H9 = 0, 0, 200, 550, 3,350, 7,950. Income $65,000: D5 = $2,300, E5 = 3.54%.`},{id:`bracket-session-rate-from-times`,topic:`bracket`,question:`A karaoke studio prices by session length: the band rate applies to the whole session, prorated by the minute. For the booking in row 5 compute the hours in E5, the hourly rate in F5 and the charge in G5; fill all three down to row 40.`,layout:`Start times in C5:C40, end times in D5:D40 (hh:mm, same day). Rate table: lower bounds in hours J5:J8 (0, 2, 4, 6), hourly rates K5:K8 ($18, $15, $13, $11).`,formulas:[{cell:`E5 (fill to E5:E40)`,formula:`=ROUND((D5-C5)*24,6)`,note:`day fraction to hours, rounded to clear floating-point dust`},{cell:`F5 (fill to F5:F40)`,formula:`=VLOOKUP(E5,$J$5:$K$8,2,TRUE)`},{cell:`G5 (fill to G5:G40)`,formula:`=E5*F5`}],steps:[`Hours = (end - start) x 24, wrapped in ROUND(...,6).`,`Band rate by approximate VLOOKUP on the hour bounds.`,`Charge = hours x rate (prorated by the minute).`],pitfalls:[`Without ROUND, 14:00 to 16:00 computes as 1.9999999999999996 hours and lands in the $18 band.`,`Looking up D5-C5 directly compares a day fraction (0.083) with hour bounds: multiply by 24 first.`],answer:`13:40 to 17:10 is 3.5 h at $15 = $52.50. 14:00 to 16:00 is 2 h at $15 = $30.00.`},{id:`bracket-discount-band-after-member-discount`,topic:`bracket`,question:`A sports shop takes 10% off for members first. A volume discount is then applied to the amount AFTER the member discount, and the volume band is also decided by that discounted amount. In D21 compute the amount after the member discount, in D22 the volume rate, and in D23 the amount payable.`,layout:`Member flag in D18 ("Y" or "N"). Subtotal before any discount in D20 ($540). Member discount rate in H2 (10%). Volume table: lower bounds G5:G8 (0, 200, 500, 1000), rates H5:H8 (0%, 5%, 8%, 10%).`,formulas:[{cell:`D21`,formula:`=D20*(1-IF(D18="Y",H2,0))`},{cell:`D22`,formula:`=VLOOKUP(D21,G5:H8,2,TRUE)`,note:`band from the amount AFTER the member discount`},{cell:`D23`,formula:`=D21*(1-D22)`},{cell:`D22 (if the band were set by the amount BEFORE discounts)`,formula:`=VLOOKUP(D20,G5:H8,2,TRUE)`}],steps:[`Read the order: which discount comes first, and which amount decides the band.`,`Apply the member discount when the flag is "Y".`,`Look up the band with the amount the question names (here D21).`,`Apply the volume rate to the discounted amount: D21 x (1 - rate).`],pitfalls:[`Adding the rates (10% + 5% = 15% off $540 = $459.00) is wrong when discounts are applied one after the other.`,`Banding on D20 ($540, 8%) instead of D21 ($486, 5%) gives $447.12 instead of $461.70.`,`If the wording is ambiguous, write your assumption next to the answer.`],answer:`Member, $540: D21 = $486.00, D22 = 5%, D23 = $461.70.`},{id:`exact-lookup-price-by-code`,topic:`exact-lookup`,question:`A cafe order sheet lists item codes. In C6 return the item name and in D6 the unit price for the code in B6; in F6 compute the line total. Fill all three down to row 15.`,layout:`Order lines: item codes in B6:B15 (e.g. "K07"), quantities in E6:E15. Menu table in H5:J24: code in column H, item name in I, price in J.`,formulas:[{cell:`C6 (fill to C6:C15)`,formula:`=VLOOKUP(B6,$H$5:$J$24,2,FALSE)`},{cell:`D6 (fill to D6:D15)`,formula:`=VLOOKUP(B6,$H$5:$J$24,3,FALSE)`},{cell:`F6 (fill to F6:F15)`,formula:`=D6*E6`},{cell:`D6 (alternative)`,formula:`=XLOOKUP(B6,$H$5:$H$24,$J$5:$J$24)`}],steps:[`Codes are exact keys: last argument FALSE (or 0).`,`Column number counts from the first column of the table: H = 1, I = 2, J = 3.`,`Lock the table, leave B6 relative, fill down.`],pitfalls:[`TRUE or a missing 4th argument does an approximate match and can silently return the wrong item.`,`#N/A: code not in the menu, a stray space, or a number stored as text.`],answer:`One name and price per line; SUM(F6:F15) is the order subtotal.`},{id:`exact-lookup-left-lookup`,topic:`exact-lookup`,question:`A clinic staff list has the department in column B, staff ID in column C and name in column D. For the ID typed in G3, return the department in G4 and the name in G5.`,layout:`Departments in B5:B40, staff IDs in C5:C40 (unique, e.g. "S1043"), names in D5:D40. Search ID in G3.`,formulas:[{cell:`G4`,formula:`=INDEX(B5:B40,MATCH(G3,C5:C40,0))`,note:`answer column is LEFT of the key: VLOOKUP cannot do this`},{cell:`G5`,formula:`=INDEX(D5:D40,MATCH(G3,C5:C40,0))`},{cell:`G4 (alternative)`,formula:`=XLOOKUP(G3,C5:C40,B5:B40)`}],steps:[`MATCH(G3, ID column, 0) gives the position of the ID inside C5:C40.`,`INDEX(answer column, that position) returns the value on the same row.`,`Both ranges must start and end on the same rows (5 to 40).`],pitfalls:[`MATCH without the 0 matches approximately and can return a wrong row on unsorted IDs.`,`INDEX over B5:B40 with MATCH over C4:C40 shifts every answer by one row.`],answer:`G4 shows the department and G5 the name; #N/A means the ID is not in the list.`},{id:`exact-lookup-two-way-region-weight`,topic:`exact-lookup`,question:`A courier rate card gives the price by region (columns) and weight band (rows). For the parcel in row 13 return the rate in E13 and fill down to E40.`,layout:`Rate card: label "From (kg)" in F4, region names in G4:J4 ("Central", "East", "North", "West"), weight-band lower bounds in kg in F5:F9 (0, 1, 2, 5, 10), rates in G5:J9. Parcels: region in C13:C40, weight in kg in D13:D40.`,formulas:[{cell:`E13 (fill to E13:E40)`,formula:`=INDEX($G$5:$J$9,MATCH(D13,$F$5:$F$9,1),MATCH(C13,$G$4:$J$4,0))`,note:`row: approximate (weight band); column: exact (region)`},{cell:`E13 (alternative)`,formula:`=VLOOKUP(D13,$F$5:$J$9,MATCH(C13,$F$4:$J$4,0),TRUE)`,note:`the MATCH counts from F, the first column of the VLOOKUP table`}],steps:[`Row position: MATCH(weight, lower bounds, 1), since weights fall between bounds.`,`Column position: MATCH(region, headers, 0), since names must match exactly.`,`INDEX(grid, row, column). Lock all table ranges, leave C13 and D13 relative.`],pitfalls:[`Match type 0 on the weight returns #N/A for any weight that is not exactly a bound.`,`In the VLOOKUP version the header range must start in column F or the column number is off by one.`,`Swapping the row and column MATCH returns a wrong rate or #REF!.`],answer:`A 3.4 kg parcel to "East" uses the 2 kg row and the East column: the value in H7.`},{id:`exact-lookup-fare-matrix-position`,topic:`exact-lookup`,question:`A ferry operator numbers its six piers 1 to 6. The fare matrix gives the fare from each origin (row) to each destination (column). For the trip in row 14 return the fare in E14 and the trip revenue in F14; fill both down to row 50.`,layout:`Fare matrix in C4:H9: row 1 = origin pier 1, column 1 = destination pier 1 (pier numbers labelled in B4:B9 and C3:H3). Trips: origin pier number in B14:B50, destination pier number in C14:C50, passengers in D14:D50.`,formulas:[{cell:`E14 (fill to E14:E50)`,formula:`=INDEX($C$4:$H$9,B14,C14)`,note:`row number = origin, column number = destination`},{cell:`F14 (fill to F14:F50)`,formula:`=D14*E14`}],steps:[`The pier numbers are already positions inside the grid.`,`INDEX(grid, row = origin, column = destination); lock the grid.`,`Revenue = passengers x fare; fill down.`],pitfalls:[`INDEX takes the row first: swapping gives the return-trip fare, which may differ.`,`The numbers are positions inside C4:H9, not sheet rows: do not add 3.`],answer:`Origin 2 to destination 5 reads the 2nd row, 5th column of the grid: cell G5.`},{id:`exact-lookup-match-position`,topic:`exact-lookup`,question:`A sales table has one row per outlet and one column per month. For the outlet chosen in Q3 and the month in Q4, return the row position in Q5, the column position in Q6, the sales in Q7 and the outlet total for the year in Q8.`,layout:`Outlet names in B5:B12, month labels "Jan" to "Dec" (text) in C4:N4, sales in C5:N12. Choices: outlet name in Q3, month label in Q4 (e.g. "Mar").`,formulas:[{cell:`Q5`,formula:`=MATCH(Q3,B5:B12,0)`},{cell:`Q6`,formula:`=MATCH(Q4,C4:N4,0)`},{cell:`Q7`,formula:`=INDEX(C5:N12,Q5,Q6)`},{cell:`Q8`,formula:`=SUMPRODUCT((B5:B12=Q3)*C5:N12)`,note:`the 1/0 column picks out the outlet row`}],steps:[`MATCH(value, list, 0) returns the position inside the list, counting from 1.`,`Feed both positions into INDEX(grid, row, column).`,`For a whole-row total, multiply the grid by the row condition inside SUMPRODUCT.`],pitfalls:[`If the month headers are real dates formatted "mmm", matching the text "Mar" fails.`,`MATCH positions count from the start of the range, not from row 1 of the sheet.`],answer:`If Q3 is the 3rd outlet and Q4 = "Mar": Q5 = 3, Q6 = 3, Q7 returns E7.`},{id:`exact-lookup-best-option-name`,topic:`exact-lookup`,question:`Four marketing plans have been evaluated. In F10 return the name of the plan with the highest projected profit and in F11 that profit.`,layout:`Plan names in B5:B8, projected profits in E5:E8 (model formulas).`,formulas:[{cell:`F10`,formula:`=INDEX(B5:B8,MATCH(MAX(E5:E8),E5:E8,0))`},{cell:`F11`,formula:`=MAX(E5:E8)`},{cell:`F10 (alternative)`,formula:`=XLOOKUP(MAX(E5:E8),E5:E8,B5:B8)`}],steps:[`MAX finds the best value (MIN for a cost column).`,`MATCH(best, values, 0) finds where it sits.`,`INDEX on the names returns the matching name.`],pitfalls:[`With a tie MATCH returns the first one: mention the tie in words.`,`Typing the winner by hand earns no formula mark and goes stale if inputs change.`],answer:`F10 shows the plan name (text), F11 its profit.`},{id:`if-logic-weekday-spend-items`,topic:`if-logic`,question:`A supermarket gives an extra discount on a weekday (Monday to Friday) when the subtotal is at least the amount in H4 and the basket has at least the number of items in H5. In D18 count the items and in D19 compute the extra discount (0 if not eligible).`,layout:`Purchase date in C3. Quantities in C6:C15. Subtotal in D17. Extra discount rate in H3 (5%), minimum subtotal in H4 ($80), minimum items in H5 (6).`,formulas:[{cell:`D18`,formula:`=SUM(C6:C15)`,note:`items = total units (state this assumption)`},{cell:`D19`,formula:`=IF(AND(WEEKDAY(C3,2)<=5,D17>=H4,D18>=H5),D17*H3,0)`}],steps:[`Weekday test: WEEKDAY(C3,2)<=5 (Mon = 1 ... Fri = 5).`,`"At least" is >= for both thresholds.`,`All three must hold: AND(...). True: subtotal x rate; false: 0.`],pitfalls:[`WEEKDAY(C3) without ,2 has Sunday = 1, so <=5 includes Sunday and drops Friday.`,`If "items" could mean product lines, COUNTIF(C6:C15,">0") counts lines instead: write which one you used.`],answer:`A Wednesday basket of 7 items and $92.40: D19 = $4.62. The same basket on a Saturday: $0.`},{id:`if-logic-or-free-delivery`,topic:`if-logic`,question:`An online florist waives the delivery fee if the order value is at least the amount in H3 or the customer tier is "Gold". In E5 compute the delivery fee and in F5 the amount payable; fill both down to row 80.`,layout:`Order values in C5:C80, customer tiers in D5:D80 ("Gold", "Silver", "Basic"). Standard delivery fee in H2 ($8.90), free-delivery threshold in H3 ($120).`,formulas:[{cell:`E5 (fill to E5:E80)`,formula:`=IF(OR(C5>=$H$3,D5="Gold"),0,$H$2)`},{cell:`F5 (fill to F5:F80)`,formula:`=C5+E5`}],steps:[`Either condition is enough: OR(...).`,`True: fee 0; false: the standard fee.`,`Lock H2 and H3, fill down.`],pitfalls:[`AND instead of OR charges a Gold customer with a $100 order.`,`"Gold " with a trailing space fails the text test.`],answer:`$95 Gold: fee $0. $95 Silver: fee $8.90 ($103.90 payable). $130 Basic: fee $0.`},{id:`if-logic-nested-three-tiers`,topic:`if-logic`,question:`A logistics firm pays a year-end bonus of 10% of salary if the performance score is at least 85, 5% if it is at least 70, otherwise nothing. In E5 compute the bonus and fill down to E50.`,layout:`Scores in C5:C50, annual salaries in D5:D50. Top rate in H2 (10%), middle rate in H3 (5%), cut-offs in H4 (85) and H5 (70).`,formulas:[{cell:`E5 (fill to E5:E50)`,formula:`=IF(C5>=$H$4,D5*$H$2,IF(C5>=$H$5,D5*$H$3,0))`},{cell:`E5 (IFS alternative)`,formula:`=IFS(C5>=$H$4,D5*$H$2,C5>=$H$5,D5*$H$3,TRUE,0)`}],steps:[`Test the highest tier first: a score of 90 also passes the >=70 test.`,`The second IF sits in the value-if-false of the first.`,`The last value-if-false is the default (0).`],pitfalls:[`Testing >=70 first gives the 90s only 5%.`,`One closing bracket per IF.`],answer:`Salary $60,000: score 88 earns $6,000, 72 earns $3,000, 69 earns $0.`},{id:`if-logic-ifs-stock-status`,topic:`if-logic`,question:`A pharmacy labels each product "Reorder" if stock is at or below its reorder level, "Low" if at or below 1.5 times that level, otherwise "OK". In E5 return the label and fill down to E120. In H3 count the products to reorder.`,layout:`Stock on hand in C5:C120, reorder levels in D5:D120. The 1.5 factor in H2.`,formulas:[{cell:`E5 (fill to E5:E120)`,formula:`=IFS(C5<=D5,"Reorder",C5<=$H$2*D5,"Low",TRUE,"OK")`},{cell:`E5 (nested IF alternative)`,formula:`=IF(C5<=D5,"Reorder",IF(C5<=$H$2*D5,"Low","OK"))`},{cell:`H3`,formula:`=COUNTIF(E5:E120,"Reorder")`}],steps:[`Order the tests from the most severe to the least.`,`IFS(test1, result1, test2, result2, TRUE, default).`,`Count a label with COUNTIF(range,"Reorder").`],pitfalls:[`Without TRUE as the last test, IFS returns #N/A when nothing matches.`,`Spell text results exactly as asked: later counts depend on them.`],answer:`Level 40: stock 40 is "Reorder", 55 is "Low" (limit 60), 61 is "OK".`},{id:`if-logic-overtime-pay`,topic:`if-logic`,question:`Warehouse staff earn their hourly rate for the first 40 hours a week and 1.5 times that rate for every hour above 40. In E5 compute the weekly pay and fill down to E30.`,layout:`Hours worked in C5:C30, hourly rates in D5:D30. Normal-hours limit in H2 (40), overtime multiplier in H3 (1.5).`,formulas:[{cell:`E5 (fill to E5:E30)`,formula:`=MIN(C5,$H$2)*D5+MAX(0,C5-$H$2)*D5*$H$3`},{cell:`E5 (IF alternative)`,formula:`=IF(C5<=$H$2,C5*D5,$H$2*D5+(C5-$H$2)*D5*$H$3)`}],steps:[`Normal hours = MIN(hours, 40).`,`Overtime hours = MAX(0, hours - 40).`,`Pay = normal x rate + overtime x rate x 1.5.`],pitfalls:[`C5*D5*1.5 pays the premium on every hour, not just the extra ones.`,`Without MAX(0, ...) a 32-hour week gets negative overtime.`],answer:`46 h at $15: 40x15 + 6x15x1.5 = $735.00. 32 h at $15: $480.00.`},{id:`if-logic-minimum-charge`,topic:`if-logic`,question:`A laundry charges per kg with a minimum charge per order. In D5 compute the charge and fill down to D60. Then give the version that also caps the charge at the amount in H4.`,layout:`Order weights in kg in C5:C60. Price per kg in H2 ($3.20), minimum charge in H3 ($12.00), cap in H4 ($40.00).`,formulas:[{cell:`D5 (fill to D5:D60)`,formula:`=MAX($H$3,C5*$H$2)`},{cell:`D5 (with the cap)`,formula:`=MIN($H$4,MAX($H$3,C5*$H$2))`},{cell:`D5 (IF alternative)`,formula:`=IF(C5*$H$2<$H$3,$H$3,C5*$H$2)`}],steps:[`A minimum charge = the larger of the minimum and the computed charge: MAX.`,`A cap = the smaller of the cap and the charge: MIN.`,`Both: MIN(cap, MAX(minimum, charge)).`],pitfalls:[`MIN and MAX are easy to swap: a "minimum charge" uses MAX.`],answer:`2.5 kg: $8.00 is below the minimum, so $12.00. 5 kg: $16.00. 15 kg: $48.00, or $40.00 with the cap.`},{id:`if-logic-late-delivery-flag`,topic:`if-logic`,question:`A furniture retailer promises a delivery date for each order. In E5 return "Late" if delivered after the promised date, else "On time"; in F5 the days late (0 if on time); in G5 compensation of $20 per day late, capped at $200. Fill all three down to row 60.`,layout:`Promised dates in C5:C60, actual delivery dates in D5:D60. Compensation per day in J2 ($20), cap in J3 ($200).`,formulas:[{cell:`E5 (fill to E5:E60)`,formula:`=IF(D5>C5,"Late","On time")`},{cell:`F5 (fill to F5:F60)`,formula:`=MAX(0,D5-C5)`},{cell:`G5 (fill to G5:G60)`,formula:`=MIN($J$3,F5*$J$2)`}],steps:[`Dates are day numbers: D5 - C5 is days.`,`Delivered on the promised day is on time: test > not >=.`,`MAX(0, ...) stops negative days; MIN applies the cap.`],pitfalls:[`Format F as Number: a day count formatted as a date shows 1900 dates.`,`Compare date cells, never typed text like "15/3/2026".`],answer:`Promised 12 Oct 2026, delivered 16 Oct: "Late", 4 days, $80. Delivered 25 Oct: 13 days, $260 capped to $200.`},{id:`dates-day-name`,topic:`dates`,question:`A spa booking list needs the day of each booking. In D5 show the short day name (Mon, Tue, ...) and in E5 the day number with Monday = 1; fill both down to row 80.`,layout:`Booking dates in C5:C80.`,formulas:[{cell:`D5 (fill to D5:D80)`,formula:`=TEXT(C5,"ddd")`},{cell:`D5 (full day name)`,formula:`=TEXT(C5,"dddd")`},{cell:`E5 (fill to E5:E80)`,formula:`=WEEKDAY(C5,2)`}],steps:[`TEXT(date,"ddd") gives Mon; "dddd" gives Monday.`,`WEEKDAY(date,2) gives 1 for Monday ... 7 for Sunday.`],pitfalls:[`TEXT returns text: use WEEKDAY, not the day name, inside rules.`,`Formatting C5 as "ddd" only changes the display; the value is still the date.`],answer:`9 Nov 2026 gives "Mon" and 1.`},{id:`dates-weekend-holiday-surcharge`,topic:`dates`,question:`A party venue charges 20% more on Saturdays, Sundays and public holidays. In E5 return "Peak" or "Off-peak" and in F5 the price including any surcharge; fill both down to row 60.`,layout:`Event dates in C5:C60, base prices in D5:D60. Surcharge rate in H2 (20%). Public holiday dates in J5:J15.`,formulas:[{cell:`E5 (fill to E5:E60)`,formula:`=IF(OR(WEEKDAY(C5,2)>5,COUNTIF($J$5:$J$15,C5)>0),"Peak","Off-peak")`},{cell:`F5 (fill to F5:F60)`,formula:`=IF(E5="Peak",D5*(1+$H$2),D5)`}],steps:[`WEEKDAY(date,2) is 6 for Saturday and 7 for Sunday: >5 means weekend.`,`COUNTIF(holiday list, date)>0 is TRUE when the date is a listed holiday.`,`Join with OR; lock the holiday list and the rate.`],pitfalls:[`WEEKDAY(C5)>5 without ,2 flags Friday and Saturday.`,`Holiday cells must be real dates, not text.`],answer:`Sat 12 Dec 2026, $2,000: "Peak", $2,400. Fri 11 Dec 2026 (not a holiday): "Off-peak", $2,000.`},{id:`dates-days-between-nights`,topic:`dates`,question:`A hotel charges per night. In E5 compute the nights between check-in and check-out and in F5 the room charge; fill both down to row 40. In E3 count the bookings longer than 7 nights.`,layout:`Check-in dates in C5:C40, check-out dates in D5:D40. Nightly rate in H2 ($180). Nights go in E5:E40, charges in F5:F40.`,formulas:[{cell:`E5 (fill to E5:E40)`,formula:`=D5-C5`},{cell:`F5 (fill to F5:F40)`,formula:`=E5*$H$2`},{cell:`E3`,formula:`=COUNTIF(E5:E40,">7")`}],steps:[`Nights = check-out - check-in (dates are day numbers).`,`Format E as Number, not Date.`,`Charge = nights x locked rate.`],pitfalls:[`Days counted inclusively (a rental from the 1st to the 3rd is 3 days) need +1; nights do not.`],answer:`Check-in 28 Dec 2026, check-out 3 Jan 2027: 6 nights, $1,080.`},{id:`dates-age-in-years`,topic:`dates`,question:`An insurer prices policies by age in completed years on the valuation date in H2. In D5 compute the age of the customer in row 5 and fill down to D200.`,layout:`Dates of birth in C5:C200. Valuation date in H2 (9 Nov 2026).`,formulas:[{cell:`D5 (fill to D5:D200)`,formula:`=YEAR($H$2)-YEAR(C5)-IF(DATE(YEAR($H$2),MONTH(C5),DAY(C5))>$H$2,1,0)`,note:`minus 1 if the birthday has not yet come this year`},{cell:`D5 (approximate, course version)`,formula:`=INT(($H$2-C5)/365.25)`},{cell:`D5 (alternative, not taught)`,formula:`=DATEDIF(C5,$H$2,"Y")`}],steps:[`Year difference: YEAR(valuation) - YEAR(birth).`,`Rebuild the birthday in the valuation year: DATE(YEAR(H2),MONTH(C5),DAY(C5)).`,`If that birthday is after the valuation date, subtract 1.`,`Use the given date cell, not TODAY(), when the question fixes the date.`],pitfalls:[`YEAR(H2)-YEAR(C5) alone is a year too high for birthdays later in the year.`,`The 365.25 version can be a day off near a birthday: use it only if an approximation is accepted.`],answer:`Born 15 Mar 2000: 26. Born 20 Dec 2000: 25.`},{id:`dates-birthday-month-points`,topic:`dates`,question:`A retailer sends a voucher to members whose birthday month is the month of the mailing date in H2 and who have at least the points in H3. In E5 compute the voucher value (0 if not eligible) and fill down to E300. In H6 compute the total value of vouchers.`,layout:`Dates of birth in C5:C300, loyalty points in D5:D300. Mailing date in H2 (a November 2026 date), minimum points in H3 (500), voucher value in H4 ($10).`,formulas:[{cell:`E5 (fill to E5:E300)`,formula:`=IF(AND(MONTH(C5)=MONTH($H$2),D5>=$H$3),$H$4,0)`},{cell:`E5 (if the rule says "this month")`,formula:`=IF(AND(MONTH(C5)=MONTH(TODAY()),D5>=$H$3),$H$4,0)`},{cell:`H6`,formula:`=SUM(E5:E300)`}],steps:[`Compare months with months: MONTH(birth) = MONTH(mailing date).`,`Points rule: >= H3.`,`Both must hold: AND; lock H2:H4 and fill down.`],pitfalls:[`MONTH(C5)=H2 compares 11 with a date number: always FALSE.`,`C5=H2 compares full dates, birth year included: almost never TRUE.`],answer:`November mailing: born 3 Nov 1990 with 620 points gets $10; with 480 points gets $0.`},{id:`dates-due-date-overdue`,topic:`dates`,question:`An accounts team tracks invoices. In F5 compute the due date, in G5 the days overdue as at the date in J2 (0 if paid or not yet due), and in H5 a flag "Overdue" or "OK". Fill all three down to row 80.`,layout:`Invoice dates in C5:C80, payment terms in days in D5:D80 (30 or 60), paid status in E5:E80 ("Y" or "N"). As-at date in J2 (9 Nov 2026).`,formulas:[{cell:`F5 (fill to F5:F80)`,formula:`=C5+D5`},{cell:`G5 (fill to G5:G80)`,formula:`=IF(AND(E5="N",$J$2>F5),$J$2-F5,0)`},{cell:`H5 (fill to H5:H80)`,formula:`=IF(G5>0,"Overdue","OK")`}],steps:[`Due date = invoice date + terms; format F as a date.`,`Overdue only if unpaid AND as-at date > due date (due today is not yet overdue).`,`Days overdue = as-at date - due date.`,`Lock J2; use TODAY() only if the question says "today".`],pitfalls:[`TODAY() instead of the given as-at date changes every day and will not match the key.`,`A due date shown as 46,000-something just needs a date format.`],answer:`Invoice 15 Sep 2026, 30 days, unpaid: due 15 Oct 2026, 25 days overdue, "Overdue".`},{id:`dates-within-promo-window`,topic:`dates`,question:`A members-only sale runs from the date in H2 to the date in H3, both inclusive. In E5 return "Promo" if the order date is inside the window (else blank) and in F5 the discount on the order; fill both down to row 150.`,layout:`Order dates in C5:C150, order values in D5:D150. Window start in H2, window end in H3, discount rate in H4 (15%).`,formulas:[{cell:`E5 (fill to E5:E150)`,formula:`=IF(AND(C5>=$H$2,C5<=$H$3),"Promo","")`},{cell:`F5 (fill to F5:F150)`,formula:`=IF(AND(C5>=$H$2,C5<=$H$3),D5*$H$4,0)`},{cell:`F5 (if C holds date AND time)`,formula:`=IF(AND(INT(C5)>=$H$2,INT(C5)<=$H$3),D5*$H$4,0)`}],steps:[`Inclusive window: >= start AND <= end.`,`Lock the window cells.`,`If orders carry a time stamp, drop the time with INT() first.`],pitfalls:[`A 3 pm order on the end date is larger than the end date itself, so <= H3 wrongly excludes it unless you use INT.`,`Typed text dates ("1/12/2026") inside the formula compare as text: use the cells or DATE(2026,12,1).`],answer:`Window 1 to 7 Dec 2026: a $200 order on 7 Dec gets "Promo" and $30; one on 8 Dec gets $0.`},{id:`time-arith-duration-hours`,topic:`time-arith`,question:`A car park records entry and exit times. In E5 compute the parking duration in hours (a number) and in F5 in minutes; fill both down to row 200.`,layout:`Entry times in C5:C200, exit times in D5:D200 (hh:mm, same day).`,formulas:[{cell:`E5 (fill to E5:E200)`,formula:`=(D5-C5)*24`},{cell:`F5 (fill to F5:F200)`,formula:`=(D5-C5)*1440`},{cell:`F5 (whole minutes)`,formula:`=ROUND((D5-C5)*1440,0)`}],steps:[`D5 - C5 is a fraction of a day.`,`x24 for hours, x1440 for minutes, x86400 for seconds.`,`Format E and F as Number, not as a time.`],pitfalls:[`D5-C5 formatted hh:mm shows 2:35 but its value is 0.1076: a rate multiplied by it is wrong.`],answer:`08:45 to 11:20: E5 = 2.5833 hours, F5 = 155 minutes.`},{id:`time-arith-prorated-hourly-charge`,topic:`time-arith`,question:`A co-working meeting room costs the hourly rate in H2, charged by the minute. In E5 compute the charge for the booking in row 5 and fill down to E60.`,layout:`Start times in C5:C60, end times in D5:D60. Hourly rate in H2 ($24).`,formulas:[{cell:`E5 (fill to E5:E60)`,formula:`=(D5-C5)*24*$H$2`},{cell:`E5 (same, via minutes)`,formula:`=(D5-C5)*1440*$H$2/60`}],steps:[`Hours = (end - start) x 24, including the part hour.`,`Charge = hours x locked hourly rate.`],pitfalls:[`(D5-C5)*$H$2 without x24 charges 1/24 of the right amount.`,`HOUR(D5-C5)*rate drops the minutes: not prorated.`],answer:`09:10 to 11:55 is 2.75 hours: $66.00.`},{id:`time-arith-add-minutes`,topic:`time-arith`,question:`A delivery app estimates arrival as dispatch time plus travel minutes. In E5 compute the estimated arrival time (format hh:mm) and fill down to E100.`,layout:`Dispatch times in C5:C100, travel times in whole minutes (numbers) in D5:D100.`,formulas:[{cell:`E5 (fill to E5:E100)`,formula:`=C5+D5/1440`},{cell:`E5 (alternative)`,formula:`=C5+TIME(0,D5,0)`}],steps:[`Turn minutes into a day fraction: divide by 1440 (24 x 60).`,`Add to the clock time; format hh:mm.`],pitfalls:[`=C5+D5 adds D5 DAYS: the clock shows the same time.`,`TIME(0,D5,0) wraps past midnight (drops whole days): fine for a clock time, not for long durations.`],answer:`10:47 + 38 minutes = 11:25.`},{id:`time-arith-add-seconds-chain`,topic:`time-arith`,question:`An assembly cell processes units one after another. In E5 compute each unit finish time (start + cycle seconds) and fill down to E60; in C6 start the next unit when the previous one finishes and fill down to C60.`,layout:`Start times in C5:C60 (C5 typed 08:00:00), cycle times in seconds in D5:D60, finish times in E5:E60.`,formulas:[{cell:`E5 (fill to E5:E60)`,formula:`=C5+D5/86400`},{cell:`C6 (fill to C6:C60)`,formula:`=E5`},{cell:`E5 (alternative)`,formula:`=C5+TIME(0,0,D5)`}],steps:[`Seconds to a day fraction: /86400 (24 x 60 x 60).`,`Finish = start + cycle; next start = previous finish.`,`Format C and E as hh:mm:ss.`],pitfalls:[`TIME(0,0,s) only accepts up to 32,767 seconds; /86400 has no limit.`,`+D5 without /86400 adds days, not seconds.`],answer:`08:00:00 + 95 s: E5 = 08:01:35 and C6 = 08:01:35.`},{id:`time-arith-minutes-to-hhmm`,topic:`time-arith`,question:`A call-centre report gives total talk time per agent in minutes. In D5 convert it to a time value shown as [h]:mm and in E5 to the text "h:mm"; fill both down to row 40.`,layout:`Total talk minutes in C5:C40 (numbers, can exceed 1,440).`,formulas:[{cell:`D5 (fill to D5:D40)`,formula:`=C5/1440`,note:`format the cell [h]:mm`},{cell:`E5 (fill to E5:E40)`,formula:`=TEXT(C5/1440,"[h]:mm")`},{cell:`D5 (alternative, under 24 h)`,formula:`=TIME(INT(C5/60),MOD(C5,60),0)`}],steps:[`Minutes / 1440 = a day fraction Excel can show as a time.`,`Use the [h]:mm format so totals over 24 hours are not reset.`],pitfalls:[`hh:mm without brackets resets at 24 h: 1,575 minutes shows 02:15 instead of 26:15.`,`Dividing by 60 gives decimal hours (2.25), not a time: 2.25 formatted hh:mm shows 06:00.`],answer:`135 minutes: D5 = 0.09375, shown 2:15. 1,575 minutes shows 26:15.`},{id:`time-arith-across-midnight`,topic:`time-arith`,question:`Security guards work shifts that may end after midnight. In E5 compute the shift length in hours and fill down to E50.`,layout:`Shift start times in C5:C50, end times in D5:D50 (clock times only, no dates; every shift is under 24 hours).`,formulas:[{cell:`E5 (fill to E5:E50)`,formula:`=MOD(D5-C5,1)*24`},{cell:`E5 (IF alternative)`,formula:`=IF(D5<C5,D5+1-C5,D5-C5)*24`}],steps:[`If the end is earlier than the start, the shift crossed midnight: add 1 day to the end.`,`MOD(end - start, 1) does that automatically.`,`x24 for hours.`],pitfalls:[`Plain D5-C5 for 22:30 to 06:15 is negative (##### as a time).`,`If the cells hold full date-times, plain D5-C5 already works: do not add 1.`],answer:`22:30 to 06:15: 7.75 hours. 09:00 to 17:30: 8.5 hours.`},{id:`time-arith-roundup-15-min-blocks`,topic:`time-arith`,question:`A legal clinic bills in 15-minute blocks, always rounding up. For each consultation compute the blocks billed in E5, billable hours in F5 and the fee in G5 at the hourly rate in J2. Fill all three down to row 80.`,layout:`Start times in C5:C80, end times in D5:D80 (hh:mm). Hourly rate in J2 ($80).`,formulas:[{cell:`E5 (fill to E5:E80)`,formula:`=ROUNDUP(ROUND((D5-C5)*96,6),0)`,note:`96 quarter-hours per day; inner ROUND keeps an exact 45 min at 3 blocks`},{cell:`F5 (fill to F5:F80)`,formula:`=E5/4`},{cell:`G5 (fill to G5:G80)`,formula:`=F5*$J$2`},{cell:`F5 (as a time value instead)`,formula:`=ROUNDUP(ROUND((D5-C5)*96,6),0)/96`,note:`format [h]:mm`}],steps:[`Quarter-hours = (end - start) x 96 (same as x24x4).`,`ROUNDUP(...,0) to the next whole block; ROUND(...,6) inside removes floating-point dust.`,`Hours = blocks / 4; fee = hours x rate.`],pitfalls:[`ROUND instead of ROUNDUP bills 77 minutes as 5 blocks instead of 6.`,`Without the inner ROUND, 11:45 to 12:30 computes as 3.000000000000005 blocks and rounds up to 4.`],answer:`14:05 to 15:22 (77 min): 6 blocks, 1.5 hours, $120.00. Exactly 45 minutes: 3 blocks, $60.00.`},{id:`time-arith-within-opening-hours`,topic:`time-arith`,question:`A food-court stall opens at the time in H2 and closes at the time in H3. In E5 compute the time of day of the order in hours, and in D5 return "Open" if it is within opening hours (opening included, closing excluded), else "Closed". Fill both down to row 500.`,layout:`Order timestamps (date and time) in C5:C500. Opening time in H2 (10:00), closing time in H3 (22:00).`,formulas:[{cell:`E5 (fill to E5:E500)`,formula:`=ROUND(MOD(C5,1)*24,6)`,note:`MOD(C5,1) drops the date; x24 and ROUND give a clean hour value`},{cell:`D5 (fill to D5:D500)`,formula:`=IF(AND(E5>=ROUND($H$2*24,6),E5<ROUND($H$3*24,6)),"Open","Closed")`},{cell:`D5 (if closing is after midnight, e.g. 18:00 to 02:00)`,formula:`=IF(OR(E5>=ROUND($H$2*24,6),E5<ROUND($H$3*24,6)),"Open","Closed")`},{cell:`D5 (one cell, no helper column)`,formula:`=IF(AND(ROUND(MOD(C5,1)*24,6)>=ROUND($H$2*24,6),ROUND(MOD(C5,1)*24,6)<ROUND($H$3*24,6)),"Open","Closed")`}],steps:[`Strip the date: MOD(timestamp,1) is the time of day.`,`Turn both sides into rounded hours: ROUND(x*24,6).`,`Within hours: >= opening AND < closing. Hours across midnight: OR instead of AND.`],pitfalls:[`Without ROUND, MOD of a 22:00 timestamp is a hair under 22:00 (0.91666666666424 vs 0.91666666666667), so an order at exactly 22:00 shows "Open".`,`A full timestamp (e.g. 46,335.9) is always greater than 10:00 (0.4167): strip the date first.`],answer:`An order at 21:59 is "Open", at exactly 22:00 "Closed", at exactly 10:00 "Open".`},{id:`time-arith-mb-to-gb-cost`,topic:`time-arith`,question:`A video studio pays cloud storage per GB per month, with 1 GB = 1,000 MB as stated. In D5 convert each file size to GB and in E5 compute its monthly cost; fill both down to row 40. In E42 compute the total monthly cost.`,layout:`File sizes in MB in C5:C40. Price per GB per month in H2 ($0.023). MB per GB in H3 (1000). Sizes in GB go in D5:D40, monthly cost per file in E5:E40.`,formulas:[{cell:`D5 (fill to D5:D40)`,formula:`=C5/$H$3`},{cell:`E5 (fill to E5:E40)`,formula:`=D5*$H$2`},{cell:`E42`,formula:`=SUM(E5:E40)`},{cell:`E42 (one cell, no helper columns)`,formula:`=SUM(C5:C40)/H3*H2`}],steps:[`Use exactly the factor given (1000 here; 1024 only if stated), kept in a cell.`,`GB = MB / factor; cost = GB x price.`],pitfalls:[`Multiplying by 1000 instead of dividing gives a cost a million times too high.`,`Never mix MB and GB in one SUMPRODUCT.`],answer:`A 2,350 MB file is 2.35 GB and costs $0.05405 a month.`},{id:`capacity-units-sold-min`,topic:`capacity`,question:`A concert hall sells tickets for 7 shows. In E5 compute the tickets sold (demand capped by seats) and in F5 the revenue; fill both down to row 11.`,layout:`Demand per show in C5:C11, seats available in D5:D11. Ticket price in J2 ($68).`,formulas:[{cell:`E5 (fill to E5:E11)`,formula:`=MIN(C5,D5)`},{cell:`F5 (fill to F5:F11)`,formula:`=E5*$J$2`}],steps:[`Sold = the smaller of demand and seats: MIN.`,`Revenue = sold x locked price.`],pitfalls:[`Revenue on demand (C5 x price) counts tickets that could not be sold.`],answer:`Demand 1,240, seats 1,100: 1,100 sold, $74,800.`},{id:`capacity-unsold-max`,topic:`capacity`,question:`A bakery bakes a fixed batch of croissants each day and donates the unsold ones. In E5 compute croissants sold, in F5 those left over (never negative) and in G5 the day profit; fill down to row 34.`,layout:`Daily demand in C5:C34, croissants baked in D5:D34. Price in J2 ($3.20), baking cost per croissant in J3 ($1.10).`,formulas:[{cell:`E5 (fill to E5:E34)`,formula:`=MIN(C5,D5)`},{cell:`F5 (fill to F5:F34)`,formula:`=MAX(0,D5-C5)`},{cell:`G5 (fill to G5:G34)`,formula:`=E5*$J$2-D5*$J$3`}],steps:[`Sold = MIN(demand, baked).`,`Left over = MAX(0, baked - demand).`,`Profit = revenue on sold units - cost of ALL units baked.`],pitfalls:[`D5-C5 without MAX gives negative leftovers on busy days.`,`Costing only the sold units understates cost.`],answer:`Demand 150, baked 180: sold 150, left 30, profit 150x3.20 - 180x1.10 = $282.00.`},{id:`capacity-lost-sales`,topic:`capacity`,question:`A chicken-rice stall prepares a fixed number of portions per day. In E5 compute portions turned away and in F5 the lost margin; fill both down to row 34. In F36 total the lost margin for the month.`,layout:`Daily demand in C5:C34, portions prepared in D5:D34. Margin per portion in J2 ($2.80). Lost portions go in E5:E34, lost margin in F5:F34.`,formulas:[{cell:`E5 (fill to E5:E34)`,formula:`=MAX(0,C5-D5)`},{cell:`F5 (fill to F5:F34)`,formula:`=E5*$J$2`},{cell:`F36`,formula:`=SUM(F5:F34)`},{cell:`E5 (equivalent)`,formula:`=C5-MIN(C5,D5)`}],steps:[`Lost sales = demand above what was prepared, never negative: MAX(0, demand - prepared).`,`Lost margin = lost portions x margin.`],pitfalls:[`C5-D5 alone is negative on quiet days and cancels real losses in the monthly total.`],answer:`Demand 320, prepared 280: 40 lost, $112.00 margin lost.`},{id:`capacity-trucks-roundup`,topic:`capacity`,question:`A beverage distributor ships cartons to supermarkets. In E5 compute the trucks needed, in F5 the delivery cost and in G5 the spare carton space on the trucks used; fill down to row 30.`,layout:`Cartons ordered per supermarket in C5:C30. Truck capacity in J2 (240 cartons), cost per truck trip in J3 ($180).`,formulas:[{cell:`E5 (fill to E5:E30)`,formula:`=ROUNDUP(C5/$J$2,0)`},{cell:`F5 (fill to F5:F30)`,formula:`=E5*$J$3`},{cell:`G5 (fill to G5:G30)`,formula:`=E5*$J$2-C5`}],steps:[`Containers always round UP: a part-load still needs a whole truck.`,`Cost = trucks x cost per truck.`,`Spare space = trucks x capacity - cartons.`],pitfalls:[`ROUND(4.2,0) = 4 leaves cartons behind: always ROUNDUP.`,`INT or ROUNDDOWN also undercounts.`],answer:`1,130 cartons: 4.71, so 5 trucks, $900, spare 70 cartons.`},{id:`capacity-cheaper-pricing-option`,topic:`capacity`,question:`A bicycle kiosk charges $6 per hour (prorated) or $15 per 3-hour pass, whichever is cheaper. For each rental compute hours in E5, hourly charge in F5, passes needed in G5, pass charge in H5, amount paid in I5 and the option used in J5. Fill down to row 60.`,layout:`Rental start times in C5:C60, return times in D5:D60 (same day). Hourly rate in M2 ($6), pass price in M3 ($15), hours per pass in M4 (3).`,formulas:[{cell:`E5 (fill to E5:E60)`,formula:`=ROUND((D5-C5)*24,6)`},{cell:`F5 (fill to F5:F60)`,formula:`=E5*$M$2`},{cell:`G5 (fill to G5:G60)`,formula:`=ROUNDUP(E5/$M$4,0)`},{cell:`H5 (fill to H5:H60)`,formula:`=G5*$M$3`},{cell:`I5 (fill to I5:I60)`,formula:`=MIN(F5,H5)`},{cell:`J5 (fill to J5:J60)`,formula:`=IF(F5<=H5,"Hourly","Pass")`}],steps:[`Hours from the times (x24, rounded).`,`Option 1 = hours x rate. Option 2 = ROUNDUP(hours / 3) passes x pass price.`,`Paid = MIN of the two; label with IF.`],pitfalls:[`Passes need ROUNDUP: 4.5 hours needs 2 passes, not 1.5.`,`Compute each option in its own cell first: MIN is then easy to check.`],answer:`13:00 to 17:30 (4.5 h): $27.00 vs $30.00, pays $27.00 "Hourly". 09:00 to 15:00 (6 h): $36.00 vs $30.00, pays $30.00 "Pass".`},{id:`capacity-end-of-period-stock`,topic:`capacity`,question:`A warehouse tracks weekly stock. For each week compute units shipped in F5 (demand capped by stock available), closing stock in G5 and unmet demand in H5, filling rows 5 to 16; in C6 make each week open with the previous closing stock and fill down to C16.`,layout:`Opening stock in C5:C16 (only C5 typed: 500), receipts in D5:D16, demand in E5:E16.`,formulas:[{cell:`F5 (fill to F5:F16)`,formula:`=MIN(C5+D5,E5)`},{cell:`G5 (fill to G5:G16)`,formula:`=C5+D5-F5`},{cell:`H5 (fill to H5:H16)`,formula:`=E5-F5`},{cell:`C6 (fill to C6:C16)`,formula:`=G5`}],steps:[`Available this week = opening + receipts.`,`Shipped = MIN(available, demand).`,`Closing = available - shipped; next opening = this closing.`,`Unmet demand = demand - shipped.`],pitfalls:[`Typing each week opening stock by hand breaks the chain: only week 1 is typed.`,`A negative closing stock means the MIN is missing.`],answer:`Week 1: 500 + 200 in, demand 650: ship 650, close 50. Week 2: 50 + 0 in, demand 300: ship 50, close 0, unmet 250.`},{id:`trend-forecast-fill-down`,topic:`trend`,question:`A bubble-tea chain has 24 months of order history. In C29 forecast month 25 with a straight-line trend and fill down to C34 for months 25 to 30.`,layout:`Month numbers 1 to 30 in B5:B34 (B5:B28 history, B29:B34 months to forecast). Orders for months 1 to 24 in C5:C28.`,formulas:[{cell:`C29 (fill to C29:C34)`,formula:`=TREND($C$5:$C$28,$B$5:$B$28,B29)`,note:`known y, known x, new x`},{cell:`C29 (alternative)`,formula:`=FORECAST.LINEAR(B29,$C$5:$C$28,$B$5:$B$28)`}],steps:[`TREND(known_y, known_x, new_x): y = orders, x = month number.`,`Lock the history ranges; leave the new x (B29) relative.`,`Fill to C34 and check C34 still reads $C$5:$C$28.`],pitfalls:[`Unlocked ranges slide down and treat earlier forecasts as history.`,`Swapping y and x fits the wrong line.`,`If the periods are month names, use a column of month numbers as x.`],answer:`Six forecasts in C29:C34 that change by the same amount (the slope) each month.`},{id:`trend-forecast-linear-driver`,topic:`trend`,question:`A retail chain models monthly sales against advertising spend (both in $000). In G4 forecast sales for the ad spend planned in G3.`,layout:`Ad spend history in B5:B10 (10, 12, 15, 18, 20, 25), sales in C5:C10 (120, 131, 150, 163, 178, 205), both in $000. Planned ad spend in G3 (22).`,formulas:[{cell:`G4`,formula:`=FORECAST.LINEAR(G3,C5:C10,B5:B10)`,note:`new x FIRST, then known y, then known x`},{cell:`G4 (same with TREND)`,formula:`=TREND(C5:C10,B5:B10,G3)`}],steps:[`x = the driver (ad spend), y = what you forecast (sales).`,`FORECAST.LINEAR(new_x, known_y, known_x) vs TREND(known_y, known_x, new_x): different order, same answer.`,`Quote the result with units.`],pitfalls:[`Using the TREND argument order inside FORECAST.LINEAR gives a nonsense value.`],answer:`G4 = 188.06, about $188,000 of sales (line: y = 5.667x + 63.38).`},{id:`trend-equation-from-chart`,topic:`trend`,question:`A scatter chart of quarterly revenue (x = quarter 1 to 12) has a linear trendline labelled y = 152.4x + 3180. (i) Explain the slope and intercept. (ii) In C17 forecast quarter 13 from the equation and in D17 with TREND as a check. (iii) In G5 and G6 recover the slope and intercept from the data.`,layout:`Quarter numbers in B5:B17 (1 to 12 history, 13 in B17), revenue in $000 for quarters 1 to 12 in C5:C16. Slope typed in G3 (152.4), intercept in G4 (3180).`,formulas:[{cell:`C17`,formula:`=G3*B17+G4`,note:`y = m x + c`},{cell:`D17`,formula:`=TREND($C$5:$C$16,$B$5:$B$16,B17)`},{cell:`G5`,formula:`=TREND(C5:C16,B5:B16,1)-TREND(C5:C16,B5:B16,0)`,note:`slope = line value at x=1 minus at x=0`},{cell:`G6`,formula:`=TREND(C5:C16,B5:B16,0)`,note:`intercept = line value at x=0`},{cell:`G5 (alternative, not taught)`,formula:`=SLOPE(C5:C16,B5:B16)`}],steps:[`Chart: Insert > Scatter on B5:C16, Add Trendline > Linear > Display Equation on chart.`,`Slope 152.4: revenue rises about $152,400 per quarter. Intercept 3180: the line value at x = 0.`,`Forecast = 152.4 x 13 + 3180; TREND on the same data agrees up to the rounding of the label.`],pitfalls:[`On a LINE chart the trendline uses x = 1, 2, 3, ... whatever the labels; on a scatter it uses the real x values (e.g. years 2019, 2020), giving a very different intercept.`,`The chart label is rounded, so D17 can differ from C17 in the last digits.`],answer:`C17 = 152.4 x 13 + 3180 = 5,161.2, about $5.16 million in quarter 13.`},{id:`goal-seek-break-even-price`,topic:`goal-seek`,question:`A start-up sells a gadget whose demand falls as the price rises. Use Goal Seek to find the lowest price in B4 at which profit in B9 is exactly 0, then find the second break-even price.`,layout:`Price in B4 (typed input). Unit variable cost in B5 ($8), fixed cost in B6 ($30,000). Demand intercept in E4 (6000), demand slope in E5 (150 units per $1). Units in B7, revenue in B8, profit in B9.`,formulas:[{cell:`B7`,formula:`=E4-E5*B4`},{cell:`B8`,formula:`=B4*B7`},{cell:`B9`,formula:`=B8-B5*B7-B6`}],tool:[`Type a start price of 15 in B4`,`Data > What-If Analysis > Goal Seek`,`Set cell: B9`,`To value: 0`,`By changing cell: B4`,`Repeat from a start price of 35 for the second root`],steps:[`Build units, revenue and profit as formulas that depend on B4.`,`Type a start value in B4 near the answer you want.`,`Goal Seek B9 to 0 by changing B4; check B9 shows 0 (or a tiny number).`,`Profit is a hill here, so there are two break-even prices: rerun from a high start.`],pitfalls:[`B4 must hold a typed number, not a formula.`,`Goal Seek usually returns the root nearest the start value, never both: run it twice.`],answer:`B4 = $16.52 from a start of 15 and $31.48 from a start of 35 (exact roots 24 +/- SQRT(56)). Profit is positive between them.`},{id:`goal-seek-latest-finish-time`,topic:`goal-seek`,question:`A recording studio prices by session length: the band rate applies to the whole session, prorated by the minute. A band booked from 14:00 has $150 to spend. Use Goal Seek to find the LATEST end time in B5 that keeps the charge in B8 at the budget.`,layout:`Start time in B4 (14:00). End time in B5 (typed input). Hours in B6, hourly rate in B7, charge in B8. Budget in B10 ($150). Rate table: lower bounds in hours E4:E6 (0, 2, 4), hourly rates F4:F6 ($45, $40, $36).`,formulas:[{cell:`B6`,formula:`=ROUND((B5-B4)*24,6)`},{cell:`B7`,formula:`=VLOOKUP(B6,$E$4:$F$6,2,TRUE)`},{cell:`B8`,formula:`=B6*B7`}],tool:[`Type a start end time of 18:30 in B5 (inside the top band)`,`Data > What-If Analysis > Goal Seek`,`Set cell: B8`,`To value: 150 (typed: the box cannot point at B10)`,`By changing cell: B5`,`Format B5 as hh:mm:ss and check B6 is still at least 4 hours`],steps:[`The charge DROPS where a cheaper band starts (3.99 h costs $159.60, 4 h costs $144), so it is not monotonic.`,`Two end times cost exactly $150: 17:45 (3.75 h at $40) and 18:10 (4.1667 h at $36). The latest is 18:10.`,`Start Goal Seek inside the top band (18:30) so it converges to 18:10, then confirm the band in B6/B7.`],pitfalls:[`Starting below 18:00 (e.g. 17:00) tends to converge to 17:45, which is not the latest time.`,`Report the end time in B5, not the charge.`,`Goal Seek can stop a fraction of a second away: report 18:10:00.`],answer:`B5 = 18:10:00 (4 h 10 min at $36/h = $150). Any later end time costs more than $150.`},{id:`goal-seek-required-rate`,topic:`goal-seek`,question:`A saver has $20,000 now and adds $500 at the end of every month for 10 years. Use Goal Seek to find the annual rate in B2 (compounded monthly) that makes the balance in B7 reach $120,000. Check it with a formula in B8.`,layout:`Annual rate in B2 (typed input, start at 5%). Years in B3 (10). Amount now in B4 ($20,000). Monthly deposit in B5 ($500). Balance after 10 years in B7.`,formulas:[{cell:`B7`,formula:`=FV(B2/12,B3*12,-B5,-B4)`,note:`deposits are paid in, so negative`},{cell:`B8 (check without Goal Seek)`,formula:`=RATE(B3*12,-B5,-B4,120000)*12`}],tool:[`Data > What-If Analysis > Goal Seek`,`Set cell: B7`,`To value: 120000`,`By changing cell: B2`],steps:[`Make B7 a formula of B2 with monthly rate B2/12 and B3*12 periods.`,`Goal Seek B7 to 120000 by changing B2.`,`Format B2 as a percentage with 2 decimals.`],pitfalls:[`With positive deposits FV returns a negative balance and Goal Seek heads the wrong way.`,`RATE returns a monthly rate when nper is in months: x12 for the annual rate.`],answer:`B2 = 6.21% a year (0.517% a month x 12 = 6.2056%).`},{id:`goal-seek-units-target-profit`,topic:`goal-seek`,question:`A craft brewery wants a profit of $50,000 this year. Use Goal Seek to find the cases in B4 that give that profit in B9. Check with a formula in B11 and give the whole number of cases needed in B12.`,layout:`Cases sold in B4 (typed input). Price per case in B5 ($25), variable cost per case in B6 ($9.50), fixed costs in B7 ($82,000). Revenue in B8, profit in B9.`,formulas:[{cell:`B8`,formula:`=B4*B5`},{cell:`B9`,formula:`=B8-B4*B6-B7`},{cell:`B11 (closed-form check)`,formula:`=(B7+50000)/(B5-B6)`},{cell:`B12`,formula:`=ROUNDUP(B4,0)`}],tool:[`Data > What-If Analysis > Goal Seek`,`Set cell: B9`,`To value: 50000`,`By changing cell: B4`],steps:[`Profit = cases x (price - variable cost) - fixed costs.`,`Goal Seek B9 to 50000 by changing B4.`,`Cases come in whole units: round UP so the target is reached.`],pitfalls:[`Rounding down (8,516) misses the target by $2.`],answer:`B4 = 8,516.13, so B12 = 8,517 cases (8,516 cases give only $49,998).`},{id:`solver-product-mix`,topic:`solver`,question:`A teak-furniture workshop makes tables, chairs and benches. Use Solver to find the whole numbers of each in C5:E5 that maximise total profit in F6, within carpentry hours, finishing hours, teak supply and a market limit on chairs.`,layout:`Decisions (units) in C5:E5: tables, chairs, benches. Unit profits in C6:E6 ($150, $55, $105). Use per unit in C9:E11: carpentry hours (5, 2, 4), finishing hours (3, 1, 2), teak board-feet (16, 5, 12). Used in F9:F11, available in G9:G11 (420, 220, 1400). Chair market limit in G12 (70).`,formulas:[{cell:`F6`,formula:`=SUMPRODUCT(C5:E5,C6:E6)`},{cell:`F9 (fill to F9:F11)`,formula:`=SUMPRODUCT($C$5:$E$5,C9:E9)`}],tool:[`Data > Solver`,`Set Objective: $F$6, To: Max`,`By Changing Variable Cells: $C$5:$E$5`,`Subject to: $F$9:$F$11 <= $G$9:$G$11`,`Subject to: $D$5 <= $G$12`,`Subject to: $C$5:$E$5 = integer`,`Make Unconstrained Variables Non-Negative: ticked; Solving Method: Simplex LP`],steps:[`Type 0 in C5:E5 as start values.`,`Objective = SUMPRODUCT(decisions, unit profits); each resource used = SUMPRODUCT(locked decisions, its row).`,`Add constraints as range comparisons, plus integer; Simplex LP.`,`Solve, Keep Solver Solution, record settings and optimal values.`],pitfalls:[`Without $ on $C$5:$E$5 in F9, F10 and F11 multiply the wrong cells.`,`Integer Optimality left at 1% can stop short: set it to 0 in Options.`],answer:`Tables 20, chairs 70, benches 45: profit F6 = $11,575. Carpentry (420) and finishing (220) are fully used, teak 1,210 of 1,400, chairs at the 70 limit.`},{id:`solver-integer-basket-budget`,topic:`solver`,question:`A student club has $250 for orientation-day food and wants as many servings as possible, with at least 2 fruit trays and supply limits. Use Solver to find the whole quantities in C5:F5 that maximise servings in G6.`,layout:`Items in C4:F4 (cracker box, juice pack, fruit tray, sandwich platter). Quantities in C5:F5 (decisions). Servings per item in C6:F6 (12, 11, 21, 31). Prices in C7:F7 ($7.50, $12, $25, $36). Maximum available in C8:F8 (6, 8, 10, 4). Minimum fruit trays in E9 (2). Total servings in G6, total cost in G7, budget in H7 ($250).`,formulas:[{cell:`G6`,formula:`=SUMPRODUCT(C5:F5,C6:F6)`},{cell:`G7`,formula:`=SUMPRODUCT(C5:F5,C7:F7)`}],tool:[`Data > Solver`,`Set Objective: $G$6, To: Max`,`By Changing Variable Cells: $C$5:$F$5`,`Subject to: $G$7 <= $H$7`,`Subject to: $C$5:$F$5 <= $C$8:$F$8`,`Subject to: $E$5 >= $E$9`,`Subject to: $C$5:$F$5 = integer`,`Non-negative ticked; Simplex LP; Options: Integer Optimality 0%`],steps:[`Servings and cost are SUMPRODUCTs of the same quantity row.`,`Budget, supply limits and the fruit minimum become three constraint lines.`,`Integer quantities; solve with Simplex LP.`],pitfalls:[`Without the integer constraint Solver buys fractions of a platter.`,`With Integer Optimality at 1% Solver may stop a few servings short.`],answer:`Crackers 6, juice packs 8, fruit trays 4, platters 0: 244 servings for $241.00 (the unique best basket).`},{id:`solver-min-cost-blend`,topic:`solver`,question:`A coffee roaster blends three beans. Use Solver to find the shares in C5:E5 that minimise cost per kg in F7, with average flavour at least 6.5, caffeine at most 1.8%, robusta share at most 40% and shares summing to 100%.`,layout:`Shares in C5:E5 (Colombia arabica, Brazil arabica, Vietnam robusta). Cost per kg in C7:E7 ($14, $11, $6). Flavour scores in C8:E8 (9, 7, 4). Caffeine in C9:E9 (1.2%, 1.3%, 2.4%). F5 = sum of shares, F7 = blend cost, F8 = blend flavour, F9 = blend caffeine. Limits: H8 minimum flavour (6.5), H9 maximum caffeine (1.8%), H10 maximum robusta share (40%).`,formulas:[{cell:`F5`,formula:`=SUM(C5:E5)`},{cell:`F7`,formula:`=SUMPRODUCT(C5:E5,C7:E7)`},{cell:`F8 (fill to F8:F9)`,formula:`=SUMPRODUCT($C$5:$E$5,C8:E8)`}],tool:[`Data > Solver`,`Set Objective: $F$7, To: Min`,`By Changing Variable Cells: $C$5:$E$5`,`Subject to: $F$5 = 1`,`Subject to: $F$8 >= $H$8`,`Subject to: $F$9 <= $H$9`,`Subject to: $E$5 <= $H$10`,`Non-negative ticked; Simplex LP (no integer: shares are fractions)`],steps:[`Blend properties are share-weighted averages: SUMPRODUCT(shares, property).`,`Shares must sum to 1 (or make E5 = 1 - C5 - D5 and add E5 >= 0).`,`Minimise cost with Simplex LP; report shares as percentages.`],pitfalls:[`Without the sum-to-1 constraint Solver sets every share to 0 (cost $0).`,`If E5 is a formula (remainder share), it must not be in the changing cells.`],answer:`Colombia 35%, Brazil 25%, Vietnam 40%: $10.05 per kg. Flavour exactly 6.5 and robusta at 40% bind; caffeine 1.705% is under the limit.`},{id:`solver-staff-scheduling`,topic:`solver`,question:`A cafe opens 08:00 to 22:00 in seven 2-hour blocks. Staff work one of five 6-hour shifts. Use Solver to choose the whole number of staff per shift in C5:G5 so every block has at least the required staff, at minimum wage cost in H6. Show total staff in H7.`,layout:`Shifts in C4:G4: S1 08-14, S2 10-16, S3 12-18, S4 14-20, S5 16-22. Staff per shift in C5:G5 (decisions). Cost per staff per shift in C6:G6 ($88, $90, $95, $100, $110). Coverage table in C9:G15: 1 if the shift works in that block, else 0 (blocks 08-10 to 20-22 down rows 9 to 15). On duty per block in H9:H15, required in I9:I15 (3, 5, 8, 6, 7, 9, 4).`,formulas:[{cell:`H6`,formula:`=SUMPRODUCT(C5:G5,C6:G6)`},{cell:`H7`,formula:`=SUM(C5:G5)`},{cell:`H9 (fill to H9:H15)`,formula:`=SUMPRODUCT($C$5:$G$5,C9:G9)`}],tool:[`Data > Solver`,`Set Objective: $H$6, To: Min`,`By Changing Variable Cells: $C$5:$G$5`,`Subject to: $H$9:$H$15 >= $I$9:$I$15`,`Subject to: $C$5:$G$5 = integer`,`Non-negative ticked; Simplex LP; Integer Optimality 0%`],steps:[`Coverage matrix: in each block row put 1 under every shift working then.`,`On duty per block = SUMPRODUCT(locked staff row, that block row).`,`One range constraint: on duty >= required; integer staff.`],pitfalls:[`A 6-hour shift covers 3 two-hour blocks: check each column has three 1s.`,`Minimising headcount instead of cost gives many tied answers; use the objective the question asks for.`],answer:`S1 = 7, S2 = 1, S3 = 0, S4 = 5, S5 = 4 (17 staff), cost $1,646. On duty per block: 7, 8, 8, 6, 9, 9, 4.`},{id:`solver-transportation`,topic:`solver`,question:`Three central kitchens (Woodlands, Tuas, Changi) supply four outlets (Orchard, Tampines, Jurong, Bishan). Use Solver to choose crates shipped on each route in C11:F13 that meet every outlet demand at minimum delivery cost in H16 without exceeding kitchen supply.`,layout:`Cost per crate in C5:F7 (rows Woodlands, Tuas, Changi; columns Orchard, Tampines, Jurong, Bishan): Woodlands 6, 9, 7, 4; Tuas 7, 11, 3, 7; Changi 9, 4, 12, 8. Shipments (decisions) in C11:F13. Shipped per kitchen in G11:G13, supply in H11:H13 (300, 250, 200). Received per outlet in C14:F14, demand in C15:F15 (180, 220, 160, 150).`,formulas:[{cell:`H16`,formula:`=SUMPRODUCT(C5:F7,C11:F13)`},{cell:`G11 (fill to G11:G13)`,formula:`=SUM(C11:F11)`},{cell:`C14 (fill to C14:F14)`,formula:`=SUM(C11:C13)`}],tool:[`Data > Solver`,`Set Objective: $H$16, To: Min`,`By Changing Variable Cells: $C$11:$F$13`,`Subject to: $G$11:$G$13 <= $H$11:$H$13`,`Subject to: $C$14:$F$14 >= $C$15:$F$15`,`Non-negative ticked; Simplex LP (add $C$11:$F$13 = integer only if asked; the answer is whole anyway)`],steps:[`Cost grid and shipment grid have the same 3 x 4 shape: SUMPRODUCT them.`,`Row sums = shipped by each kitchen; column sums = received by each outlet.`,`Supply <=, demand >=, minimise with Simplex LP.`],pitfalls:[`Supply (750) exceeds demand (710): supply must be <=, not =, or the model is infeasible.`,`Mixing up rows and columns of the cost grid prices every route wrongly.`],answer:`Woodlands: Orchard 130, Tampines 20, Bishan 150. Tuas: Orchard 50, Jurong 160. Changi: Tampines 200. Minimum cost $3,190; Tuas has 40 crates spare.`},{id:`solver-linearise-step-discount`,topic:`solver`,question:`A sports club spends at most $500 (amount paid). The shop discount depends on the subtotal: 0% below $300, 5% from $300, 10% from $450, looked up in H7. Find whole quantities in C5:F5 (at most 6 each) that maximise usefulness points in H5, solving with Simplex LP.`,layout:`Items in C4:F4 (football, racket, shuttlecock tube, basketball). Quantities in C5:F5 (decisions). Points per item in C6:F6 (6, 8, 3, 7). Prices in C7:F7 ($28, $45, $18, $35). Maximum per item in C8:F8 (6 each). Total points H5, subtotal H6, looked-up rate H7, amount paid H8, budget H9 ($500). Fixed band rate typed in H11, its lower bound in H12, check cell H13. Discount table: lower bounds K5:K7 (0, 300, 450), rates L5:L7 (0%, 5%, 10%).`,formulas:[{cell:`H5`,formula:`=SUMPRODUCT(C5:F5,C6:F6)`},{cell:`H6`,formula:`=SUMPRODUCT(C5:F5,C7:F7)`},{cell:`H7 (original model, non-linear)`,formula:`=VLOOKUP(H6,K5:L7,2,TRUE)`},{cell:`H8`,formula:`=H6*(1-H11)`,note:`linear: uses the FIXED band rate in H11, not the lookup`},{cell:`H13 (check after solving)`,formula:`=VLOOKUP(H6,K5:L7,2,TRUE)=H11`}],tool:[`Type 10% in H11 and 450 in H12 (top band: $500 buys more than $450 of goods)`,`Data > Solver: Set Objective $H$5, To: Max`,`By Changing Variable Cells: $C$5:$F$5`,`Subject to: $H$8 <= $H$9`,`Subject to: $H$6 >= $H$12`,`Subject to: $C$5:$F$5 <= $C$8:$F$8`,`Subject to: $C$5:$F$5 = integer`,`Non-negative ticked; Simplex LP; Integer Optimality 0%`],steps:[`With the VLOOKUP inside, Simplex LP stops with "linearity conditions are not satisfied".`,`Fix the band: paid = subtotal x (1 - fixed rate H11), and force the subtotal into that band (H6 >= 450).`,`Solve with Simplex LP, then confirm H13 is TRUE (the lookup agrees with the fixed rate).`,`If unsure which band wins, solve once per band and keep the best (for a lower band also cap the subtotal, e.g. H6 <= 449.99 for the 5% band).`],pitfalls:[`Fixing the rate without the subtotal >= 450 constraint lets Solver take 10% off a $200 basket.`,`GRG Nonlinear on the VLOOKUP model can stop at a poor answer; Evolutionary is slow and not guaranteed optimal.`],answer:`Footballs 6, rackets 3, shuttlecock tubes 2, basketballs 6: 108 points, subtotal $549, 10% off, paid $494.10 (H13 TRUE).`},{id:`solver-record-keeping-key-style`,topic:`solver`,question:`A courier leases small vans (80 parcels a day, $95 a day) and large vans (150 parcels, $160 a day). It must carry at least 1,200 parcels a day, has 12 drivers (one per van) and parking for 6 large vans. After running Solver for minimum daily cost, record the model in answer cells J4:J10 the way a marking key expects.`,layout:`Vans leased in C5:D5 (small, large; decisions). Cost per van in C6:D6 ($95, $160), parcels per van in C7:D7 (80, 150). Total cost in F6, capacity in F7, vans used (drivers) in F8. Limits: parcels required G7 (1200), drivers available G8 (12), large-van parking D9 (6). Answer cells J4:J10.`,formulas:[{cell:`F6`,formula:`=SUMPRODUCT(C5:D5,C6:D6)`},{cell:`F7`,formula:`=SUMPRODUCT(C5:D5,C7:D7)`},{cell:`F8`,formula:`=SUM(C5:D5)`},{cell:`J4 (objective formula shown as text)`,formula:`=FORMULATEXT(F6)`}],tool:[`Objective: $F$6, Min`,`Changing cells: $C$5:$D$5`,`Constraint: $F$7 >= $G$7 (capacity)`,`Constraint: $F$8 <= $G$8 (drivers)`,`Constraint: $D$5 <= $D$9 (parking)`,`Constraint: $C$5:$D$5 = integer; Make Unconstrained Variables Non-Negative ticked`,`Engine: Simplex LP. Result: 4 small, 6 large, cost $1,340`],steps:[`One line each: objective and Max/Min; changing cells; every constraint; integer and non-negative; engine.`,`Then the optimal decision values and the objective value.`,`Write references as the Solver dialog shows them ($F$6).`],pitfalls:[`Giving only the answer (4 and 6) loses the marks for the settings.`,`Leaving out integer or non-negativity loses marks even if the solution happens to be whole.`],answer:`Small 4, large 6: 1,220 parcels, 10 drivers, $1,340 a day (next best 6 small + 5 large at $1,370).`},{id:`what-if-one-way-data-table`,topic:`what-if`,question:`A theme-park model computes daily revenue in B10 and profit in B12 from the ticket price in B4. Build a one-way data table in E5:G16 showing revenue and profit for ticket prices $40 to $60 in steps of $2.`,layout:`Model: ticket price B4 (input), revenue B10, profit B12. Table block E5:G16: prices in E6:E16 (E6 typed 40), links to the outputs in F5 and G5, E5 left blank.`,formulas:[{cell:`E7 (fill to E7:E16)`,formula:`=E6+2`},{cell:`F5`,formula:`=B10`},{cell:`G5`,formula:`=B12`}],tool:[`Select E5:G16 (link row + price column + empty result cells)`,`Data > What-If Analysis > Data Table`,`Row input cell: (leave blank)`,`Column input cell: $B$4`],steps:[`List the input values down E6:E16.`,`One row up and one column right of the first value, link to each output (=B10, =B12).`,`Select the whole block and run Data Table with B4 as the Column input cell.`],pitfalls:[`Selecting E6:G16 without the link row gives a wrong or empty table.`,`B4 in the Row input box (values run DOWN a column) fills the table with wrong numbers.`,`The input cell must be on the same sheet as the table.`],answer:`Each row of F6:G16 shows revenue and profit if B4 took that price.`},{id:`what-if-two-way-data-table`,topic:`what-if`,question:`A home-loan model computes the monthly instalment in B8 from the annual rate in B2 and the term in years in B3. Build a two-way data table in E4:J10 with rates 2.5% to 4.5% across and terms 10 to 35 years down.`,layout:`Model: annual rate B2, years B3, loan amount B4 ($500,000), instalment B8. Table block E4:J10: E4 = link to the output, rates (2.5%, 3%, 3.5%, 4%, 4.5%) in F4:J4, terms (10, 15, 20, 25, 30, 35) in E5:E10.`,formulas:[{cell:`B8`,formula:`=-PMT(B2/12,B3*12,B4)`,note:`positive instalment`},{cell:`E4`,formula:`=B8`}],tool:[`Select E4:J10`,`Data > What-If Analysis > Data Table`,`Row input cell: $B$2 (rates run across the top row)`,`Column input cell: $B$3 (terms run down the first column)`],steps:[`Output link in the top-left corner (E4).`,`One input across the top row, the other down the first column.`,`Row input = the input across the top; Column input = the input down the side.`],pitfalls:[`Swapping the row and column input cells puts every value in the wrong place without any error.`],answer:`F5:J10 holds the instalment for each rate and term; the 3%, 30-year cell is $2,108.02.`},{id:`what-if-pick-best-input`,topic:`what-if`,question:`From the one-way data table of ticket prices and profits, return in J5 the price with the highest profit, in J6 that profit, and in J7 how many listed prices reach the profit target in J2.`,layout:`Data table results: ticket prices in E6:E16, revenue in F6:F16, profit in G6:G16. Profit target in J2 ($20,000).`,formulas:[{cell:`J5`,formula:`=INDEX(E6:E16,MATCH(MAX(G6:G16),G6:G16,0))`},{cell:`J6`,formula:`=MAX(G6:G16)`},{cell:`J7`,formula:`=COUNTIF(G6:G16,">="&J2)`}],steps:[`MAX of the result column finds the best profit.`,`INDEX/MATCH returns the input value on the same row.`,`COUNTIF with ">="&cell counts results meeting a target.`],pitfalls:[`The best listed price is only the best of the values tried; a finer step or Solver could do slightly better: say so.`,`Data-table cells cannot be edited one by one.`],answer:`J5 is one of the listed prices, J6 its profit, J7 a count between 0 and 11.`},{id:`tvm-monthly-loan-payment`,topic:`tvm`,question:`A customer borrows for a car at an annual rate compounded monthly, repaid monthly. In B6 compute the monthly instalment as a positive amount and in B7 the total interest paid.`,layout:`Annual rate in B2 (3.2%), years in B3 (7), loan amount in B4 ($85,000).`,formulas:[{cell:`B6`,formula:`=-PMT(B2/12,B3*12,B4)`,note:`PMT is negative for a loan received; the minus shows it positive`},{cell:`B7`,formula:`=B6*B3*12-B4`}],steps:[`Monthly rate = annual / 12; payments = years x 12.`,`PMT(rate, nper, pv): the loan is received, so pv is positive and PMT is negative.`,`Total interest = all payments - amount borrowed.`],pitfalls:[`PMT(B2,B3,B4) with yearly inputs gives a yearly payment.`,`This formula is for a rate compounded monthly; a "flat rate" quote is a different calculation.`],answer:`B6 = $1,130.81 a month; B7 = $9,987.93 total interest.`},{id:`tvm-payment-with-balloon`,topic:`tvm`,question:`A clinic finances equipment over 5 years at an annual rate (monthly payments and compounding), with a balloon payment due with the last instalment. In B7 compute the regular monthly payment (positive) and in B8 the payment without a balloon.`,layout:`Annual rate B2 (4.5%), years B3 (5), amount financed B4 ($150,000), balloon B5 ($30,000).`,formulas:[{cell:`B7`,formula:`=-PMT(B2/12,B3*12,B4,-B5)`,note:`fv = -balloon: money still to be paid at the end`},{cell:`B8`,formula:`=-PMT(B2/12,B3*12,B4)`}],steps:[`pv = amount financed (+), fv = balloon (-): both are on the loan side.`,`The balloon lowers the regular payment.`],pitfalls:[`+B5 as fv means you RECEIVE $30,000 at the end, which raises the payment.`],answer:`B7 = $2,349.66 a month; B8 = $2,796.45 without the balloon.`},{id:`tvm-pv-annuity-max-loan`,topic:`tvm`,question:`A couple can afford a fixed monthly payment on a 25-year home loan at an annual rate compounded monthly. In B6 compute the largest loan they can take.`,layout:`Annual rate B2 (3.5%), years B3 (25), affordable monthly payment B4 ($2,400).`,formulas:[{cell:`B6`,formula:`=PV(B2/12,B3*12,-B4)`,note:`payments made are negative, so the loan comes out positive`}],steps:[`The largest loan = present value of the payments they can afford.`,`Monthly rate and months; payment entered negative.`],pitfalls:[`2,400 x 300 = $720,000 ignores interest: far too high.`],answer:`B6 = $479,402.12.`},{id:`tvm-fv-savings-topups`,topic:`tvm`,question:`An investor puts a lump sum into a fund now and adds a fixed amount at the end of every month. In B7 compute the balance after the given years and in B8 the interest earned.`,layout:`Annual rate B2 (4%, compounded monthly), years B3 (15), amount now B4 ($10,000), monthly top-up B5 ($800).`,formulas:[{cell:`B7`,formula:`=FV(B2/12,B3*12,-B5,-B4)`},{cell:`B8`,formula:`=B7-B4-B5*B3*12`,note:`balance - everything paid in`}],steps:[`Money paid in is negative: -B5 (pmt) and -B4 (pv).`,`FV then comes out positive.`,`Interest = balance - lump sum - all top-ups.`],pitfalls:[`Leaving out pv (the lump sum) ignores the $10,000 and its growth.`],answer:`B7 = $215,075.41; paid in $154,000; B8 = $61,075.41.`},{id:`tvm-rate-instalment-plan`,topic:`tvm`,question:`A store sells a TV for a cash price or 24 monthly instalments starting one month from now. In B6 compute the implied monthly rate, in B7 the nominal annual rate and in B8 the effective annual rate.`,layout:`Cash price B2 ($2,999), instalment B3 ($139), number of instalments B4 (24).`,formulas:[{cell:`B6`,formula:`=RATE(B4,-B3,B2)`},{cell:`B7`,formula:`=B6*12`},{cell:`B8`,formula:`=(1+B6)^12-1`}],steps:[`Treat the cash price as a loan received (+) repaid by the instalments (-).`,`RATE gives the rate per month; x12 for the nominal annual rate.`,`Effective annual = (1 + monthly)^12 - 1.`],pitfalls:[`Same signs on price and instalment give #NUM!.`,`Reporting the monthly rate as the annual rate understates it 12 times.`],answer:`B6 = 0.870% a month; B7 = 10.44% a year; B8 = 10.96%.`},{id:`tvm-nper-pay-off`,topic:`tvm`,question:`A credit-card balance is charged interest monthly. Paying a fixed amount at the end of each month and spending nothing more, in B6 compute the months needed to clear it and in B7 the whole number of payments.`,layout:`Balance B2 ($8,000), annual rate B3 (24%, i.e. 2% a month), monthly payment B4 ($300).`,formulas:[{cell:`B6`,formula:`=NPER(B3/12,-B4,B2)`},{cell:`B7`,formula:`=ROUNDUP(B6,0)`}],steps:[`Monthly rate = B3 / 12.`,`Balance owed is pv (+), payments are pmt (-).`,`Round the months up: the last payment is a smaller one.`],pitfalls:[`If the payment is below the monthly interest ($160 here) the debt never clears and NPER returns #NUM!.`],answer:`B6 = 38.49 months, so B7 = 39 payments.`},{id:`tvm-npv-time0-outside`,topic:`tvm`,question:`A bakery chain considers a new outlet costing $250,000 now with net cash flows over 6 years. In C13 compute the NPV at the rate in B2, in C14 decide "Accept" or "Reject", and in C15 compute the IRR.`,layout:`Discount rate B2 (8%). Cash flows in C5:C11: C5 = year 0 (-250,000), C6:C11 = years 1 to 6 (50,000, 58,000, 65,000, 65,000, 60,000, 45,000).`,formulas:[{cell:`C13`,formula:`=NPV(B2,C6:C11)+C5`,note:`NPV() discounts its first value one year, so year 0 stays outside`},{cell:`C14`,formula:`=IF(C13>0,"Accept","Reject")`},{cell:`C15`,formula:`=IRR(C5:C11)`}],steps:[`NPV(rate, years 1 to n) + year-0 flow (already negative).`,`Accept if NPV > 0.`,`IRR takes the whole range including year 0.`],pitfalls:[`=NPV(B2,C5:C11) also discounts the outlay and returns $13,509.82: wrong.`],answer:`C13 = $14,590.61, "Accept". C15 = 9.90%, above the 8% rate (consistent).`},{id:`tvm-irr-accept-reject`,topic:`tvm`,question:`A factory can install rooftop solar for $180,000. It saves $28,000 a year for 10 years and the panels are sold for $10,000 at the end of year 10. In C17 compute the IRR, in C18 decide against the hurdle rate, and in C19 compute the NPV at the hurdle rate.`,layout:`Hurdle rate B2 (7%). Cash flows in C5:C15: C5 = year 0 (-180,000), C6:C14 = years 1 to 9 (28,000 each), C15 = year 10 (38,000 = 28,000 + 10,000).`,formulas:[{cell:`C17`,formula:`=IRR(C5:C15)`},{cell:`C18`,formula:`=IF(C17>B2,"Accept","Reject")`},{cell:`C19`,formula:`=NPV(B2,C6:C15)+C5`}],steps:[`One cell per year in time order, year 0 first.`,`IRR over the whole range; accept if IRR > hurdle.`,`NPV at the hurdle should then be positive: a consistency check.`],pitfalls:[`IRR needs the year-0 flow inside the range (unlike NPV).`,`Add the resale to the year-10 flow; do not give it its own year.`],answer:`C17 = 9.48% > 7%: "Accept". C19 = $21,743.78.`},{id:`tvm-lump-sum-vs-monthly`,topic:`tvm`,question:`A retiring business owner can take a lump sum now or receive a fixed amount at the end of each month for 5 years. In B7 compute the present value of the monthly option, in B8 its difference from the lump sum, and in B9 recommend an option.`,layout:`Annual rate B2 (5%, compounded monthly), number of months B3 (60), monthly amount B4 ($1,800), lump sum now B5 ($95,000).`,formulas:[{cell:`B7`,formula:`=PV(B2/12,B3,-B4)`},{cell:`B8`,formula:`=B7-B5`,note:`positive means the monthly stream is worth more`},{cell:`B9`,formula:`=IF(B8>0,"Monthly payments","Lump sum")`}],steps:[`Bring the stream to today: PV at the monthly rate.`,`Compare with the lump sum (already in today money).`,`Recommend the larger value, and say it depends on the rate.`],pitfalls:[`Comparing 60 x 1,800 = $108,000 with $95,000 ignores the time value of money.`,`Annual rate with monthly periods makes the stream look far less valuable.`],answer:`B7 = $95,383.27, B8 = $383.27: "Monthly payments" at 5%, by a small margin (a higher rate would favour the lump sum).`},{id:`tvm-start-of-period-type1`,topic:`tvm`,question:`A firm leases an office for 36 months with rent paid at the START of each month. In B6 compute the present value of the rent at the given rate; in B7 compute it as if rent were paid at the end of each month.`,layout:`Annual rate B2 (6%, compounded monthly), months B3 (36), monthly rent B4 ($4,500).`,formulas:[{cell:`B6`,formula:`=PV(B2/12,B3,-B4,0,1)`,note:`type 1 = payments at the start of each period`},{cell:`B7`,formula:`=PV(B2/12,B3,-B4)`}],steps:[`Start-of-period payments: last argument type = 1 (fv = 0 before it).`,`The same with type 0 (or omitted) for end-of-period.`],pitfalls:[`Forgetting the 0 for fv puts the 1 in the fv slot: =PV(r,n,pmt,1) is wrong.`],answer:`B6 = $148,659.17; B7 = $147,919.57 (B6 = B7 x 1.005: each payment is one month earlier).`},{id:`tvm-loan-balance-after-k`,topic:`tvm`,question:`A home loan is repaid monthly over 25 years. In B7 compute the monthly payment (as Excel returns it, negative) and in B8 the balance still owed right after the payment number in B5.`,layout:`Annual rate B2 (2.6%, compounded monthly), years B3 (25), loan B4 ($600,000), payments made B5 (60).`,formulas:[{cell:`B7`,formula:`=PMT(B2/12,B3*12,B4)`},{cell:`B8`,formula:`=-FV(B2/12,B5,B7,B4)`,note:`FV of the loan and the payments made; minus shows the debt as positive`},{cell:`B8 (alternative)`,formula:`=PV(B2/12,B3*12-B5,B7)`,note:`PV of the payments still due`}],steps:[`Payment over the full term with PMT (negative).`,`Balance after k payments = -FV(rate, k, payment, loan).`,`Check: PV of the remaining payments gives the same number.`],pitfalls:[`The payment must be negative and the loan positive inside FV, or the balance grows instead of shrinking.`,`Use the full term for PMT but k (B5) for FV.`],answer:`B7 = -$2,722.02; B8 = $508,989.88 still owed after 5 years.`},{id:`interpret-recommend-buy-or-lease`,topic:`interpret`,question:`The model gives the present value of the total cost of buying (D20) and leasing (E20) a delivery van over 5 years. In D22 compute the difference and in D23 write a 2-3 sentence recommendation.`,layout:`PV of the cost of buying in D20 ($182,400), PV of the cost of leasing in E20 ($176,900), both at the 6% discount rate in B2.`,formulas:[{cell:`D22`,formula:`=D20-E20`,note:`positive means buying costs more`}],steps:[`Start with the decision: "Lease."`,`Quote both numbers and the difference with units and the rate.`,`Give one assumption that could change the answer.`],pitfalls:[`A number without a decision earns little: say what to do.`],answer:`Lease. At a 6% discount rate leasing costs $176,900 in present-value terms against $182,400 for buying, a saving of $5,500 (D22). The gap depends on the discount rate and the resale value assumed for the van, so a lower rate or a higher resale value would narrow it.`},{id:`interpret-compare-solver-vs-current`,topic:`interpret`,question:`The current furniture plan earns the profit in F7; the Solver plan earns the profit in F6. In F8 compute the improvement, in F9 the percentage improvement, and explain in 2-3 sentences what Solver changed.`,layout:`Solver-plan profit F6 ($11,575: 20 tables, 70 chairs, 45 benches). Current-plan profit F7 ($10,900: 30 tables, 40 chairs, 40 benches). Carpentry 420 h and finishing 220 h available; the current plan uses 390 h and 210 h.`,formulas:[{cell:`F8`,formula:`=F6-F7`},{cell:`F9`,formula:`=F6/F7-1`}],steps:[`Lead with the gain in dollars and percent.`,`Say what moved (fewer tables, more chairs and benches) and why it helps (idle hours now used).`,`One assumption: everything made can be sold at the listed profits.`],pitfalls:[`Do not invent reasons: check claims such as "more profit per hour" against the data before writing them.`],answer:`The Solver plan earns $675 more (6.19%). It makes 10 fewer tables but 30 more chairs (up to the 70 limit) and 5 more benches, so carpentry and finishing are fully used (420 h and 220 h) instead of leaving 30 and 10 hours idle. This assumes all units sell at the listed unit profits.`},{id:`interpret-limitation-trend`,topic:`interpret`,question:`Your TREND forecast for month 36 in C40 is based on 24 months of history. In D40 compute how far the forecast differs from the last actual value, then write two limitations of using it for planning in D41.`,layout:`Month numbers 1 to 24 in B5:B28 with orders in C5:C28 (history; last actual in C28). Forecast month 36 in B40, forecast in C40.`,formulas:[{cell:`C40`,formula:`=TREND($C$5:$C$28,$B$5:$B$28,B40)`},{cell:`D40`,formula:`=C40-C28`}],steps:[`State the number first (the forecast and the gap in D40).`,`Limitation 1: extrapolation 12 months past the data assumes the same straight-line growth.`,`Limitation 2: a single point with no range, ignoring seasonality and one-off events.`],pitfalls:[`Generic remarks ("forecasts can be wrong") earn less than ones tied to this model.`],answer:`The forecast extrapolates 12 months beyond the data and assumes orders keep changing by the same amount every month, so any change in trend, seasonality or one-off event is ignored. It is also a single point estimate with no error range, so plans should allow a margin and be updated as new months arrive.`}],S=`One pharmacist. Opening time 09:00 in G14 (the end time of an imaginary customer 0) and E14 holds =G14. Customers 1-50 in rows 15-64: inter-arrival gaps C15:C64 and service times D15:D64 (Excel times), arrival times E14:E64, service starts F15:F64, service ends G14:G64, waits H15:H64, times in system I15:I64.`,C=`Number of counters c in G4. Opening time 09:00 in G14 (the end time of an imaginary customer 0) and E14 holds =G14. Customers 1-50 in rows 15-64: inter-arrival gaps C15:C64 and service times D15:D64 (Excel times), arrival times E14:E64, service starts F15:F64, service ends G14:G64, waits H15:H64, number in system at arrival J15:J64.`,w=`Single check-in counter; each row is a group of visitors. Groups 1-50 in rows 15-64: group numbers A15:A64, group sizes B15:B64, inter-arrival gaps C15:C64, service times D15:D64, arrivals E14:E64 (E14 = opening time 09:00), service starts F15:F64, service ends G14:G64 (G14 = opening time 09:00), waits H15:H64, times in system I15:I64 (all Excel times), number in system at arrival J15:J64. Thresholds in minutes: 5 in B6 and 10 in B7.`,T=`Car wash with 2 washing bays in I4. Balk limit 6 in F4 (a driver balks when MORE than 6 cars are already in the system), renege limit 0:20 typed as a time in G4, opening time 08:00 in I14 (the end time of an imaginary car 0). Cars 1-50 in rows 15-64: gaps C15:C64, wash times D15:D64, arrivals E15:E64, potential start F15:F64, potential wait G15:G64, actual start H15:H64, end time I14:I64, wait J15:J64, time in system K15:K64, system length at arrival L15:L64. Cars that balk or renege hold "" where they have no value.`,E=`Bumboats from a jetty: interval 10 (minutes) in B2, seats per boat 12 in D2, shelter capacity 25 in G2, fare $4 in J2, loading time 15 (seconds per passenger) in K2. Arrivals per interval 6, 9, 12, 15, 18 in M6:M10 (probabilities 0.15, 0.25, 0.30, 0.20, 0.10) with CRF lower bounds 0, 0.15, 0.40, 0.70, 0.90 in N6:N10. Row 6 is the start state: C6 = 07:00 and G6 = 0 (nobody left behind). Departures 1-36 in rows 7-42: scheduled time C7:C42, arrivals D7:D42, in shelter E7:E42, boarded F7:F42, left behind G6:G42, turned away H7:H42, actual departure I7:I42, revenue J7:J42.`,D=`Umbrella sharing at four MRT stations numbered 1-4. Route table rows 5-16 (one row per origin-destination pair): origin station number A5:A16, destination station number B5:B16, potential borrowers n C5:C16 (some 0), borrow probability p D5:D16, simulated trips E5:E16, fare F5:F16. Station table rows 5-8: station number H5:H8, start stock I5:I8, departures J5:J8, arrivals K5:K8, end stock L5:L8, surplus M5:M8. Target stock per station 30 in P2, cost per umbrella moved $1.50 in P3, fare matrix P5:S8 (row = origin station 1-4, column = destination station 1-4).`,O=`One simulated weekend of a pop-up stall: profit (the output) in H20, computed from RAND() inputs. One-way Data Table in K5:L505: trial numbers 1-500 in K6:K505, link cell L5 (=H20), replicated profits L6:L505. N2 is a blank cell that no formula uses.`,k=[{id:`discrete-rv-prob-from-freq`,topic:`discrete-rv`,question:`A chicken-rice stall logged how many orders arrived in each of 200 five-minute intervals. In C5, compute the probability of each order count from its frequency, and fill down to C9. In C10, check that the probabilities add up to 1.`,layout:`Order counts 0, 1, 2, 3, 4 in A5:A9; frequencies 20, 50, 70, 40, 20 (200 intervals in total) in B5:B9. Probabilities go in C5:C9 and the check in C10.`,formulas:[{cell:`C5 (fill to C5:C9)`,formula:`=B5/SUM($B$5:$B$9)`,note:`frequency over the anchored total`},{cell:`C10`,formula:`=SUM(C5:C9)`,note:`must show 1`}],steps:[`Divide each frequency by the total of all frequencies.`,`Anchor the total range ($B$5:$B$9) so it does not slide as you fill down.`,`Check that the probabilities add up to exactly 1.`],pitfalls:[`Dividing by a typed 200 breaks if the data change; divide by SUM of the range.`,`Without the $ signs, row 6 divides by SUM(B6:B10), which drops B5 and gives wrong probabilities.`],answer:`C5:C9 = 0.10, 0.25, 0.35, 0.20, 0.10 and C10 = 1.`},{id:`discrete-rv-crf-lower-bound`,topic:`discrete-rv`,question:`Using the probabilities in C5:C9, build the cumulative probability (CRF) column in D5:D9 as LOWER bounds, so that a random number can be looked up against it.`,layout:`Order counts 0-4 in A5:A9 and their probabilities 0.10, 0.25, 0.35, 0.20, 0.10 in C5:C9. The CRF lower bounds go in D5:D9.`,formulas:[{cell:`D5`,formula:`=0`,note:`or simply type 0: the first lower bound is always 0`},{cell:`D6 (fill to D6:D9)`,formula:`=D5+C5`,note:`bound above + probability above`},{cell:`D6 (alternative, fill to D6:D9)`,formula:`=SUM($C$5:C5)`,note:`running total of the probabilities above`}],steps:[`Start the column at 0 on the first value row.`,`Each next bound = previous bound + the probability of the row ABOVE.`,`The last bound equals 1 minus the last probability (here 0.90), never 1.`],pitfalls:[`Starting at the first probability (0.10) instead of 0 shifts every draw by one value.`,`Adding the probability of the same row gives upper bounds; LOOKUP then returns a value one row too low and #N/A for small random numbers.`],answer:`D5:D9 = 0, 0.10, 0.35, 0.70, 0.90.`},{id:`discrete-rv-lookup-draw`,topic:`discrete-rv`,question:`Simulate the number of orders in each of the 60 intervals of the lunch period. In G15, draw a value from the order-count distribution, and fill down to G74.`,layout:`Order counts 0-4 in A5:A9 (ascending), CRF lower bounds 0, 0.10, 0.35, 0.70, 0.90 in D5:D9. Intervals 1-60 in F15:F74; the draws go in G15:G74.`,formulas:[{cell:`G15 (fill to G15:G74)`,formula:`=LOOKUP(RAND(),$D$5:$D$9,$A$5:$A$9)`,note:`LOOKUP(value, CRF lower bounds, values)`}],steps:[`RAND() is the lookup value.`,`Lookup vector = the CRF lower-bound column; result vector = the values column. Same size, both anchored.`,`LOOKUP returns the value on the last row whose lower bound is <= RAND().`,`Press F9 a few times: the average of G15:G74 should stay near the expected value 1.95.`],pitfalls:[`Swapping the vectors (values first, CRF second) returns the wrong column.`,`The CRF column must be in ascending order and start at 0.`],answer:`Each cell shows 0-4 and changes on every F9; in the long run about 10% of intervals are 0, 25% are 1, 35% are 2, 20% are 3 and 10% are 4.`},{id:`discrete-rv-vlookup-draw`,topic:`discrete-rv`,question:`A durian stall serves groups of 1 to 5 people. Draw a random group size for each of 40 groups in C15:C54 with VLOOKUP on the group-size table (formula in C15, filled down).`,layout:`Group-size table K4:L8: CRF lower bounds 0, 0.30, 0.55, 0.80, 0.95 in K4:K8 and group sizes 1, 2, 3, 4, 5 in L4:L8 (probabilities 0.30, 0.25, 0.25, 0.15, 0.05). Groups 1-40 in rows 15-54; sizes go in C15:C54.`,formulas:[{cell:`C15 (fill to C15:C54)`,formula:`=VLOOKUP(RAND(),$K$4:$L$8,2,TRUE)`,note:`approximate match on the CRF column`}],steps:[`The CRF lower bounds must be the LEFTMOST column of the table range.`,`Column index 2 returns the group size beside the matched bound.`,`TRUE (or leaving it out) means approximate match: the largest bound <= RAND().`],pitfalls:[`FALSE (exact match) returns #N/A because RAND() almost never equals a bound.`,`If the values sit to the LEFT of the CRF column, VLOOKUP cannot reach them: use LOOKUP(RAND(),CRF,values).`],answer:`Sizes 1-5 that change on F9; the long-run average is 1(0.30) + 2(0.25) + 3(0.25) + 4(0.15) + 5(0.05) = 2.40.`},{id:`discrete-rv-predrawn`,topic:`discrete-rv`,question:`So the first run can be marked, the template gives a fixed random number for each group in B15:B54. In C15, return the group size for that random number instead of using RAND(), and fill down to C54. What size does 0.62 give?`,layout:`Fixed random numbers in B15:B54 (B15 = 0.62). Group-size table: CRF lower bounds 0, 0.30, 0.55, 0.80, 0.95 in K4:K8, group sizes 1-5 in L4:L8.`,formulas:[{cell:`C15 (fill to C15:C54)`,formula:`=LOOKUP(B15,$K$4:$K$8,$L$4:$L$8)`,note:`the given random number replaces RAND()`}],steps:[`Use the given random-number cell as the lookup value, relative so it moves down.`,`Keep the table ranges anchored.`,`Check one row by hand: find the last lower bound that is <= the random number.`],pitfalls:[`Writing RAND() when the paper supplies fixed numbers loses the marks for matching the key.`,`Anchoring the random number ($B$15) makes every group use the first number.`],answer:`0.62 lies between the bounds 0.55 and 0.80, so C15 = 3. With fixed numbers the results do not change on F9.`},{id:`discrete-rv-expected-value`,topic:`discrete-rv`,question:`Check the order-count model: in C12, compute the expected number of orders per interval from the table; in C13, the average of the 60 simulated intervals, so the two can be compared.`,layout:`Order counts 0-4 in A5:A9, probabilities 0.10, 0.25, 0.35, 0.20, 0.10 in C5:C9, simulated counts for 60 intervals in G15:G74.`,formulas:[{cell:`C12`,formula:`=SUMPRODUCT(A5:A9,C5:C9)`,note:`sum of value x probability`},{cell:`C13`,formula:`=AVERAGE(G15:G74)`,note:`simulated average, changes on F9`}],steps:[`Multiply each value by its probability and add up: SUMPRODUCT does both.`,`Average the simulated column.`,`The two should be close; a big gap points to a CRF or LOOKUP error.`],pitfalls:[`SUMPRODUCT with the CRF column instead of the probabilities gives a meaningless number.`],answer:`C12 = 0(0.10) + 1(0.25) + 2(0.35) + 3(0.20) + 4(0.10) = 1.95 orders. C13 changes on every F9 and should land near 1.95.`},{id:`discrete-rv-upper-crf-shifted`,topic:`discrete-rv`,question:`A taxi-stand table gives, for 0 to 4 taxis arriving per minute, the running cumulative probability INCLUDING each value (as in the course DataSim sheet). Without adding a new column, draw the number of taxis arriving in each of 120 minutes in D15:D134 (formula in D15, filled down).`,layout:`Taxi counts 0, 1, 2, 3, 4 in A6:A10, probabilities 0.20, 0.30, 0.25, 0.15, 0.10 in B6:B10, running cumulative probabilities 0.20, 0.50, 0.75, 0.90, 1.00 in C6:C10, and C5 holds 0. Minutes 1-120 in rows 15-134; draws go in D15:D134.`,formulas:[{cell:`D15 (fill to D15:D134)`,formula:`=LOOKUP(RAND(),$C$5:$C$9,$A$6:$A$10)`,note:`CRF range starts one row ABOVE the values`}],steps:[`A running total that includes its own row is an UPPER bound; LOOKUP needs lower bounds.`,`The lower bound of each value is the running total of the row above, so pair C5:C9 (C5 = 0) with the values A6:A10.`,`Both vectors still have the same number of cells (5 and 5).`],pitfalls:[`=LOOKUP(RAND(),$C$6:$C$10,$A$6:$A$10) returns #N/A whenever RAND() < 0.20 and a value one too low otherwise.`],answer:`Taxi counts 0-4 that change on F9. Example: 0.60 matches the bound 0.50 (third position) and returns the third value, 2 taxis.`},{id:`continuous-rv-uniform`,topic:`continuous-rv`,question:`A food-delivery rider takes anywhere between 20 and 35 minutes per delivery, all values equally likely. In D15, simulate the delivery time in minutes for each of 100 orders, and fill down to D114.`,layout:`Minimum 20 (minutes) in B3, maximum 35 (minutes) in B4. Orders 1-100 in rows 15-114; times go in D15:D114.`,formulas:[{cell:`D15 (fill to D15:D114)`,formula:`=$B$3+RAND()*($B$4-$B$3)`,note:`a + RAND() x (b - a)`}],steps:[`RAND() is uniform between 0 and 1; multiplying by (b - a) stretches it to the width of the range.`,`Adding a shifts it to start at the minimum.`,`Anchor both parameter cells.`],pitfalls:[`RANDBETWEEN(20,35) gives whole minutes only; use it only when the question says whole numbers.`,`RAND()*$B$4 alone runs from 0 to 35, not 20 to 35.`],answer:`Values between 20 and 35 that change on F9; the long-run average is (20 + 35)/2 = 27.5 minutes.`},{id:`continuous-rv-uniform-clock`,topic:`continuous-rv`,question:`A supplier van arrives at a random time, equally likely anywhere between 10:00 and 10:30. In C5, simulate its arrival clock time.`,layout:`Earliest time 10:00 in B3 and latest time 10:30 in B4, both typed as times. The arrival time goes in C5 (format h:mm:ss).`,formulas:[{cell:`C5`,formula:`=$B$3+RAND()*($B$4-$B$3)`,note:`uniform between two clock times`},{cell:`C5 (alternative)`,formula:`=TIME(10,0,0)+RAND()*30/1440`,note:`10:00 plus up to 30 minutes`}],steps:[`Clock times are day fractions, so the uniform formula works on them directly.`,`If the width is given in minutes, convert it: 30/1440.`,`Format the result as a time.`],pitfalls:[`=TIME(10,0,0)+RAND()*30 adds up to 30 DAYS.`],answer:`A time between 10:00 and 10:30 that changes on F9; the average is 10:15.`},{id:`continuous-rv-randbetween`,topic:`continuous-rv`,question:`Each visitor to a souvenir kiosk buys a whole number of keychains from 1 to 6, all equally likely. In E15, simulate the number bought by each of 80 visitors, and fill down to E94.`,layout:`Smallest quantity 1 in B3, largest quantity 6 in B4. Visitors 1-80 in rows 15-94; quantities go in E15:E94.`,formulas:[{cell:`E15 (fill to E15:E94)`,formula:`=RANDBETWEEN($B$3,$B$4)`,note:`whole numbers, both ends included`}],steps:[`RANDBETWEEN(bottom, top) returns a whole number, every value equally likely.`,`Both ends are included: 1 and 6 can both appear.`],pitfalls:[`=ROUND($B$3+RAND()*($B$4-$B$3),0) makes the two end values only half as likely as the middle ones.`],answer:`Whole numbers 1-6 that change on F9; the long-run average is (1 + 6)/2 = 3.5 keychains.`},{id:`continuous-rv-normal`,topic:`continuous-rv`,question:`Daily demand for kaya toast sets at a kopitiam is normally distributed with mean 180 and standard deviation 25. In C15, simulate the demand for each of 30 days, and fill down to C44.`,layout:`Mean 180 in B3, standard deviation 25 in B4. Days 1-30 in rows 15-44; demands go in C15:C44.`,formulas:[{cell:`C15 (fill to C15:C44)`,formula:`=NORMINV(RAND(),$B$3,$B$4)`,note:`NORMINV(probability, mean, sd)`}],steps:[`The first argument is the random probability RAND().`,`Then the mean, then the standard deviation.`,`Add ROUND or MAX only if the question asks for whole units or a floor.`],pitfalls:[`NORMINV(RAND(),$B$4,$B$3) swaps the mean and the sd.`,`NORM.INV is the newer name of the same function; NORMINV is the course form.`],answer:`Decimal values that change on F9, almost all within 180 +/- 3 x 25 (105 to 255); the average over many days is near 180.`},{id:`continuous-rv-normal-floor`,topic:`continuous-rv`,question:`Making a bubble-tea order takes a normally distributed time with mean 3 minutes and standard deviation 1.2 minutes, but never less than 0.5 minutes. In D15, simulate the time in minutes for each of 50 orders, and fill down to D64.`,layout:`Mean 3 (minutes) in B3, standard deviation 1.2 (minutes) in B4, minimum 0.5 (minutes) in B5. Orders 1-50 in rows 15-64; times go in D15:D64.`,formulas:[{cell:`D15 (fill to D15:D64)`,formula:`=MAX($B$5,NORMINV(RAND(),$B$3,$B$4))`,note:`MAX applies the floor`}],steps:[`Draw the normal value with NORMINV(RAND(), mean, sd).`,`Wrap it in MAX(floor, draw): any draw below the floor becomes the floor.`],pitfalls:[`MIN instead of MAX caps every time at 0.5.`,`Leaving the floor out lets a few draws go negative.`],answer:`Values of at least 0.5 that change on F9; the average is slightly above 3 because the floor lifts the lowest draws.`},{id:`continuous-rv-normal-round`,topic:`continuous-rv`,question:`The number of walk-in patients at a polyclinic each hour is roughly normal with mean 14 and standard deviation 5. In C15, simulate a whole, never-negative number of patients for each of 10 hours, and fill down to C24.`,layout:`Mean 14 in B3, standard deviation 5 in B4. Hours 1-10 in rows 15-24; counts go in C15:C24.`,formulas:[{cell:`C15 (fill to C15:C24)`,formula:`=MAX(0,ROUND(NORMINV(RAND(),$B$3,$B$4),0))`,note:`round to whole patients, then floor at 0`}],steps:[`Draw the normal value.`,`ROUND(..., 0) makes it a whole number.`,`MAX(0, ...) turns any negative count into 0.`],pitfalls:[`ROUNDUP or ROUNDDOWN shift the average by about half a patient; ROUND keeps it centred.`,`ROUND alone can still give -1 or -2 for a draw far below the mean.`],answer:`Whole numbers 0 or more that change on F9, averaging close to 14.`},{id:`continuous-rv-normal-time`,topic:`continuous-rv`,question:`At an immigration counter each check takes a normally distributed time with mean 4 minutes and standard deviation 1.5 minutes, never less than 1 minute. The queue works in clock times. In D15, simulate the check time as an Excel time, and fill down to D64.`,layout:`Mean 4 (minutes, typed as a number) in B3, standard deviation 1.5 (minutes) in B4, minimum 1 (minute) in B5. Travellers 1-50 in rows 15-64; check times (format mm:ss) go in D15:D64.`,formulas:[{cell:`D15 (fill to D15:D64)`,formula:`=MAX($B$5/1440,NORMINV(RAND(),$B$3/1440,$B$4/1440))`,note:`everything converted to day fractions`},{cell:`D15 (alternative)`,formula:`=MAX($B$5,NORMINV(RAND(),$B$3,$B$4))/1440`,note:`draw and floor in minutes, convert once`}],steps:[`Excel times are fractions of a day: 1 minute = 1/1440.`,`Convert the mean, the sd AND the floor, or work in minutes and divide the final result by 1440.`,`Format the column mm:ss (or [h]:mm:ss).`],pitfalls:[`Converting the mean but not the sd or the floor mixes units: MAX(1, ...) on day fractions makes every check last 1 full day.`,`About 0.0028 in General format is not an error: it is 4 minutes (check with x1440).`],answer:`Times of at least 0:01:00 that change on F9; their average x 1440 is about 4 minutes.`},{id:`continuous-rv-service-by-size`,topic:`continuous-rv`,question:`At a clinic registration desk, registering a family takes a normal time with mean 2 minutes plus 1.5 minutes per family member and standard deviation 0.8 minutes, never below 1 minute. In D15, simulate the registration time as an Excel time for each family, and fill down to D64.`,layout:`Base time 2 (minutes) in B3, extra time per member 1.5 (minutes) in B4, standard deviation 0.8 (minutes) in B5, minimum 1 (minute) in B6. Families 1-50 in rows 15-64 with family sizes in C15:C64; times (format mm:ss) go in D15:D64.`,formulas:[{cell:`D15 (fill to D15:D64)`,formula:`=MAX($B$6,NORMINV(RAND(),$B$3+$B$4*C15,$B$5))/1440`,note:`mean depends on the row; converted to a time at the end`}],steps:[`Build the mean for this row: base + per-member time x family size.`,`Draw in minutes and apply the floor with MAX.`,`Divide the final result by 1440 to get a time value.`],pitfalls:[`Anchoring C15 gives every family the size of the first one.`,`Converting only the mean to a day fraction while the sd and the floor stay in minutes mixes units; stay in minutes and divide once.`],answer:`Times that change on F9; a family of 3 averages about 2 + 1.5 x 3 = 6.5 minutes (0:06:30).`},{id:`continuous-rv-exponential`,topic:`continuous-rv`,question:`Calls to a hotline arrive with exponentially distributed gaps averaging 2.5 minutes. In C15, simulate the gap in minutes (a plain number) for each of 100 calls, and fill down to C114. Give both common forms of the formula.`,layout:`Mean gap 2.5 (minutes) in B3. Calls 1-100 in rows 15-114; gaps go in C15:C114.`,formulas:[{cell:`C15 (fill to C15:C114)`,formula:`=-$B$3*LN(RAND())`,note:`course form`},{cell:`C15 (alternative)`,formula:`=-$B$3*LN(1-RAND())`,note:`inverse CDF; same distribution since 1-RAND() is also uniform`}],steps:[`LN of a number between 0 and 1 is negative, so the leading minus makes the gap positive.`,`Multiply by the MEAN, not the rate.`,`If a rate is given (calls per hour), the mean gap is 1/rate: 24 calls per hour means 60/24 = 2.5 minutes.`],pitfalls:[`Without the minus sign every gap is negative.`,`Putting the rate (24) where the mean (2.5) belongs.`],answer:`Positive values that change on F9 and average about 2.5 minutes: many short gaps, a few long ones.`},{id:`continuous-rv-exp-time`,topic:`continuous-rv`,question:`Cars reach a carpark gantry with exponential gaps averaging 1.5 minutes, and the arrival column holds clock times. In C15, simulate each gap as an Excel time, and fill down to C214.`,layout:`Mean gap 1.5 (minutes, typed as a number) in B3. Cars 1-200 in rows 15-214; gaps (format mm:ss) go in C15:C214.`,formulas:[{cell:`C15 (fill to C15:C214)`,formula:`=-$B$3/1440*LN(RAND())`,note:`mean converted from minutes to a day fraction`},{cell:`C15 (if B3 holds the time 0:01:30)`,formula:`=-$B$3*LN(RAND())`,note:`no /1440 when the mean is already a time`}],steps:[`Check how the mean is stored: a number of minutes (1.5) or a time (0:01:30).`,`A number of minutes must be divided by 1440 before it is added to clock times.`,`A mean typed as a time is already a day fraction: do not divide again.`],pitfalls:[`Dividing a mean that is already a time by 1440 makes the gaps 1440 times too small.`,`Forgetting /1440 on a mean in minutes adds 1.5 DAYS per car.`],answer:`Gaps that change on F9; formatted mm:ss they average about 01:30.`},{id:`continuous-rv-binomial`,topic:`continuous-rv`,question:`Each tour group booked on a river-cruise slot has a known number of members, and each member independently fails to show up with probability 0.08. Some slots have no booking (0 members). In D15, simulate the number of no-shows for each of 40 slots, and fill down to D54.`,layout:`No-show probability 0.08 in B3. Members booked per slot in C15:C54 (whole numbers, some 0). No-shows go in D15:D54.`,formulas:[{cell:`D15 (fill to D15:D54)`,formula:`=IF(C15>0,CRITBINOM(C15,$B$3,RAND()),0)`,note:`CRITBINOM(trials, probability, RAND())`}],steps:[`n independent yes/no trials with the same chance p give a binomial count.`,`CRITBINOM(n, p, RAND()) draws that count.`,`Guard with IF(n>0, ..., 0) so an empty slot always gives 0 and never an error.`],pitfalls:[`The order is trials, probability, random number: CRITBINOM(RAND(),C15,$B$3) is wrong.`,`Anchor p but not n, because n changes row by row.`,`BINOM.INV is the newer name; CRITBINOM is the course form.`],answer:`Whole numbers from 0 to the slot size that change on F9; a slot averages 0.08 x its members (25 members gives 2 no-shows on average).`},{id:`continuous-rv-poisson-approx`,topic:`continuous-rv`,question:`The number of ambulance call-outs per day in a district is Poisson with mean 3.2. Using the course method, simulate the daily count in C15 for 365 days, filling down to C379.`,layout:`Mean 3.2 call-outs per day in B3. Days 1-365 in rows 15-379; counts go in C15:C379.`,formulas:[{cell:`C15 (fill to C15:C379)`,formula:`=CRITBINOM(1000,$B$3/1000,RAND())`,note:`binomial with large n and p = mean/n`}],steps:[`Poisson is the limit of a binomial with large n and small p where n x p = mean.`,`Use n = 1000 (as in the course) and p = mean/1000.`,`The result is a whole number 0, 1, 2, ...`],pitfalls:[`NORMINV for a small-mean count gives decimals and negative values.`,`p must be mean/n (between 0 and 1), not the mean itself.`],answer:`Whole numbers that change on F9, averaging about 3.2 per day.`},{id:`continuous-rv-bernoulli`,topic:`continuous-rv`,question:`Each customer at a mixed-rice stall buys a drink with probability 0.35. In F15, record 1 if the customer buys a drink and 0 if not, and fill down to F74 (60 customers). In F76, compute the simulated share of buyers.`,layout:`Probability 0.35 in B3. Customers 1-60 in rows 15-74; the 1/0 results go in F15:F74 and the share in F76.`,formulas:[{cell:`F15 (fill to F15:F74)`,formula:`=IF(RAND()<$B$3,1,0)`},{cell:`F76`,formula:`=AVERAGE(F15:F74)`,note:`share of 1s`}],steps:[`RAND() < p is TRUE with probability p.`,`Return 1/0 so that SUM counts the buyers and AVERAGE gives the share.`,`If the same random number is needed twice, put RAND() in its own cell and test that cell.`],pitfalls:[`RAND()>$B$3 happens with probability 1 - p = 0.65.`,`Text results ("Yes"/"No") cannot be summed; use 1/0 or COUNTIF.`],answer:`F76 changes on F9 and stays around 0.35 (21 buyers out of 60 on average).`},{id:`continuous-rv-choice-crf`,topic:`continuous-rv`,question:`Customers at a bakery pay by card (50%), PayNow (30%) or cash (20%). In C15, draw one random number per customer; in D15, return the payment method from that number. Fill both down to row 74. Also give the CRF-table version.`,layout:`Customers 1-60 in rows 15-74: random numbers in C15:C74, payment methods in D15:D74. Optional table: CRF lower bounds 0, 0.50, 0.80 in J4:J6 and the methods "Card", "PayNow", "Cash" in K4:K6.`,formulas:[{cell:`C15 (fill to C15:C74)`,formula:`=RAND()`,note:`one stored random number per customer`},{cell:`D15 (fill to D15:D74)`,formula:`=IF(C15<0.5,"Card",IF(C15<0.8,"PayNow","Cash"))`,note:`cumulative cut-offs 0.5 and 0.8`},{cell:`D15 (table alternative)`,formula:`=LOOKUP(C15,$J$4:$J$6,$K$4:$K$6)`,note:`same result from the CRF table`}],steps:[`Store one RAND() in its own cell.`,`Compare it with CUMULATIVE cut-offs: below 0.5 is Card, 0.5 to 0.8 is PayNow, the rest (0.2) is Cash.`,`With many options a CRF table and LOOKUP are easier to check.`],pitfalls:[`=IF(RAND()<0.5,"Card",IF(RAND()<0.8,"PayNow","Cash")) uses two different random numbers: PayNow comes out 0.5 x 0.8 = 40% and Cash 10%.`,`Using the plain probabilities (0.5, 0.3) as cut-offs instead of the cumulative ones (0.5, 0.8).`],answer:`Text labels that change on F9; over many customers about 50% Card, 30% PayNow and 20% Cash.`},{id:`resample-percentile`,topic:`resample`,question:`The template lists 120 recorded taxi-queue waiting times (minutes) in B5:K16. Resample them as a continuous variable: in N15, draw one simulated waiting time, and fill down to N214.`,layout:`Observed waiting times in minutes in the block B5:K16 (12 rows by 10 columns = 120 values). Simulated draws go in N15:N214.`,formulas:[{cell:`N15 (fill to N15:N214)`,formula:`=PERCENTILE($B$5:$K$16,RAND())`,note:`random percentile of the data`}],steps:[`PERCENTILE(data, k) returns the value below which a share k of the data lies.`,`With k = RAND() every percentile is equally likely, so the draws follow the shape of the data.`,`It interpolates between neighbouring observations, so draws are continuous between the smallest and largest value.`],pitfalls:[`The data block can span several columns; anchor the whole block.`,`Draws can never go below the smallest or above the largest observation.`],answer:`Values between the smallest and largest recorded wait that change on F9; their average is close to AVERAGE(B5:K16).`},{id:`resample-small`,topic:`resample`,question:`The number of items in 80 recorded self-checkout baskets is in A5:A84 (whole numbers). In D2, count the observations; in F15, resample one basket size so that only observed values can appear, and fill down to F64.`,layout:`Recorded basket sizes in A5:A84 (80 whole numbers). The count goes in D2 and the simulated sizes in F15:F64.`,formulas:[{cell:`D2`,formula:`=COUNT($A$5:$A$84)`,note:`n = 80`},{cell:`F15 (fill to F15:F64)`,formula:`=SMALL($A$5:$A$84,RANDBETWEEN(1,$D$2))`,note:`k-th smallest for a random position k`},{cell:`F15 (alternative)`,formula:`=INDEX($A$5:$A$84,RANDBETWEEN(1,$D$2))`,note:`random row; same distribution`},{cell:`F15 (rounded alternative)`,formula:`=ROUND(PERCENTILE($A$5:$A$84,RAND()),0)`,note:`course alternative: whole numbers, but it can return values between observations that were never recorded`}],steps:[`Count the data so the random position covers every observation.`,`RANDBETWEEN(1, n) picks a position; SMALL returns the value in that sorted position.`,`Every recorded basket is equally likely, so values appear in proportion to their frequency.`],pitfalls:[`RANDBETWEEN(1,100) with only 80 values gives #NUM! whenever k > 80.`,`PERCENTILE without ROUND interpolates and can return 3.4 items.`],answer:`D2 = 80. F15:F64 are whole numbers that all appear in A5:A84 and change on F9.`},{id:`resample-index-row`,topic:`resample`,question:`A hawker centre has 40 stalls listed in A5:A44. Each day an inspector visits one stall chosen at random. In E15, return the stall inspected on each of 30 days, and fill down to E44.`,layout:`Stall names in A5:A44 (40 stalls). Days 1-30 in rows 15-44; the inspected stall goes in E15:E44.`,formulas:[{cell:`E15 (fill to E15:E44)`,formula:`=INDEX($A$5:$A$44,RANDBETWEEN(1,40))`,note:`random position 1-40`}],steps:[`INDEX(list, k) returns the k-th item.`,`RANDBETWEEN(1, 40) makes every stall equally likely.`,`The upper limit must equal the number of items in the list.`],pitfalls:[`RANDBETWEEN(0,40) can ask for position 0, which is not a stall; positions start at 1.`],answer:`Stall names that change on F9; each stall has a 1/40 = 2.5% chance per day.`},{id:`resample-index-grid`,topic:`resample`,question:`The loading time per passenger (seconds) is equally likely to be any of the 8 values in the table H4:I7. In J15, draw one loading time for each of 36 departures, and fill down to J50.`,layout:`Loading times in seconds in the 4-row by 2-column table H4:I7 (8 equally likely values). Draws go in J15:J50.`,formulas:[{cell:`J15 (fill to J15:J50)`,formula:`=INDEX($H$4:$I$7,RANDBETWEEN(1,4),RANDBETWEEN(1,2))`,note:`random row 1-4, random column 1-2`}],steps:[`INDEX(table, row, column) returns one cell of a grid.`,`Draw the row with RANDBETWEEN(1, rows) and the column with RANDBETWEEN(1, columns).`,`Each of the 4 x 2 = 8 cells is then equally likely.`],pitfalls:[`Swapping the limits asks for columns 3 or 4 of a 2-column table and returns #REF!.`,`These are seconds: divide by 86400 before adding them to a clock time.`],answer:`Values from the table that change on F9; the long-run average is the plain average of the 8 cells, AVERAGE(H4:I7).`},{id:`replications-data-table-setup`,topic:`replications`,question:`The sheet simulates one weekend of a Christmas pop-up stall, with the profit in H20. Set up 500 replications of the profit with a Data Table in K5:L505 (trial numbers in K6:K505, results in L6:L505).`,layout:O,formulas:[{cell:`K7 (fill to K7:K505)`,formula:`=K6+1`,note:`K6 holds 1; trial numbers are only labels`},{cell:`L5`,formula:`=H20`,note:`link to the output, one row above the first trial and one column right`}],tool:[`Type 1 in K6 and fill =K6+1 from K7 down to K505`,`Put =H20 in L5`,`Select K5:L505 (trial column plus the link column, including row 5)`,`Data > What-If Analysis > Data Table`,`Row input cell: (leave empty)`,`Column input cell: $N$2 (a blank cell that no formula uses)`,`OK: L6:L505 fills with 500 different profits`],steps:[`Build ONE complete run of the model with RAND() inside, ending in one output cell.`,`Trial numbers go down a column; the link to the output sits in the row above, one column to the right.`,`Run Data Table with a BLANK column input cell: each row recalculates every RAND() and records the new output.`,`If the sheet becomes slow: Formulas > Calculation Options > Automatic Except for Data Tables, then F9.`],pitfalls:[`Using a model input (e.g. the price cell) as the column input cell overwrites it with 1, 2, 3, ... and ruins every result.`,`The selection must include the trial column and the link row; selecting L5:L505 alone does not work.`],answer:`Report the method: 500 replications, Data Table on K5:L505, row input empty, column input N2, link L5 = H20. The values in L6:L505 change on every F9.`},{id:`replications-average`,topic:`replications`,question:`From the 500 replicated profits, estimate the expected weekend profit in L2.`,layout:O,formulas:[{cell:`L2`,formula:`=AVERAGE(L6:L505)`,note:`table body only`}],steps:[`Average the 500 replicated values, not the link cell.`,`Place the summary outside the table block.`,`Quote it as an estimate with the number of replications.`],pitfalls:[`Including L5 (the current single run) in the average.`,`Averaging the trial-number column K gives 250.5, not a profit.`],answer:`A value that moves slightly on every F9: report "about <value> from 500 replications". Keys accept a range around the true mean.`},{id:`replications-probability`,topic:`replications`,question:`The weekend model also counts customers turned away in H22. Record it in column M of the same Data Table (K5:M505), and in M2 estimate the probability that at least one customer is turned away in a weekend.`,layout:`${O} Turned-away count for one run in H22; second link cell M5, replicated counts M6:M505.`,formulas:[{cell:`M5`,formula:`=H22`,note:`second output in the same table`},{cell:`M2`,formula:`=COUNTIF(M6:M505,">0")/COUNT(M6:M505)`,note:`share of replications with at least one turned away`}],tool:[`Clear the old table body L6:L505 first (part of a Data Table cannot be changed)`,`Select K5:M505`,`Data > What-If Analysis > Data Table`,`Row input cell: (empty)`,`Column input cell: $N$2 (blank)`],steps:[`Add the second output as another link cell in the link row.`,`Probability = replications where the event happens / number of replications.`,`COUNTIF with ">0" counts the replications with at least one turned away.`],pitfalls:[`AVERAGE(M6:M505) is the expected NUMBER turned away, not the probability.`,`">1" misses the replications with exactly 1; use ">0" or ">=1".`],answer:`A share between 0 and 1 that moves slightly on F9; report it as a percentage with the number of replications.`},{id:`replications-loss-share`,topic:`replications`,question:`Using the 500 replicated profits, compute in L3 the probability of making a loss, and in L4 the probability that profit reaches at least the target in P3.`,layout:`${O} Profit target in P3.`,formulas:[{cell:`L3`,formula:`=COUNTIF(L6:L505,"<0")/COUNT(L6:L505)`,note:`share of runs with a loss`},{cell:`L4`,formula:`=COUNTIF(L6:L505,">="&$P$3)/COUNT(L6:L505)`,note:`criterion joined to the cell with &`}],steps:[`A loss is profit < 0.`,`Count the replications that meet the condition and divide by the number of replications.`,`Join a cell into the criterion with &: ">="&P3.`],pitfalls:[`">=P3" inside the quotes compares with the text P3.`,`"<=0" would also count break-even runs as losses.`],answer:`Two shares between 0 and 1 that move slightly on F9; quote them with the number of replications.`},{id:`replications-two-way`,topic:`replications`,question:`A bank-branch model (one simulated morning) reports the average wait in minutes in H8, using the number of tellers in G4. With ONE Data Table, replicate the morning 200 times for 2, 3, 4 and 5 tellers, and give the average wait for each teller count in L2:O2.`,layout:`Number of tellers (a typed model input) in G4; average wait in minutes for one run in H8. Two-way Data Table K4:O204: corner K4, teller counts 2, 3, 4, 5 in L4:O4, trial numbers 1-200 in K5:K204, results L5:O204. Q1 is a blank cell. Averages go in L2:O2.`,formulas:[{cell:`K4`,formula:`=H8`,note:`output in the top-left corner`},{cell:`L2 (fill right to L2:O2)`,formula:`=AVERAGE(L5:L204)`,note:`average wait for that teller count`}],tool:[`Type 2, 3, 4, 5 in L4:O4 and trial numbers 1 to 200 in K5:K204`,`Put =H8 in the corner K4`,`Select K4:O204`,`Data > What-If Analysis > Data Table`,`Row input cell: $G$4 (the tellers cell: the values across the top go here)`,`Column input cell: $Q$1 (a blank cell: the trial numbers go here)`],steps:[`Parameter values across the top, trial numbers down the side, the output in the corner.`,`Row input cell = the parameter cell, because the values in the top ROW are fed into it.`,`Column input cell = a blank cell, because the trial numbers in the side COLUMN are only labels.`,`Average each column and compare.`],pitfalls:[`Swapping the two input cells feeds 1-200 into the tellers cell.`,`G4 must hold a typed value, not a formula.`],answer:`Four averages that move slightly on F9; the wait should fall as tellers are added. Report the setup (K4:O204, row input G4, column input Q1, 200 replications) and the four averages.`},{id:`replications-compare-policies`,topic:`replications`,question:`A mini-mart model computes, from the SAME random demand, the weekly profit under ordering policy A in H20 and under policy B in H21. Replicate both 500 times in one Data Table (K5:N505). Give the average profit of each policy in L2 and M2, the average difference B - A in N2, and in N3 the share of weeks in which B earns more.`,layout:`Profit under policy A in H20 and under policy B in H21 (one simulated week, same RAND() demand). Data Table K5:N505: trial numbers K6:K505, link cells L5, M5, N5, results L6:N505. P1 is a blank cell.`,formulas:[{cell:`L5`,formula:`=H20`},{cell:`M5`,formula:`=H21`},{cell:`N5`,formula:`=H21-H20`,note:`difference B - A in the same run`},{cell:`L2 (fill right to L2:N2)`,formula:`=AVERAGE(L6:L505)`},{cell:`N3`,formula:`=COUNTIF(N6:N505,">0")/COUNT(N6:N505)`,note:`share of weeks where B beats A`}],tool:[`Select K5:N505`,`Data > What-If Analysis > Data Table`,`Row input cell: (empty)`,`Column input cell: $P$1 (blank)`],steps:[`Compute both policies from the same random draws in each run, so the comparison is fair.`,`Record both profits and their difference as three outputs of one table.`,`Recommend the policy with the higher average; N3 shows how consistently it wins.`,`If the average difference is small next to the run-to-run spread, call it inconclusive.`],pitfalls:[`Comparing two separate F9 runs mixes the policy effect with random noise.`],answer:`All values move on F9; recommend the policy with the higher average profit and quote N3 as the share of weeks it wins.`},{id:`replications-spread`,topic:`replications`,question:`For the 500 replicated profits, report in P6 the standard deviation, in P7 the range (largest minus smallest), in P8 the 5th percentile (the profit that 95% of weekends exceed), and in P9 the standard error of the average profit.`,layout:O,formulas:[{cell:`P6`,formula:`=STDEV(L6:L505)`},{cell:`P7`,formula:`=MAX(L6:L505)-MIN(L6:L505)`},{cell:`P8`,formula:`=PERCENTILE(L6:L505,0.05)`,note:`5% of runs fall below this`},{cell:`P9`,formula:`=STDEV(L6:L505)/SQRT(COUNT(L6:L505))`,note:`precision of the average`}],steps:[`STDEV measures how much one weekend varies around the average.`,`MAX - MIN is the full range seen in the replications.`,`PERCENTILE(results, 0.05) is a bad-weekend level; 0.95 gives a good-weekend level.`,`The standard error shrinks with more replications; the average is usually within 2-3 standard errors of the true mean.`],pitfalls:[`Confusing the standard deviation (spread of one weekend) with the standard error (precision of the average).`],answer:`All four move slightly on F9; quote them as estimates from 500 replications.`},{id:`replications-output-not-inputs`,topic:`replications`,question:`A newsstand stocks 100 copies of a magazine at $2 each and sells at $5; unsold copies are worthless. Demand is 0 or 200 copies, each with probability 0.5. A classmate averages simulated demand (about 100) and reports profit = 5 x MIN(100, 100) - 200 = $300. Build the one-run model in B8 and B10, replicate the profit 500 times, give the correct expected profit in H2 and explain the difference.`,layout:`Stock 100 in B3, unit cost 2 in B4, price 5 in B5. Demand for one run in B8, profit for one run in B10. One-way Data Table G4:H504: trial numbers G5:G504, link H4, results H5:H504. J1 is a blank cell.`,formulas:[{cell:`B8`,formula:`=IF(RAND()<0.5,0,200)`,note:`demand 0 or 200, each with probability 0.5`},{cell:`B10`,formula:`=$B$5*MIN(B8,$B$3)-$B$4*$B$3`,note:`non-linear because of MIN`},{cell:`H4`,formula:`=B10`},{cell:`H2`,formula:`=AVERAGE(H5:H504)`,note:`average of the replicated OUTPUT`}],tool:[`Select G4:H504`,`Data > What-If Analysis > Data Table`,`Row input cell: (empty)`,`Column input cell: $J$1 (blank)`],steps:[`Replicate the output (profit) itself, then average it.`,`Demand 0 gives 0 - 200 = -200; demand 200 gives 5 x 100 - 200 = 300.`,`Expected profit = 0.5 x (-200) + 0.5 x 300 = 50.`,`The average demand of 100 gives 300 because MIN cuts off the high demand while the low demand still costs the full stock.`],pitfalls:[`f(average input) is not the average of f(input) when the model has MIN, MAX or IF.`,`Replicating only the inputs and averaging them throws away the variation that drives the loss.`],answer:`H2 is about $50 (it moves around 50 on each F9); the classmate overstates the expected profit by about $250.`},{id:`flows-binomial-trips`,topic:`flows`,question:`For each route, C holds the number of commuters who might borrow an umbrella at the origin station and return it at the destination, and D the chance each one does. In E5, simulate the number of trips on the route, and fill down to E16. In E18, compute the expected total number of trips as a check.`,layout:`${D} The check goes in E18.`,formulas:[{cell:`E5 (fill to E5:E16)`,formula:`=IF(C5>0,CRITBINOM(C5,D5,RAND()),0)`,note:`binomial trips, guarded for n = 0`},{cell:`E18`,formula:`=SUMPRODUCT(C5:C16,D5:D16)`,note:`expected trips = sum of n x p`}],steps:[`Each commuter borrows or not with the same chance, so the trips on a route are binomial(n, p).`,`CRITBINOM(n, p, RAND()) draws the count; n and p stay relative because each route has its own.`,`Guard empty routes so they always give 0.`,`The average of SUM(E5:E16) over replications should be close to E18.`],pitfalls:[`Anchoring $D$5 when each route has its own probability.`,`ROUND(n x p) is the average, not a random count.`],answer:`E5:E16 are whole numbers from 0 to n that change on F9. E18 is fixed; for example a route with n = 40 and p = 0.15 contributes 6 trips.`},{id:`flows-departures`,topic:`flows`,question:`In J5, compute the number of umbrellas that leave station 1 (trips that start there), and fill down to J8 for stations 2-4.`,layout:D,formulas:[{cell:`J5 (fill to J5:J8)`,formula:`=SUMIF($A$5:$A$16,H5,$E$5:$E$16)`,note:`trips whose ORIGIN is this station`},{cell:`J5 (alternative)`,formula:`=SUMPRODUCT(($A$5:$A$16=H5)*$E$5:$E$16)`}],steps:[`Departures = trips whose origin is this station.`,`SUMIF(origin column, station number, trips column).`,`Anchor both ranges; leave the station cell H5 relative.`],pitfalls:[`Using the destination column gives arrivals instead.`,`The criteria range and the sum range must cover the same rows (5-16).`],answer:`Whole numbers that change on F9; the four departures add up to SUM(E5:E16).`},{id:`flows-arrivals`,topic:`flows`,question:`In K5, compute the number of umbrellas returned to each station (trips that end there), and fill down to K8. In K10, check that total departures equal total arrivals.`,layout:`${D} The check goes in K10.`,formulas:[{cell:`K5 (fill to K5:K8)`,formula:`=SUMIF($B$5:$B$16,H5,$E$5:$E$16)`,note:`trips whose DESTINATION is this station`},{cell:`K10`,formula:`=SUM(J5:J8)-SUM(K5:K8)`,note:`must be 0: every trip departs once and arrives once`}],steps:[`Arrivals = trips whose destination is this station.`,`Same SUMIF, with the destination column as the criteria range.`,`The totals must match.`],pitfalls:[`Swapping origin and destination flips departures and arrivals but the totals still match, so K10 will not catch it: check one station by hand.`],answer:`Whole numbers that change on F9; K10 is always 0.`},{id:`flows-end-stock-surplus`,topic:`flows`,question:`In L5, compute the end-of-day stock at each station; in M5, the surplus above the target stock that must be trucked back; fill both down to row 8. In M10, compute the day rebalancing cost.`,layout:`${D} The rebalancing cost goes in M10.`,formulas:[{cell:`L5 (fill to L5:L8)`,formula:`=I5-J5+K5`,note:`start - departures + arrivals`},{cell:`M5 (fill to M5:M8)`,formula:`=MAX(0,L5-$P$2)`,note:`only the excess above target`},{cell:`M10`,formula:`=SUM(M5:M8)*$P$3`,note:`surplus umbrellas x cost per umbrella`}],steps:[`End stock = start - departures + arrivals.`,`Surplus = MAX(0, end - target); a station below target has no surplus (its shortage would be MAX(0, target - end)).`,`Cost = total surplus x cost per umbrella moved.`],pitfalls:[`L5-$P$2 without MAX gives negative surpluses that reduce the cost.`,`The cost is non-linear in the stocks: replicate the cost or profit itself, never plug average stocks into MAX.`],answer:`Example: I5 = 30, J5 = 12, K5 = 18 gives L5 = 36 and M5 = 36 - 30 = 6; at $1.50 each that station adds $9 to M10. Simulated values change on F9.`},{id:`flows-fare-revenue`,topic:`flows`,question:`The rental fare depends on the route and is given in a 4 x 4 fare matrix. In F5, look up the fare for each route and fill down to F16. In F18, compute the total rental revenue, and in F19 the profit after the rebalancing cost.`,layout:`${D} The rebalancing cost for the day is in M10.`,formulas:[{cell:`F5 (fill to F5:F16)`,formula:`=INDEX($P$5:$S$8,A5,B5)`,note:`row = origin number, column = destination number`},{cell:`F18`,formula:`=SUMPRODUCT(E5:E16,F5:F16)`,note:`trips x fare, summed`},{cell:`F19`,formula:`=F18-M10`}],steps:[`INDEX(matrix, row number, column number) picks one fare.`,`The station numbers 1-4 are exactly the row and column positions in the matrix.`,`Revenue = sum of trips x fare over all routes.`,`Replicate F19 with a Data Table for the expected profit.`],pitfalls:[`INDEX($P$5:$S$8,B5,A5) reads the reverse route (wrong when the matrix is not symmetric).`,`Station names (text) cannot be INDEX positions; use the numbers.`],answer:`F5:F16 are fixed fares; F18 and F19 change on F9. Report the expected profit as the average of a Data Table of F19.`},{id:`single-server-arrival-chain`,topic:`single-server`,question:`A neighbourhood pharmacy has one pharmacist. In E15, compute the arrival clock time of customer 1 from the gap in C15, then fill down to E64 so that each customer arrives one gap after the previous one.`,layout:S,formulas:[{cell:`E15 (fill to E15:E64)`,formula:`=E14+C15`,note:`previous arrival + this gap`}],steps:[`Row 14 is customer 0: E14 = G14 = opening time, so customer 1 arrives one gap after opening.`,`Each arrival = previous arrival (relative E14) + own gap.`,`Format column E as a clock time (h:mm:ss).`],pitfalls:[`=$E$14+C15 measures every gap from the opening time, so customers never spread out.`,`Gaps in minutes (plain numbers) must be divided by 1440 before adding them to a clock time.`],answer:`Rising clock times that change on F9. Example: gaps of 0:03:30 and 0:02:00 give arrivals 09:03:30 and 09:05:30.`},{id:`single-server-first-row-opening`,topic:`single-server`,question:`In a sheet with NO customer-0 row, the opening time 10:00 is in B3 and customer 1 is in row 15 (row 14 holds headers). Give the arrival, service start and service end of customer 1 in E15:G15, then the row-16 formulas in E16:G16 that fill down to row 64.`,layout:`Opening time 10:00 in B3; row 14 holds column headers. Customers 1-50 in rows 15-64: gaps C15:C64, service times D15:D64 (Excel times), arrivals E15:E64, service starts F15:F64, service ends G15:G64.`,formulas:[{cell:`E15`,formula:`=$B$3+C15`,note:`first arrival = opening time + first gap`},{cell:`F15`,formula:`=E15`,note:`the server is free, so customer 1 starts on arrival`},{cell:`G15`,formula:`=F15+D15`},{cell:`E16 (fill to E16:E64)`,formula:`=E15+C16`},{cell:`F16 (fill to F16:F64)`,formula:`=MAX(E16,G15)`},{cell:`G16 (fill to G16:G64)`,formula:`=F16+D16`}],steps:[`The first row is special: it starts from the opening time and nobody is ahead of customer 1.`,`From row 16 the general formulas read the row above.`,`Alternatively add a customer-0 row (end = opening time) so one formula fills the whole column.`],pitfalls:[`Filling the general formula into row 15 makes it read the header row: =E14+C15 returns #VALUE! on header text.`,`If customer 1 arrives exactly at opening, E15 = $B$3 with no gap.`],answer:`Example: B3 = 10:00, C15 = 0:04:00, D15 = 0:06:00 gives E15 = 10:04, F15 = 10:04, G15 = 10:10.`},{id:`single-server-start`,topic:`single-server`,question:`In F15, compute when the pharmacist starts serving customer 1, and fill down to F64. Service starts once the customer has arrived and the previous customer has finished.`,layout:S,formulas:[{cell:`F15 (fill to F15:F64)`,formula:`=MAX(E15,G14)`,note:`later of own arrival and previous end`}],steps:[`Service cannot start before the customer arrives (E15).`,`Nor before the previous customer leaves (G14, the end time one row up).`,`The later of the two is the MAX; G14 = opening time handles customer 1.`],pitfalls:[`=MAX(E15,F14) uses the previous START and ignores how long that service took.`,`=E15 alone ignores the queue: every wait becomes 0.`,`MIN instead of MAX lets service start before the customer arrives.`],answer:`Example: arrival 09:05:30 while the previous customer ends at 09:08:00 gives a start of 09:08:00.`},{id:`single-server-end`,topic:`single-server`,question:`In G15, compute when service ends for each customer, and fill down to G64.`,layout:S,formulas:[{cell:`G15 (fill to G15:G64)`,formula:`=F15+D15`,note:`start + service duration`}],steps:[`End = service start + service time.`,`Clock time + duration = a later clock time.`],pitfalls:[`=E15+D15 (arrival + service) forgets the wait, so the queue never builds.`],answer:`Example: start 09:08:00 with a service time of 0:04:15 ends at 09:12:15.`},{id:`single-server-wait`,topic:`single-server`,question:`In H15, compute how long each customer waits before service starts, and fill down to H64.`,layout:S,formulas:[{cell:`H15 (fill to H15:H64)`,formula:`=F15-E15`,note:`start - arrival`}],steps:[`Wait = service start - arrival.`,`It is 0 when the server is free on arrival.`,`Format as mm:ss, or [h]:mm:ss if a wait can exceed an hour.`],pitfalls:[`=G15-E15 is the time in system (wait + service), not the wait.`,`mm:ss hides whole hours: a 65-minute wait shows as 05:00.`],answer:`Example: arrival 09:05:30 and start 09:08:00 give a wait of 00:02:30.`},{id:`single-server-system-time`,topic:`single-server`,question:`In I15, compute the time each customer spends in the system (from arrival until service ends), and fill down to I64.`,layout:S,formulas:[{cell:`I15 (fill to I15:I64)`,formula:`=G15-E15`,note:`end - arrival`},{cell:`I15 (alternative)`,formula:`=H15+D15`,note:`wait + service`}],steps:[`Time in system = service end - arrival.`,`It always equals wait + service time, which is a useful check.`],pitfalls:[`=G15-F15 is just the service time.`],answer:`Example: arrival 09:05:30 and end 09:12:15 give 00:06:45 (= 2:30 wait + 4:15 service).`},{id:`single-server-idle`,topic:`single-server`,question:`In K15, compute how long the pharmacist is idle just before serving each customer, and fill down to K64. In K66, compute the total idle time in minutes.`,layout:`${S} Idle times go in K15:K64 and the total in K66.`,formulas:[{cell:`K15 (fill to K15:K64)`,formula:`=F15-G14`,note:`previous end to this start`},{cell:`K66`,formula:`=SUM(K15:K64)*1440`,note:`total idle minutes`}],steps:[`The server is free from the previous end time (G14 for customer 1 = the opening time).`,`Idle = this start - previous end; it is 0 whenever the customer had to wait.`,`Multiply a total time by 1440 to report minutes.`],pitfalls:[`=E15-G14 (arrival - previous end) turns negative whenever a queue exists.`,`Check: total idle + total service = last end - opening time.`],answer:`Changes on F9. Check: SUM(K15:K64) + SUM(D15:D64) = G64 - G14.`},{id:`single-server-wait-minutes`,topic:`single-server`,question:`The mark scheme wants waits as plain numbers of minutes. In L15, convert the wait in H15 to minutes rounded to 2 decimals, and fill down to L64.`,layout:`${S} Waits in minutes go in L15:L64.`,formulas:[{cell:`L15 (fill to L15:L64)`,formula:`=ROUND(H15*1440,2)`,note:`a day has 1440 minutes`},{cell:`L15 (alternative)`,formula:`=HOUR(H15)*60+MINUTE(H15)+SECOND(H15)/60`,note:`from the time parts, to the nearest second`}],steps:[`A time value is a fraction of a day; x1440 gives minutes (x24 hours, x86400 seconds).`,`Format the result as Number or General, not as a time.`,`Round only if the question asks for it.`],pitfalls:[`Formatting H15 as mm only changes the display; the cell still holds a day fraction.`,`MINUTE(H15) alone drops whole hours and the seconds.`],answer:`Example: a wait of 0:02:30 is stored as about 0.001736 and converts to 2.5 minutes.`},{id:`single-server-overtime`,topic:`single-server`,question:`The pharmacy closes at 13:00 but finishes serving everyone in the sheet (all 50 arrive before closing). In K3, find when the pharmacist finishes the last customer; in K4, the overtime in minutes after closing (0 if none).`,layout:`${S} Closing time 13:00 in B5.`,formulas:[{cell:`K3`,formula:`=MAX(G15:G64)`,note:`last service end`},{cell:`K4`,formula:`=MAX(0,K3-$B$5)*1440`,note:`minutes past closing, never negative`},{cell:`K4 (alternative)`,formula:`=MAX(0,K3-TIME(13,0,0))*1440`,note:`closing time built with TIME`}],steps:[`The last end time is the largest end time: MAX of the column.`,`Overtime = MAX(0, last end - closing) so an early finish gives 0, not a negative.`,`x1440 reports minutes.`],pitfalls:[`Typing 13 for the closing time means 13 days; use 13:00 in a cell or TIME(13,0,0).`],answer:`Example: a last end of 13:17:30 gives K4 = 17.5 minutes. Simulated values change on F9.`},{id:`multi-server-number-in-system`,topic:`multi-server`,question:`A hospital outpatient pharmacy has c dispensing counters fed by one queue. In J15, count how many earlier patients are still in the system (waiting or being served) when patient 1 arrives, and fill down to J64.`,layout:C,formulas:[{cell:`J15 (fill to J15:J64)`,formula:`=COUNTIF($G$14:G14,">"&E15)`,note:`earlier end times later than this arrival`}],steps:[`An earlier patient is still in the system if the service end is after this arrival.`,`COUNTIF over the earlier end times with the criterion ">"&E15.`,`The range $G$14:G14 grows by one row as you fill down: anchored top, relative bottom.`],pitfalls:[`">E15" inside the quotes compares with the text E15; join the cell with &.`,`$G$14:$G$14 (fully anchored) only ever looks at customer 0.`,`Including the own row (G15) is circular, because G15 depends on the start.`],answer:`Whole numbers 0, 1, 2, ... that change on F9; a value of at least c means the patient has to wait.`},{id:`multi-server-start-c`,topic:`multi-server`,question:`With c counters (G4) sharing one queue, compute in F15 when patient 1 starts service and fill down to F64. Then give the end time in G15 and the wait in H15, both filled down to row 64.`,layout:C,formulas:[{cell:`F15 (fill to F15:F64)`,formula:`=IF(J15<$G$4,E15,LARGE($G$14:G14,$G$4))`,note:`course form`},{cell:`G15 (fill to G15:G64)`,formula:`=F15+D15`},{cell:`H15 (fill to H15:H64)`,formula:`=F15-E15`}],steps:[`Fewer than c patients in the system means a counter is free: start on arrival.`,`Otherwise start when the first counter frees up: the c-th largest end time among the earlier patients.`,`Anchor G4 and the top of the expanding range; keep E15, J15 and the bottom of the range relative.`],pitfalls:[`=MAX(E15,LARGE($G$14:G14,$G$4)) returns #NUM! for the first patients (fewer than c end times exist) and the error spreads down.`,`LARGE(..., 1) is the LAST counter to free up, not the first.`,`=MAX(E15,G14) treats the pharmacy as a single server.`],answer:`Clock times that change on F9; with more counters, more rows have F = E (no wait).`},{id:`multi-server-next-free-logic`,topic:`multi-server`,question:`Explain why the c-th largest earlier end time is when the next counter frees up, using these numbers: c = 3; the earlier patients end at 09:00 (customer 0), 09:58, 10:01, 10:04, 10:09 and 10:06; the next patient arrives at 10:02 in E20. Give J20 and F20, and say what changes if the arrival is 10:05.`,layout:`Counters c = 3 in G4. End times of the earlier patients in G14:G19: 09:00 (customer 0, the opening time), 09:58, 10:01, 10:04, 10:09, 10:06. The next patient arrives at 10:02 in E20; J20 is the number in system and F20 the start.`,formulas:[{cell:`J20`,formula:`=COUNTIF($G$14:G19,">"&E20)`},{cell:`F20`,formula:`=IF(J20<$G$4,E20,LARGE($G$14:G19,$G$4))`}],steps:[`Patients start in arrival order, so the c largest end times so far belong to the patient currently (or last) at each counter.`,`The smallest of those c values, the c-th largest overall, is when the first counter frees up.`,`Here the three latest ends are 10:09, 10:06 and 10:04, so the next free counter opens at 10:04.`,`If fewer than c earlier patients are still in the system, a counter is already idle and service starts on arrival.`],pitfalls:[`MIN of all earlier ends (09:00) picks a counter that has long since served someone else.`,`The c-th largest is the SMALLEST of the c latest ends, not the largest.`],answer:`J20 = 3 (10:04, 10:09 and 10:06 are after 10:02), so F20 = 3rd largest = 10:04 and the wait is 2 minutes. If the arrival is 10:05, J20 = 2 < 3, so service starts at 10:05 at the counter freed at 10:04.`},{id:`multi-server-utilisation`,topic:`multi-server`,question:`In D8, compute the utilisation of the c counters: total service time divided by the counter time available from opening until the last patient leaves. Put the last service end in G8.`,layout:`${C} The last end goes in G8 and the utilisation in D8.`,formulas:[{cell:`G8`,formula:`=MAX(G14:G64)`,note:`last service end`},{cell:`D8`,formula:`=SUM(D15:D64)/($G$4*(G8-G14))`,note:`busy time / (c x elapsed time)`}],steps:[`Busy time = sum of all service times.`,`Available time = c counters x (last end - opening time).`,`The ratio lies between 0 and 1; format as %.`],pitfalls:[`Forgetting the x c gives values above 100% with several counters.`,`With several counters the last ROW need not hold the last end time: use MAX.`],answer:`Changes on F9. Example: 6 hours of service in total with c = 2 from 09:00 to 13:00 gives 6/(2 x 4) = 0.75 (75%).`},{id:`multi-server-traffic-intensity`,topic:`multi-server`,question:`Before simulating, compute in C8 the traffic intensity from the mean service time (D4), the mean inter-arrival time (C4) and c counters (G4). What does a value above 1 mean?`,layout:`Mean inter-arrival time in C4 and mean service time in D4 (both Excel times, or both minutes); counters c in G4. The result goes in C8.`,formulas:[{cell:`C8`,formula:`=($D$4/$G$4)/$C$4`,note:`course form: (mean service / c) / mean gap`}],steps:[`c counters share the work: the effective service time per patient is mean service / c.`,`Intensity = (service / c) / gap, i.e. arrival rate / total service rate.`,`Above 1, patients arrive faster than the counters can serve, so the queue keeps growing.`],pitfalls:[`Gap / service (upside down) looks fine when the system is actually overloaded.`,`C4 and D4 must be in the same units.`],answer:`Example: mean service 9 minutes, mean gap 4 minutes, c = 2 gives (9/2)/4 = 1.125 (queue builds); with c = 3 it is (9/3)/4 = 0.75.`},{id:`multi-server-first-row`,topic:`multi-server`,question:`Explain why the model uses a customer-0 row (G14 = opening time, E14 = G14). Then give the row-15 and row-16 formulas for a sheet WITHOUT it, where patient 1 is in row 15 and the arrivals already chain from the opening time.`,layout:`Counters c in G4. No customer-0 row: patients 1-50 in rows 15-64 with gaps C15:C64, service times D15:D64, arrivals E15:E64, starts F15:F64, ends G15:G64, number in system J15:J64.`,formulas:[{cell:`J15`,formula:`=0`,note:`nobody is ahead of patient 1 (or type 0)`},{cell:`F15`,formula:`=E15`},{cell:`J16 (fill to J16:J64)`,formula:`=COUNTIF($G$15:G15,">"&E16)`},{cell:`F16 (fill to F16:F64)`,formula:`=IF(J16<$G$4,E16,LARGE($G$15:G15,$G$4))`}],steps:[`With a customer-0 row every real patient has at least one earlier end time, so one formula fills from row 15.`,`Customer 0 ends at the opening time, so it never counts as in the system once the pharmacy is open.`,`Without it, patient 1 has no earlier rows: J15 = 0 and F15 = E15 by hand; from row 16 the ranges start at $G$15.`],pitfalls:[`Filling the row-15 formulas down instead of the row-16 ones gives every patient F = E (no queue).`],answer:`Same results as the customer-0 version; patient 1 always starts on arrival.`},{id:`queue-measures-avg-wait`,topic:`queue-measures`,question:`In H8, compute the average wait in minutes over the 50 groups; in I8, the average time in system in minutes.`,layout:w,formulas:[{cell:`H8`,formula:`=AVERAGE(H15:H64)*1440`,note:`day fraction to minutes`},{cell:`I8`,formula:`=AVERAGE(I15:I64)*1440`}],steps:[`AVERAGE of a time column gives a day fraction.`,`x1440 turns it into minutes.`,`If the question wants a time instead, leave out x1440 and format [h]:mm:ss.`],pitfalls:[`Reporting the raw day fraction: 0.004167 is 6 minutes, not 0.004 minutes.`,`mm:ss formatting hides whole hours for long averages.`],answer:`Changes on F9; quote it in minutes.`},{id:`queue-measures-share-within`,topic:`queue-measures`,question:`In H9, compute the proportion of groups that waited at most the threshold in B6 (minutes).`,layout:w,formulas:[{cell:`H9`,formula:`=COUNTIF(H15:H64,"<="&$B$6/1440)/COUNT(H15:H64)`,note:`threshold converted to a time`},{cell:`H9 (typed 5 minutes)`,formula:`=COUNTIF(H15:H64,"<="&5/1440)/COUNT(H15:H64)`}],steps:[`Turn the threshold into a time: minutes/1440.`,`Build the criterion with "<="&value.`,`Divide by the number of groups (COUNT).`],pitfalls:[`"<=5" compares the waits with 5 DAYS: every group passes and the answer is 100%.`,`"at most" is <=, "less than" is <.`,`If the waits are already in minutes, drop the /1440.`],answer:`A proportion between 0 and 1 that changes on F9; format as %.`},{id:`queue-measures-share-more-than`,topic:`queue-measures`,question:`In H10, compute the proportion of groups that waited MORE than the threshold in B7 (10 minutes).`,layout:w,formulas:[{cell:`H10`,formula:`=COUNTIF(H15:H64,">"&$B$7/1440)/COUNT(H15:H64)`},{cell:`H10 (alternative)`,formula:`=1-COUNTIF(H15:H64,"<="&$B$7/1440)/COUNT(H15:H64)`,note:`1 - share within`}],steps:[`Same pattern as the share within, with ">".`,`"More than" and "at most" are complements: they add up to 1.`],pitfalls:[`">=" would include groups that waited exactly 10 minutes.`],answer:`A proportion that changes on F9; it equals 1 minus the share waiting at most 10 minutes.`},{id:`queue-measures-weighted-wait`,topic:`queue-measures`,question:`Everyone in a group waits the same time. In H11, compute the average wait PER PERSON in minutes, using the group sizes in B15:B64.`,layout:w,formulas:[{cell:`H11`,formula:`=SUMPRODUCT(H15:H64,B15:B64)/SUM(B15:B64)*1440`,note:`person-waiting time / persons`}],steps:[`Total waiting by people = sum of (group wait x group size): SUMPRODUCT.`,`Divide by the total number of people.`,`x1440 for minutes.`],pitfalls:[`AVERAGE(H15:H64) is the wait per GROUP and under-weights the big groups.`],answer:`Example: groups of 1, 3 and 2 waiting 2, 4 and 0 minutes give (2 + 12 + 0)/6 = 2.33 minutes per person, while the plain average is 2.`},{id:`queue-measures-weighted-share`,topic:`queue-measures`,question:`In H12, compute the proportion of PEOPLE (not groups) who waited at most the threshold in B6.`,layout:w,formulas:[{cell:`H12`,formula:`=SUMIF(H15:H64,"<="&$B$6/1440,B15:B64)/SUM(B15:B64)`,note:`people in qualifying groups / all people`}],steps:[`SUMIF adds the sizes of the groups whose wait meets the criterion.`,`Divide by the total number of people.`],pitfalls:[`COUNTIF counts groups, not people.`],answer:`Example: groups of 1, 3 and 2 waiting 2, 6 and 0 minutes: 1 + 2 = 3 of the 6 people waited at most 5 minutes, so 50% (COUNTIF would say 2 of 3 groups, 67%).`},{id:`queue-measures-utilisation`,topic:`queue-measures`,question:`In D8, compute the utilisation of the single counter: the share of time from opening until the last group leaves during which it was busy.`,layout:`${w} Idle times before each group, if computed, are in K15:K64.`,formulas:[{cell:`D8`,formula:`=SUM(D15:D64)/(MAX(G15:G64)-G14)`,note:`busy time / elapsed time`},{cell:`D8 (alternative)`,formula:`=1-SUM(K15:K64)/(MAX(G15:G64)-G14)`,note:`1 - idle share`}],steps:[`Busy time = total service time.`,`Elapsed time = last end - opening time.`,`Utilisation = busy / elapsed; idle share = 1 - utilisation.`],pitfalls:[`Dividing by the number of groups instead of the elapsed time.`,`A value above 100% means something is double counted.`],answer:`Changes on F9. Example: 3 hours of service between 09:00 and 13:00 gives 3/4 = 0.75.`},{id:`queue-measures-longest-wait`,topic:`queue-measures`,question:`In M3, report the longest wait in minutes; in M4, the number of the group that waited longest.`,layout:w,formulas:[{cell:`M3`,formula:`=MAX(H15:H64)*1440`},{cell:`M4`,formula:`=INDEX(A15:A64,MATCH(MAX(H15:H64),H15:H64,0))`,note:`position of the largest wait`}],steps:[`MAX gives the longest wait; x1440 for minutes.`,`MATCH(max, waits, 0) finds its position; INDEX returns the group number there.`],pitfalls:[`MATCH needs 0 (exact match): the waits are not sorted.`],answer:`Changes on F9; if two groups tie, MATCH returns the first.`},{id:`queue-measures-number-waited`,topic:`queue-measures`,question:`In M5, count the groups that had to wait at all; in M6, the proportion that waited; in M7, the average wait in minutes of only those that waited.`,layout:`${w} Groups served on arrival have a wait of exactly 0.`,formulas:[{cell:`M5`,formula:`=COUNTIF(H15:H64,">0")`},{cell:`M6`,formula:`=COUNTIF(H15:H64,">0")/COUNT(H15:H64)`},{cell:`M7`,formula:`=SUM(H15:H64)/COUNTIF(H15:H64,">0")*1440`,note:`total wait / number who waited`}],steps:[`A group waited if its wait is greater than 0.`,`Divide by COUNT for the proportion.`,`Zero waits add nothing to the sum, so total wait / number who waited is their average.`],pitfalls:[`AVERAGE(H15:H64) includes the zero waits and is lower.`,`If nobody waited, M7 gives #DIV/0!; guard with IF(M5=0,0,...).`],answer:`All three change on F9.`},{id:`queue-measures-avg-number-in-system`,topic:`queue-measures`,question:`Using the course formula, compute in J8 the time-average number of groups in the system between opening and the last arrival. Put the last arrival in E8.`,layout:`${w} J15:J64 counts the earlier groups still in the system when each group arrives (not counting itself). The last arrival goes in E8.`,formulas:[{cell:`E8`,formula:`=MAX(E14:E64)`,note:`last arrival`},{cell:`J8`,formula:`=SUMPRODUCT(((J15:J63+1)+J16:J64)/2,C16:C64)/(E8-E14)`,note:`area under the number-in-system curve / elapsed time`}],steps:[`Just after group k arrives there are J(k) + 1 groups in the system; just before group k+1 arrives there are J(k+1).`,`Over the gap C(k+1) the course uses the average of the two (a trapezoid).`,`Add the trapezoid areas with SUMPRODUCT and divide by the time from opening (E14) to the last arrival (E8).`,`Enter it normally: SUMPRODUCT handles the arrays (the course file shows it with braces).`],pitfalls:[`The ranges are offset by one row: J15:J63 with J16:J64 and C16:C64, all 49 cells.`,`Numerator and denominator are both in days, so there is no x1440: the result is a count.`],answer:`A plain number of groups (format as Number, not time) that changes on F9.`},{id:`queue-measures-arrivals-before-closing`,topic:`queue-measures`,question:`The counter stops taking new groups at 12:00. In M8, count the simulated groups that arrive before 12:00; in M9, the average wait in minutes of those groups only.`,layout:w,formulas:[{cell:`M8`,formula:`=COUNTIF(E15:E64,"<"&TIME(12,0,0))`},{cell:`M9`,formula:`=SUMIF(E15:E64,"<"&TIME(12,0,0),H15:H64)/M8*1440`,note:`total wait of early arrivals / their number`}],steps:[`TIME(12,0,0) builds 12:00 as a day fraction (0.5).`,`Join it to the operator with & inside COUNTIF and SUMIF.`,`SUMIF adds the waits of the rows whose ARRIVAL meets the criterion.`],pitfalls:[`"<12" compares with 12 DAYS, so every arrival passes; use TIME(12,0,0) or a cell holding 12:00.`],answer:`Both change on F9. TIME(12,0,0) = 0.5.`},{id:`balk-renege-system-length`,topic:`balk-renege`,question:`In L15, compute the system length (earlier cars still in the system) when car 1 arrives, and fill down to L64.`,layout:T,formulas:[{cell:`L15 (fill to L15:L64)`,formula:`=COUNTIF($I$14:I14,">"&E15)`,note:`earlier end times after this arrival`}],steps:[`Count the earlier end times that are later than this arrival.`,`Balkers hold "" in I; COUNTIF with a numeric criterion skips text, so they are not counted.`,`The range grows as you fill down: $I$14:I14.`],pitfalls:[`The end-time column must treat renegers correctly (see the end-time part), or L is inflated and too many cars balk.`],answer:`Whole numbers that change on F9.`},{id:`balk-renege-potential-start`,topic:`balk-renege`,question:`A driver balks (drives off at once) if MORE than F4 cars are already in the system. In F15, return "" for a balking driver; otherwise the time washing would start with I4 bays. Fill down to F64.`,layout:T,formulas:[{cell:`F15 (fill to F15:F64)`,formula:`=IF(L15>F$4,"",IF(L15>=I$4,LARGE(I$14:I14,I$4),$E15))`,note:`course form`}],steps:[`Test the balk rule first: L15 > F4 means the driver leaves, so "".`,`Otherwise the c-bay rule: start on arrival if L15 < c, else at the c-th largest earlier end time.`,`This is a POTENTIAL start: the driver may still renege.`],pitfalls:[`"more than 6" is L15>6; "6 or more" would be L15>=6. Read the wording.`,`Returning 0 instead of "" for balkers makes COUNT treat them as cars that joined.`],answer:`Clock times or blanks that change on F9.`},{id:`balk-renege-actual-start`,topic:`balk-renege`,question:`A driver who joins leaves (reneges) if the potential wait exceeds the limit in G4. In G15, compute the potential wait; in H15, the actual start ("" for balkers and renegers). Fill both down to row 64.`,layout:T,formulas:[{cell:`G15 (fill to G15:G64)`,formula:`=IF(F15="","",F15-E15)`,note:`potential wait`},{cell:`H15 (fill to H15:H64)`,formula:`=IF(F15="","",IF(G15>$G$4,"",F15))`,note:`blank if balked or reneged`}],steps:[`Potential wait = potential start - arrival; blank for balkers.`,`If the potential wait exceeds the limit, the driver leaves before washing: no actual start.`,`Otherwise the actual start equals the potential start.`],pitfalls:[`If the limit is typed as 20 (minutes) instead of 0:20, compare with $G$4/1440.`,`Test F15="" first: on a "" cell, G15>$G$4 is TRUE because text compares greater than any number.`],answer:`Times or blanks that change on F9.`},{id:`balk-renege-end-time`,topic:`balk-renege`,question:`In I15, compute when each car leaves the system: washed cars at actual start + wash time, renegers when their patience runs out (arrival + G4), balkers "". Fill down to I64. Then give the wait in J15 and the time in system in K15 (renegers count the full limit), both filled down.`,layout:T,formulas:[{cell:`I15 (fill to I15:I64)`,formula:`=IF(F15="","",IF(G15>$G$4,E15+$G$4,H15+D15))`,note:`course BR-M version`},{cell:`J15 (fill to J15:J64)`,formula:`=IF(F15="","",IF(H15="",$G$4,H15-E15))`},{cell:`K15 (fill to K15:K64)`,formula:`=IF(F15="","",IF(H15="",$G$4,I15-E15))`}],steps:[`Balkers never join: "".`,`Renegers stay in the queue for exactly the renege limit, so they still count in later system lengths for that time.`,`Washed cars end at actual start + wash time.`],pitfalls:[`=IF(F15="","",F15+D15) gives renegers a full wash end time, inflating later system lengths so too many cars balk.`,`=IF(H15="","",H15+D15) drops renegers from the count altogether, so too few balk.`],answer:`Times or blanks that change on F9.`},{id:`balk-renege-proportions`,topic:`balk-renege`,question:`In F8, compute the proportion of arriving cars that balked; in G8, the proportion of cars that joined but reneged.`,layout:`${T} Results in F8 and G8.`,formulas:[{cell:`F8`,formula:`=(COUNT(E15:E64)-COUNT(F15:F64))/COUNT(E15:E64)`,note:`(arrivals - joined) / arrivals`},{cell:`G8`,formula:`=(COUNT(F15:F64)-COUNT(H15:H64))/COUNT(F15:F64)`,note:`(joined - washed) / joined`}],steps:[`COUNT counts numbers only, so "" cells are skipped.`,`Balked = arrivals - joined (potential starts); divide by arrivals.`,`Reneged = joined - washed (actual starts); divide by those who JOINED.`],pitfalls:[`Dividing the reneges by all arrivals understates the renege proportion.`,`COUNTA counts "" cells as filled.`],answer:`Example: 50 arrivals, 44 joined and 38 washed give F8 = 6/50 = 0.12 and G8 = 6/44 = 0.136. Simulated values change on F9.`},{id:`balk-renege-lost-revenue`,topic:`balk-renege`,question:`Each car washed pays the fee in B5. In M8, compute the number of cars lost (balked or reneged); in M9, the fees lost.`,layout:`${T} Fee per car $15 in B5.`,formulas:[{cell:`M8`,formula:`=COUNT(E15:E64)-COUNT(H15:H64)`,note:`arrivals - washed`},{cell:`M9`,formula:`=M8*$B$5`}],steps:[`Every arrival either balks, reneges or is washed.`,`Lost = arrivals - actual starts.`,`Lost fees = lost cars x fee.`],pitfalls:[`Counting only the balkers misses the renegers.`],answer:`Example: 50 arrivals and 38 washed give 12 lost cars and $180 of lost fees. Simulated values change on F9.`},{id:`balk-renege-probabilistic-balk`,topic:`balk-renege`,question:`Variation: when AT LEAST F4 cars are already in the system, an arriving driver balks only with the probability in F5 (otherwise joins). Rewrite the potential start in F15 and fill down to F64.`,layout:`${T} Here F4 = 4 (balk threshold) and F5 = 0.6 (probability of balking once the threshold is reached).`,formulas:[{cell:`F15 (fill to F15:F64)`,formula:`=IF(AND(L15>=$F$4,RAND()<$F$5),"",IF(L15>=$I$4,LARGE($I$14:I14,$I$4),E15))`,note:`long line AND a random yes`}],steps:[`Balking now needs two things at once: a long line AND a random yes with chance F5.`,`If the driver stays, apply the usual c-bay start rule.`,`The later columns stay the same because they test F15="".`],pitfalls:[`"at least 4" is >=4, "more than 4" is >4.`],answer:`Times or blanks that change on F9; fewer drivers balk than with a hard limit at the same threshold.`},{id:`batch-queue-schedule-arrivals`,topic:`batch-queue`,question:`Bumboats leave the jetty every B2 minutes, the first at 07:10. In C7, compute the scheduled departure time from the one above; in D7, the number of passengers arriving during the interval, drawn from the arrivals table. Fill both down to row 42.`,layout:E,formulas:[{cell:`C7 (fill to C7:C42)`,formula:`=C6+$B$2/1440`,note:`minutes to a day fraction`},{cell:`C7 (alternative)`,formula:`=C6+TIME(0,$B$2,0)`},{cell:`D7 (fill to D7:D42)`,formula:`=LOOKUP(RAND(),$N$6:$N$10,$M$6:$M$10)`,note:`discrete arrivals via the CRF`}],steps:[`One row per departure; the scheduled time steps by the interval.`,`Arrivals per interval come from the discrete table: LOOKUP(RAND(), CRF, values).`,`Expected arrivals per interval = 6(0.15) + 9(0.25) + 12(0.30) + 15(0.20) + 18(0.10) = 11.55.`],pitfalls:[`=C6+$B$2 adds 10 DAYS.`,`Anchoring $C$6 makes every boat leave at 07:10.`],answer:`C7:C42 run 07:10, 07:20, ..., 13:00; D7:D42 are values from the table that change on F9.`},{id:`batch-queue-waiting`,topic:`batch-queue`,question:`The jetty shelter holds at most G2 people. In E7, compute how many people are in the shelter waiting for the boat: new arrivals plus those left behind by the previous boat, capped at the capacity. Fill down to E42.`,layout:E,formulas:[{cell:`E7 (fill to E7:E42)`,formula:`=MIN(D7+G6,$G$2)`,note:`arrivals + left behind, capped`}],steps:[`People available = this interval arrivals + left behind by the PREVIOUS boat (row above).`,`The shelter cannot hold more than its capacity: MIN(available, capacity).`],pitfalls:[`=MIN(D7+G7,$G$2) uses this row left-behind, which depends on E7: a circular reference.`,`MAX instead of MIN fills the shelter to capacity every time.`],answer:`Example: 18 arrivals and 10 left behind give MIN(28, 25) = 25.`},{id:`batch-queue-boarded-left`,topic:`batch-queue`,question:`Each boat takes at most D2 passengers. In F7, compute the number who board; in G7, the number left behind for the next boat. Fill both down to row 42.`,layout:E,formulas:[{cell:`F7 (fill to F7:F42)`,formula:`=MIN($D$2,E7)`,note:`seats or people waiting, whichever is fewer`},{cell:`G7 (fill to G7:G42)`,formula:`=E7-F7`}],steps:[`Boarded = MIN(seats, people in the shelter).`,`Left behind = people in the shelter - boarded; they wait for the next boat.`],pitfalls:[`MAX($D$2,E7) boards more people than there are seats.`,`Left behind comes from the shelter number E7, not from the arrivals D7.`],answer:`Example: 25 in the shelter gives F7 = 12 and G7 = 13.`},{id:`batch-queue-turned-away`,topic:`batch-queue`,question:`In H7, compute how many people are turned away because the shelter is full, and fill down to H42. In H44, total the people turned away over the day.`,layout:`${E} The day total goes in H44.`,formulas:[{cell:`H7 (fill to H7:H42)`,formula:`=MAX(D7+G6-$G$2,0)`,note:`excess over capacity, never negative`},{cell:`H44`,formula:`=SUM(H7:H42)`}],steps:[`Excess = arrivals + left behind - capacity.`,`MAX(excess, 0): nobody is turned away when there is room.`,`Check each row: E7 + H7 = D7 + G6.`],pitfalls:[`=MAX(D7-$G$2,0) ignores the people already waiting from the previous boat.`,`Working from G7 (after boarding) is too late: the cap applies before the boat comes.`],answer:`Example: 18 arrivals + 10 left behind - 25 = 3 turned away. The total changes on F9.`},{id:`batch-queue-departure-time`,topic:`batch-queue`,question:`Loading takes K2 seconds per boarding passenger, so a boat leaves later than scheduled. In I7, compute the actual departure time, and fill down to I42. Also give the version where the seconds per passenger are drawn at random from the 4 x 2 table P4:Q7.`,layout:`${E} Optional random loading table (seconds per passenger) in P4:Q7.`,formulas:[{cell:`I7 (fill to I7:I42)`,formula:`=C7+F7*$K$2/86400`,note:`seconds to a day fraction`},{cell:`I7 (random loading time)`,formula:`=C7+F7*INDEX($P$4:$Q$7,RANDBETWEEN(1,4),RANDBETWEEN(1,2))/86400`}],steps:[`Total loading seconds = boarded x seconds per passenger.`,`Divide seconds by 86400 (seconds in a day) before adding them to a clock time.`,`Format column I as h:mm:ss.`],pitfalls:[`/1440 treats the seconds as minutes: 12 x 15 = 180 would add 3 hours.`,`Anchor K2; keep C7 and F7 relative.`],answer:`Example: C7 = 07:10 with 12 boarding at 15 seconds each adds 180 seconds, so I7 = 07:13:00.`},{id:`batch-queue-revenue-summary`,topic:`batch-queue`,question:`Each boarding passenger pays the fare in J2. In J7, compute the revenue of each boat (fill down to J42); in J44, the day revenue; in G44, the average number left behind per departure; in F44, the share of boats that left full.`,layout:`${E} Summaries go in F44, G44 and J44.`,formulas:[{cell:`J7 (fill to J7:J42)`,formula:`=F7*$J$2`},{cell:`J44`,formula:`=SUM(J7:J42)`},{cell:`G44`,formula:`=AVERAGE(G7:G42)`},{cell:`F44`,formula:`=COUNTIF(F7:F42,$D$2)/COUNT(F7:F42)`,note:`boats with every seat taken`}],steps:[`Revenue per boat = boarded x fare.`,`Sum for the day; average the left-behind column; count the full boats.`,`Replicate J44 with a Data Table for the expected daily revenue.`],pitfalls:[`Revenue on arrivals (D) counts people who never boarded.`],answer:`Changes on F9. Upper bound: 36 boats x 12 seats x $4 = $1,728 if every boat leaves full.`},{id:`batch-queue-capacity-compare`,topic:`batch-queue`,question:`Management may enlarge the shelter from 25 to 40 people. With one Data Table, replicate the day 1,000 times for both capacities and give the average number turned away for each in S3:T3. Does the larger shelter raise revenue? Explain.`,layout:`${E} Day total turned away in H44 and day revenue in J44. Two-way Data Table R5:T1005: corner R5, capacities 25 and 40 in S5:T5, trial numbers 1-1000 in R6:R1005, results S6:T1005. V1 is a blank cell. Averages go in S3:T3.`,formulas:[{cell:`R5`,formula:`=H44`,note:`output in the corner`},{cell:`S3 (fill right to S3:T3)`,formula:`=AVERAGE(S6:S1005)`}],tool:[`Type 25 and 40 in S5:T5 and 1 to 1000 in R6:R1005`,`Put =H44 in the corner R5`,`Select R5:T1005`,`Data > What-If Analysis > Data Table`,`Row input cell: $G$2 (shelter capacity)`,`Column input cell: $V$1 (blank)`,`Build a second table the same way with =J44 in its corner for revenue`],steps:[`Capacities across the top feed G2 (row input); trial numbers down the side feed a blank cell.`,`Average each column for the two capacities.`,`Repeat with revenue (J44) as the output to answer the revenue question.`,`Explain using the seats: revenue can never exceed 36 x 12 x $4 = $1,728 a day.`],pitfalls:[`G2 must be a typed value, not a formula.`,`Comparing single F9 runs instead of 1,000-replication averages.`],answer:`Averages change on F9. Fewer people are turned away with 40 places. Revenue rises only if the extra people kept in the shelter later find seats; expected arrivals (11.55 per interval) are close to the 12 seats, so boats are often full and the revenue gain is small and capped at $1,728. Quote both revenue averages before concluding.`}],A=`Fresh Fields Wholesale order list A8:K68: headers in row 8 (Order ID, Region, Channel, Order Date, Customer, Product, Category, Qty, Unit Price, Status, Revenue) and 60 orders in rows 9-68. Order ID A9:A68, Region B9:B68 (North, North-East, East, West, Central), Channel C9:C68 (Hawker, Restaurant, Supermarket, Online), Order Date D9:D68 (real Excel dates in 2026), Customer E9:E68, Product F9:F68, Category G9:G68 (Vegetables, Fruit, Herbs), Qty H9:H68 (cartons), Unit Price I9:I68 (S$), Status J9:J68 (Paid, Pending), Revenue K9:K68 (Qty x Unit Price). Rows 1-6 are free for criteria and answers; row 7 is blank.`,j=`Delivery job list A5:G45: headers in row 5 (Job ID, Zone, Vehicle, Distance, Fee, Rating, Comment) and 40 jobs in rows 6-45. Job ID A6:A45, Zone B6:B45 (North, South, East, West, Central), Vehicle C6:C45 (Bike, Van), Distance D6:D45 (km), Fee E6:E45 (S$), Rating F6:F45 (whole numbers 1 to 5, blank if the customer did not rate), Comment G6:G45 (text, blank if none).`,M=`Alternative only: not taught in the course, use it as a check`,N=[{id:`data-filters-and-one-row`,topic:`filters`,question:`Fresh Fields wants every Supermarket order of at least 40 cartons. Set up the criteria in M1:N2 and use Advanced Filter to copy the matching orders, with their headers, to the area starting at M8.`,layout:A,formulas:[{cell:`M2`,formula:`="=Supermarket"`,note:`Exact match on Channel; the cell displays =Supermarket`}],tool:[`Data > Advanced`,`Action: Copy to another location`,`List range: $A$8:$K$68`,`Criteria range: $M$1:$N$2`,`Copy to: $M$8`,`Unique records only: not ticked`],steps:[`Copy the headers Channel (C8) and Qty (H8) into M1 and N1 so the spelling matches the list exactly.`,`Put both conditions on row 2 (same row = AND): M2 ="=Supermarket", and N2 typed as the text >=40.`,`Run Data > Advanced with the settings shown; the matching orders appear from M8 with their headers.`],pitfalls:[`>40 drops the orders of exactly 40 cartons: "at least" means >=.`,`A criteria range that runs on to an empty row 3 ($M$1:$N$3) lets every order through.`,`Keep the area below M8 empty: the extract overwrites it.`],answer:`Report the criteria M1:N2 and the extract from M8. The number of rows copied must equal =SUMPRODUCT((C9:C68="Supermarket")*(H9:H68>=40)) on the original list.`},{id:`data-filters-or-two-regions`,topic:`filters`,question:`Show only the Paid orders from the East or the West region. Write the criteria in M1:N3, filter the list in place, and count the same orders by formula in Q2.`,layout:A,formulas:[{cell:`M2`,formula:`="=East"`},{cell:`N2`,formula:`="=Paid"`,note:`Plain Paid works too (no other status begins with Paid)`},{cell:`M3`,formula:`="=West"`},{cell:`N3`,formula:`="=Paid"`,note:`Repeat the Paid condition on every OR row`},{cell:`Q2`,formula:`=SUMPRODUCT(((B9:B68="East")+(B9:B68="West"))*(J9:J68="Paid"))`,note:`Adding the two Region tests gives OR; multiplying by the Status test gives AND`}],tool:[`Data > Advanced`,`Action: Filter the list, in-place`,`List range: $A$8:$K$68`,`Criteria range: $M$1:$N$3`],steps:[`Headers: M1 Region and N1 Status, copied from B8 and J8.`,`Row 2 = East AND Paid, row 3 = West AND Paid: each extra row is an OR alternative.`,`Run Data > Advanced in place; the status bar shows how many records were found, which must equal Q2.`,`Data > Clear brings back all 60 rows.`],pitfalls:[`Paid written only on row 2 lets row 3 keep every West order, Pending ones included.`,`East and West on one row (Region header twice) asks for both at once and returns nothing.`,`An empty row 4 inside the criteria range shows every order.`],answer:`Report M1:N3 and Q2; the number of records found by the filter equals Q2.`},{id:`data-filters-exact-north`,topic:`filters`,question:`The Region column holds North, North-East and other regions. Filter the list in place to show only the orders whose Region is exactly North, with the criteria in M1:M2, and give their number in Q2 by formula.`,layout:A,formulas:[{cell:`M2`,formula:`="=North"`,note:`Displays =North: an exact match, so North-East is left out`},{cell:`Q2`,formula:`=COUNTIF(B9:B68,"North")`,note:`COUNTIF without wildcards matches the whole cell, so it also leaves out North-East`}],tool:[`Data > Advanced`,`Action: Filter the list, in-place`,`List range: $A$8:$K$68`,`Criteria range: $M$1:$M$2`],steps:[`M1 holds the header Region.`,`M2 holds ="=North" (or type '=North with a leading apostrophe, which stores the text =North).`,`Run Data > Advanced in place and compare the number of records found with Q2.`],pitfalls:[`Plain North in M2 means "begins with North" and keeps the North-East orders too.`,`Typing =North without the quotes makes Excel read a formula and show #NAME?.`,`COUNTIF(B9:B68,"North*") would count North-East as well.`],answer:`M2 shows =North; the filter finds exactly Q2 records.`},{id:`data-filters-revenue-band`,topic:`filters`,question:`The sales manager types a minimum revenue in Q1 and a maximum in Q2. Build criteria in M1:N2 from these two cells that copy the orders with Revenue from Q1 to Q2 (both included) to M8, and count those orders in Q4.`,layout:A,formulas:[{cell:`M2`,formula:`=">="&Q1`,note:`Shows, for example, >=500`},{cell:`N2`,formula:`="<="&Q2`,note:`Shows, for example, <=1500`},{cell:`Q4`,formula:`=COUNTIF(K9:K68,">="&Q1)-COUNTIF(K9:K68,">"&Q2)`,note:`At least Q1, minus those above Q2`}],tool:[`Data > Advanced`,`Action: Copy to another location`,`List range: $A$8:$K$68`,`Criteria range: $M$1:$N$2`,`Copy to: $M$8`],steps:[`Type Revenue in both M1 and N1: one field, two conditions on the same row = AND.`,`Build M2 and N2 from Q1 and Q2 with &; fixed bounds could simply be typed as >=500 and <=1500.`,`Run Data > Advanced. Run it again whenever Q1 or Q2 changes: the extract does not update by itself.`,`Check that Q4 equals the number of orders copied.`],pitfalls:[`The two bounds on separate rows are OR, and every order passes.`,`">=Q1" inside the quotes compares with the text Q1, not the value in Q1.`],answer:`Report M1:N2, the extract from M8 and Q4.`},{id:`data-filters-date-window`,topic:`filters`,question:`Q1 holds a start date and Q2 an end date. In M1:N2 build criteria from these two cells that extract the orders dated from Q1 to Q2 (both days included) to M8, and count them by formula in Q4.`,layout:A,formulas:[{cell:`M2`,formula:`=">="&TEXT(Q1,"d mmm yyyy")`,note:`Shows, for example, >=1 Mar 2026`},{cell:`N2`,formula:`="<="&TEXT(Q2,"d mmm yyyy")`},{cell:`M2 (alternative)`,formula:`=">="&Q1`,note:`Also works: compares the date serial number (1 Mar 2026 shows as >=46082)`},{cell:`Q4`,formula:`=COUNTIF(D9:D68,">="&Q1)-COUNTIF(D9:D68,">"&Q2)`}],tool:[`Data > Advanced`,`Action: Copy to another location`,`List range: $A$8:$K$68`,`Criteria range: $M$1:$N$2`,`Copy to: $M$8`],steps:[`M1 and N1 both hold Order Date, spelt exactly as in D8.`,`M2 and N2 turn the dates in Q1 and Q2 into criteria text with TEXT, joined to the operator with &.`,`Run Data > Advanced; Q4 must equal the number of orders copied.`],pitfalls:[`A TEXT format that Excel cannot read back as a date, such as "yyyymmdd", matches nothing.`,`> and < instead of >= and <= lose the orders placed on the first and the last day.`,`The header must read Order Date exactly: "Date" is not a field of this list.`],answer:`Report M1:N2, the extract from M8 and Q4.`},{id:`data-filters-unique-customers`,topic:`filters`,question:`With Advanced Filter, list each customer in the order book once, starting at M8, and report the number of distinct customers in Q2.`,layout:`${A} The extract will fill column M from the header in M8 down; M9:M68 is empty beforehand.`,formulas:[{cell:`Q2`,formula:`=COUNTIF(M9:M68,"<>")`,note:`Counts the names below the header M8`}],tool:[`Data > Advanced`,`Action: Copy to another location`,`List range: $E$8:$E$68 (Customer column only, header included)`,`Criteria range: leave blank`,`Copy to: $M$8`,`Unique records only: ticked`],steps:[`Use only the Customer column E8:E68 as the list range: duplicates are judged on whole rows of the list range.`,`Leave the criteria range blank so no customer is excluded.`,`Tick Unique records only and copy to M8, then count the names in Q2.`,`For distinct pairs, such as Region and Channel, use $B$8:$C$68 as the list range instead.`],pitfalls:[`With the full list $A$8:$K$68 every row is unique (each order has its own Order ID), so nothing is removed.`,`Names that differ only by a trailing space count as two customers.`,`Do not count the header: the count starts at M9.`],answer:`Q2 = number of distinct customers; M9 down lists each name once.`},{id:`data-filters-wildcards`,topic:`filters`,question:`Copy to M8 the orders whose Customer name contains Hotel anywhere and whose Product begins with Durian, using criteria in M1:N2. In Q2 count all orders from customers whose name contains Hotel (any product), and in Q3 count the records extracted.`,layout:`${A} After the filter, the copied Qty column lands in T9:T68 (list columns A to K map to output columns M to W).`,formulas:[{cell:`Q2`,formula:`=COUNTIF(E9:E68,"*Hotel*")`,note:`* stands for any run of characters, including none`},{cell:`Q3`,formula:`=COUNT(T9:T68)`,note:`Counts the copied rows through their numeric Qty`},{cell:`Q3 (alternative)`,formula:`=COUNTIFS(E9:E68,"*Hotel*",F9:F68,"Durian*")`,note:M}],tool:[`Data > Advanced`,`Action: Copy to another location`,`List range: $A$8:$K$68`,`Criteria range: $M$1:$N$2`,`Copy to: $M$8`],steps:[`Headers M1 Customer and N1 Product, copied from E8 and F8.`,`M2 *Hotel* (contains Hotel); N2 Durian* (begins with Durian; plain Durian does the same in Advanced Filter).`,`Both sit on row 2, so both must hold. Run Data > Advanced and copy to M8.`],pitfalls:[`Plain Hotel in M2 means "begins with Hotel" and misses names such as Marina Bay Hotel.`,`="=Hotel" is an exact match and finds only a customer called just Hotel.`,`COUNTIF needs the * written in: COUNTIF(E9:E68,"Hotel") counts only cells equal to Hotel.`],answer:`Report M1:N2, the extract from M8, Q2 and Q3.`},{id:`data-filters-count-crosscheck`,topic:`filters`,question:`An Advanced Filter with criteria M1:O2 (Region exactly Central, Channel exactly Online, Revenue above 800) has copied the matching orders to M8. As a cross-check, give in Q4 the number of such orders and in Q5 their total revenue, both by formula on the original list.`,layout:`${A} Criteria range M1:O2: M1 Region, N1 Channel, O1 Revenue; M2 ="=Central", N2 ="=Online", O2 holds the text >800.`,formulas:[{cell:`Q4`,formula:`=SUMPRODUCT((B9:B68="Central")*(C9:C68="Online")*(K9:K68>800))`,note:`Each test gives 1 or 0; the product is 1 only when all three hold`},{cell:`Q5`,formula:`=SUMPRODUCT((B9:B68="Central")*(C9:C68="Online")*(K9:K68>800)*K9:K68)`},{cell:`Q4 (alternative)`,formula:`=COUNTIFS(B9:B68,"Central",C9:C68,"Online",K9:K68,">800")`,note:M},{cell:`Q5 (alternative)`,formula:`=SUMIFS(K9:K68,B9:B68,"Central",C9:C68,"Online",K9:K68,">800")`,note:M}],tool:[`Data > Advanced`,`Action: Copy to another location`,`List range: $A$8:$K$68`,`Criteria range: $M$1:$O$2`,`Copy to: $M$8`],steps:[`Turn each criteria cell into a test in brackets: (B9:B68="Central"), (C9:C68="Online"), (K9:K68>800).`,`Multiply the tests for AND; SUMPRODUCT adds the 1s, which counts the orders.`,`Multiply by K9:K68 as well to total their revenue.`,`Q4 must equal the rows copied, and Q5 the sum of the copied Revenue column (W9:W68).`],pitfalls:[`Tests separated by commas instead of * make SUMPRODUCT return 0.`,`A comparison inside SUMPRODUCT is an exact match, while plain text in a criteria cell means "begins with".`,`Above 800 is >800; >=800 would add the orders of exactly 800.`],answer:`Q4 = number of orders copied below M8; Q5 = their total revenue.`},{id:`data-pivot-total-by-category`,topic:`pivot`,question:`Build a PivotTable on a new sheet showing total Revenue for each Category, with a grand total. On the data sheet, check the Fruit total in Q2 and the grand total in Q3 by formula.`,layout:A,formulas:[{cell:`Q2`,formula:`=SUMIF(G9:G68,"Fruit",K9:K68)`,note:`Range to test, criterion, range to add`},{cell:`Q3`,formula:`=SUM(K9:K68)`}],tool:[`Click a cell inside A8:K68, then Insert > PivotTable`,`Table/Range: $A$8:$K$68; location: New Worksheet`,`Rows: Category`,`Values: Revenue (Sum of Revenue)`],steps:[`Insert the PivotTable from the whole list, headers included.`,`Drag Category to Rows and Revenue to Values.`,`If Values shows Count of Revenue, change it in Value Field Settings to Sum.`,`Q2 must equal the Fruit row and Q3 the Grand Total.`],pitfalls:[`SUMIF takes the criteria range first and the sum range last: SUMIF(K9:K68,"Fruit",G9:G68) returns 0.`,`After the data changes, right-click the PivotTable > Refresh: it does not update by itself.`],answer:`Report the PivotTable and Q2:Q3; the Fruit row equals Q2 and the Grand Total equals Q3.`},{id:`data-pivot-region-by-channel`,topic:`pivot`,question:`Summarise total Revenue with Region down the side and Channel across the top: first as a PivotTable on a new sheet, then by formula in N2:Q6, with the regions in M2:M6 and the channels in N1:Q1.`,layout:`${A} M2:M6 hold North, North-East, East, West, Central; N1:Q1 hold Hawker, Restaurant, Supermarket, Online.`,formulas:[{cell:`N2 (fill to N2:Q6)`,formula:`=SUMPRODUCT(($B$9:$B$68=$M2)*($C$9:$C$68=N$1)*$K$9:$K$68)`,note:`Region label: column locked; channel label: row locked; data ranges fully locked`},{cell:`N2 (alternative)`,formula:`=SUMIFS($K$9:$K$68,$B$9:$B$68,$M2,$C$9:$C$68,N$1)`,note:M}],tool:[`Insert > PivotTable, Table/Range: $A$8:$K$68, New Worksheet`,`Rows: Region`,`Columns: Channel`,`Values: Sum of Revenue`],steps:[`Drag Region to Rows, Channel to Columns and Revenue to Values.`,`For the formula grid, lock the data ranges fully, the region label by column ($M2) and the channel label by row (N$1).`,`Write N2 once and fill it to Q6; each cell must match the pivot cell with the same two labels.`],pitfalls:[`$M$2 in the formula repeats North in every row of the grid.`,`The PivotTable sorts the regions A to Z, so compare cells by label, not by position.`,`An empty pivot cell means no orders for that pair; the formula shows 0 there.`],answer:`N2:Q6 match the PivotTable body, and =SUM(N2:Q6) matches its Grand Total.`},{id:`data-pivot-percent-of-total`,topic:`pivot`,question:`Show each Category's share of total Revenue as a percentage: with a PivotTable on a new sheet, and by formula in N2:N4 for the categories in M2:M4, with a check total in N5.`,layout:`${A} M2:M4 hold Vegetables, Fruit, Herbs.`,formulas:[{cell:`N2 (fill to N2:N4)`,formula:`=SUMIF($G$9:$G$68,M2,$K$9:$K$68)/SUM($K$9:$K$68)`,note:`Category total over the locked grand total`},{cell:`N5`,formula:`=SUM(N2:N4)`,note:`Must show 100%`}],tool:[`Insert > PivotTable, Table/Range: $A$8:$K$68, New Worksheet`,`Rows: Category; Values: Sum of Revenue`,`Value Field Settings > Show Values As: % of Grand Total`],steps:[`Build the Sum of Revenue by Category pivot first.`,`Value Field Settings > Show Values As tab > % of Grand Total (or right-click a value > Show Values As).`,`For the formulas, divide each category total by the anchored grand total and format N2:N5 as percentages.`],pitfalls:[`SUM(K9:K68) without $ slides down as the formula is filled (K10:K69, K11:K70).`,`Once a Columns field is added, % of Column Total and % of Row Total give shares within a column or a row, not of the grand total.`],answer:`N2:N4 equal the pivot percentages and add up to 100% in N5.`},{id:`data-pivot-average-by-channel`,topic:`pivot`,question:`Report the average Revenue per order for each Channel: with a PivotTable on a new sheet, and by formula in N2:N5 for the channels listed in M2:M5.`,layout:`${A} M2:M5 hold Hawker, Restaurant, Supermarket, Online.`,formulas:[{cell:`N2 (fill to N2:N5)`,formula:`=SUMIF($C$9:$C$68,M2,$K$9:$K$68)/COUNTIF($C$9:$C$68,M2)`,note:`Channel total over the number of orders in the channel`},{cell:`N2 (alternative)`,formula:`=AVERAGEIF($C$9:$C$68,M2,$K$9:$K$68)`,note:M}],tool:[`Insert > PivotTable, Table/Range: $A$8:$K$68, New Worksheet`,`Rows: Channel; Values: Revenue`,`Value Field Settings > Summarize value field by: Average`,`Number Format: Number, 2 decimal places`],steps:[`Drag Channel to Rows and Revenue to Values (it starts as Sum of Revenue).`,`Value Field Settings > Average: the field becomes Average of Revenue.`,`Formula check: the channel total divided by the channel order count.`],pitfalls:[`Leaving Sum, or picking Count, answers a different question: the field name in the pivot shows which one is used.`,`The Grand Total of an Average pivot is the average over all orders, not the average of the four channel averages.`,`A label in M2:M5 that does not appear in the list gives #DIV/0!.`],answer:`N2:N5 equal the Average of Revenue values in the pivot, to 2 decimal places.`},{id:`data-pivot-month-helper`,topic:`pivot`,question:`Management wants total Revenue by month. Add a helper column Month in column L (header in L8) holding the year and month of each order, then build a PivotTable of total Revenue by Month.`,layout:`${A} Column L is empty.`,formulas:[{cell:`L9 (fill to L9:L68)`,formula:`=TEXT(D9,"yyyy-mm")`,note:`Text such as 2026-03, which sorts in date order`}],tool:[`Type Month in L8 and fill L9 down to L68`,`Insert > PivotTable, Table/Range: $A$8:$L$68 (include column L), New Worksheet`,`Rows: Month`,`Values: Sum of Revenue`],steps:[`Give L8 the header Month so the PivotTable can use the column.`,`L9 =TEXT(D9,"yyyy-mm"), filled down to L68.`,`Build the PivotTable on A8:L68 with Month in Rows and Revenue in Values.`,`Without a helper: put Order Date in Rows, then right-click a date > Group > Months (and Years).`],pitfalls:[`TEXT(D9,"mmm") merges the same month of different years into one row; "yyyy-mm" keeps them apart.`,`A PivotTable built on A8:K68 has no Month field: widen it with Change Data Source, then Refresh.`,`A blank header in L8 stops the PivotTable with a "field name is not valid" message.`],answer:`One row per month (2026-01, 2026-02, ...) with its Sum of Revenue; the Grand Total equals =SUM(K9:K68).`},{id:`data-sumproduct-countif-cell-criterion`,topic:`sumproduct`,question:`The dispatcher types a distance in km in J2. In J4 count the jobs longer than that distance, so that J4 updates whenever J2 changes.`,layout:`${j} J2 is the input cell.`,formulas:[{cell:`J4`,formula:`=COUNTIF(D6:D45,">"&J2)`,note:`The criterion becomes text such as >8`}],steps:[`Range first: the Distance column D6:D45.`,`Build the criterion by joining the operator in quotes to the cell: ">"&J2.`,`Test it by changing J2 and watching J4 change.`],pitfalls:[`">J2" inside the quotes compares with the text J2 and returns 0.`,`"Longer than" is >; "at least" would be ">="&J2.`],answer:`J4 = number of jobs with a Distance greater than J2.`},{id:`data-sumproduct-sumif-by-zone`,topic:`sumproduct`,question:`The five zones are listed in L6:L10. In M6:M10 give the total fee earned in each zone with one formula filled down, and in M11 the sum of the zone totals.`,layout:`${j} L6:L10 hold North, South, East, West, Central.`,formulas:[{cell:`M6 (fill to M6:M10)`,formula:`=SUMIF($B$6:$B$45,L6,$E$6:$E$45)`},{cell:`M11`,formula:`=SUM(M6:M10)`,note:`Must equal =SUM(E6:E45); if it is lower, a label in L6:L10 is misspelt`}],steps:[`SUMIF(range, criteria, sum_range): the Zone column, this row's label, the Fee column.`,`Lock both data ranges with $, leave L6 relative, and fill down to M10.`,`Check that M11 equals the total of all fees.`],pitfalls:[`Without $ the ranges slide down when filled, so the lower rows miss the first jobs.`,`A label typed "East " with a trailing space returns 0.`],answer:`M6:M10 hold one total per zone; M11 equals SUM(E6:E45).`},{id:`data-sumproduct-average-by-zone`,topic:`sumproduct`,question:`For the zones in L6:L10, show in N6:N10 the average fee per job in each zone, using taught functions only.`,layout:`${j} L6:L10 hold North, South, East, West, Central.`,formulas:[{cell:`N6 (fill to N6:N10)`,formula:`=SUMIF($B$6:$B$45,L6,$E$6:$E$45)/COUNTIF($B$6:$B$45,L6)`,note:`Zone total over the number of jobs in the zone`},{cell:`N6 (alternative)`,formula:`=AVERAGEIF($B$6:$B$45,L6,$E$6:$E$45)`,note:M}],steps:[`Zone total with SUMIF, number of jobs in the zone with COUNTIF, then divide.`,`Lock the data ranges, keep L6 relative, and fill down to N10.`,`If the zone totals already sit in M6:M10, =M6/COUNTIF($B$6:$B$45,L6) gives the same result.`],pitfalls:[`Dividing by 40 (all jobs) instead of the zone count understates every average.`,`A zone with no jobs gives #DIV/0!; wrap the formula in IFERROR(...,0) only if the question allows it.`],answer:`N6:N10 hold the average fee per job in S$, shown to 2 decimal places.`},{id:`data-sumproduct-count-between`,topic:`sumproduct`,question:`J2 holds a lower and J3 an upper distance in km. In J4 count the jobs whose Distance is from J2 to J3, both limits included.`,layout:`${j} J2 and J3 are input cells; the value in J2 is not greater than the value in J3.`,formulas:[{cell:`J4`,formula:`=COUNTIF(D6:D45,">="&J2)-COUNTIF(D6:D45,">"&J3)`,note:`At least J2, minus those above J3`},{cell:`J4 (SUMPRODUCT alternative)`,formula:`=SUMPRODUCT((D6:D45>=J2)*(D6:D45<=J3))`,note:`Same count with two tests multiplied (AND)`},{cell:`J4 (COUNTIFS alternative)`,formula:`=COUNTIFS(D6:D45,">="&J2,D6:D45,"<="&J3)`,note:M}],steps:[`Count every job at or above the lower limit.`,`Subtract every job strictly above the upper limit, so jobs exactly at J3 stay in.`,`Check with the SUMPRODUCT version: both must agree.`],pitfalls:[`Subtracting COUNTIF(D6:D45,">="&J3) also removes the jobs exactly at J3.`,`For strictly between, use ">"&J2 in the first term and ">="&J3 in the second.`],answer:`J4 = number of jobs with J2 <= Distance <= J3.`},{id:`data-sumproduct-two-conditions`,topic:`sumproduct`,question:`J2 holds a zone name and J3 a vehicle type. In J4 count the jobs that match both, and in J5 total their fees, using taught functions only.`,layout:`${j} J2 (for example East) and J3 (for example Van) are input cells.`,formulas:[{cell:`J4`,formula:`=SUMPRODUCT((B6:B45=J2)*(C6:C45=J3))`},{cell:`J5`,formula:`=SUMPRODUCT((B6:B45=J2)*(C6:C45=J3)*E6:E45)`},{cell:`J4 (alternative)`,formula:`=COUNTIFS(B6:B45,J2,C6:C45,J3)`,note:M},{cell:`J5 (alternative)`,formula:`=SUMIFS(E6:E45,B6:B45,J2,C6:C45,J3)`,note:M}],steps:[`Write each condition as a test in brackets: (B6:B45=J2) and (C6:C45=J3).`,`Multiply the tests: TRUE x TRUE = 1 and anything with a FALSE = 0, so SUMPRODUCT counts the matches.`,`Multiply by the Fee column as well to add up the fees of the matching jobs only.`],pitfalls:[`Commas between the tests, SUMPRODUCT((B6:B45=J2),(C6:C45=J3)), return 0: only * turns TRUE/FALSE into 1/0.`,`All ranges must cover the same rows (6 to 45), else #VALUE!.`,`SUMIFS puts the sum range first, unlike SUMIF where it comes last.`],answer:`J4 = number of jobs in zone J2 with vehicle J3; J5 = their total fee.`},{id:`data-sumproduct-share-rated`,topic:`sumproduct`,question:`In J4 show, as a percentage, the share of rated jobs that scored 4 or 5. Jobs without a rating must not count.`,layout:j,formulas:[{cell:`J4`,formula:`=COUNTIF(F6:F45,">=4")/COUNT(F6:F45)`,note:`COUNT counts only the rated (numeric) cells`}],steps:[`Numerator: jobs rated 4 or more, COUNTIF(F6:F45,">=4").`,`Denominator: jobs rated at all, COUNT(F6:F45), which skips the blanks.`,`Format J4 as a percentage.`],pitfalls:[`Dividing by 40 puts the unrated jobs into the base and understates the share.`,`">4" leaves out the 4s: "4 or 5" is ">=4".`],answer:`J4 formatted as a percentage.`},{id:`data-sumproduct-count-nonblank`,topic:`sumproduct`,question:`Report in J4 how many jobs were rated, in J5 how many have a comment, and in J6 how many were not rated.`,layout:j,formulas:[{cell:`J4`,formula:`=COUNT(F6:F45)`,note:`Counts cells holding numbers`},{cell:`J5`,formula:`=COUNTIF(G6:G45,"<>")`,note:`Counts cells that are not empty, text included`},{cell:`J6`,formula:`=COUNTIF(F6:F45,"")`,note:`Counts the empty Rating cells`}],steps:[`Numeric answers (ratings): COUNT counts the cells holding numbers.`,`Text answers (comments): COUNTIF(range,"<>") counts the cells that are not empty.`,`Blanks: COUNTIF(range,""); check that J4 + J6 equals the 40 jobs.`],pitfalls:[`COUNT(G6:G45) returns 0 because the comments are text.`,`A cell holding only a space looks empty but is counted by "<>" and not by "".`],answer:`Three whole numbers, with J4 + J6 = 40.`},{id:`data-sumproduct-top3-large`,topic:`sumproduct`,question:`In J4 give the total fee of the three highest-paying jobs, and in J5 the share of all fees that these three jobs represent.`,layout:j,formulas:[{cell:`J4`,formula:`=LARGE(E6:E45,1)+LARGE(E6:E45,2)+LARGE(E6:E45,3)`},{cell:`J4 (alternative)`,formula:`=SUMPRODUCT(LARGE(E6:E45,{1,2,3}))`,note:`Same total with one LARGE and the array constant {1,2,3}`},{cell:`J5`,formula:`=J4/SUM(E6:E45)`,note:`Format as a percentage`}],steps:[`LARGE(range,k) returns the k-th highest value: k = 1, 2, 3.`,`Add the three, or put the array constant {1,2,3} inside SUMPRODUCT.`,`Divide by the total of all fees for the share.`],pitfalls:[`MAX(E6:E45)*3 triples the top fee instead of adding the top three.`,`Tied fees each count: if two jobs share the top fee, LARGE(...,1) and LARGE(...,2) both return it.`,`SMALL(range,k) gives the k-th lowest, for "the three cheapest jobs".`],answer:`J4 in S$, J5 as a percentage.`},{id:`data-anchoring-quote-grid`,topic:`anchoring`,question:`Build a quote grid in B6:F12 that gives the charge for each number of cartons in A6:A12 at each discount rate in B5:F5, with the list price per carton in B2. Write one formula in B6 and fill it to F12.`,layout:`B2 list price per carton: 24 (S$). A6:A12 carton numbers: 10, 20, 30, 40, 50, 60, 70. B5:F5 discount rates: 0%, 5%, 10%, 15%, 20%.`,formulas:[{cell:`B6 (fill to B6:F12)`,formula:`=$A6*$B$2*(1-B$5)`,note:`Cartons: column locked; discount: row locked; price: both locked`}],steps:[`The cartons sit in column A on every row: lock the column, $A6.`,`The discounts sit in row 5 for every column: lock the row, B$5.`,`The price is one cell for the whole grid: lock both, $B$2.`,`Fill B6 right to F6 and down to F12, then click F12 and check that it reads $A12, $B$2 and F$5.`],pitfalls:[`A6 without $ turns into B6, C6 ... (cells of the grid itself) when filled right.`,`B5 without the $ before the 5 slides down to B6, B7 ... when filled down.`,`B2 without $ reads the empty cells C2, D2 ... when filled right and returns 0.`],answer:`B6 = 240; D9 (40 cartons at 10%) = 864; F12 (70 cartons at 20%) = 1344.`},{id:`data-anchoring-growth-fill`,topic:`anchoring`,question:`January sales for five outlets are in B6:B10 and the monthly growth rate is in B2. Fill C6:M10 with the projected sales for February to December, each month growing by the rate in B2 on the month before. Write one formula in C6 and fill it right and down.`,layout:`B2 monthly growth rate: 2%. A6:A10 outlet names; B6:B10 January sales (B6 = 10000); C5:M5 month labels Feb to Dec.`,formulas:[{cell:`C6 (fill to C6:M10)`,formula:`=B6*(1+$B$2)`,note:`Previous month (relative) times the locked growth factor`}],steps:[`Each cell grows the cell to its left, so the reference to B6 stays fully relative.`,`The rate is one cell for the whole grid: $B$2.`,`Fill C6 right to M6, then fill C6:M6 down to row 10.`],pitfalls:[`$B6 would grow every month from January, so all of C6:M6 would show 10200.`,`B2 without $ moves to the empty C2, D2 ... and multiplies by 1, so sales stop growing.`],answer:`With B6 = 10000 and B2 = 2%: C6 = 10200, D6 = 10404, M6 = 10000 x 1.02^11 = 12433.74 (2 dp).`},{id:`data-anchoring-row-share`,topic:`anchoring`,question:`Quarterly sales for five outlets are in B5:E9. In F5:F9 give each outlet's annual total, then in H5:K9 show each quarter as a percentage of that outlet's annual total, writing one formula in H5 and filling it across and down.`,layout:`A5:A9 outlet names; B5:E9 sales for Q1 to Q4 (row 5: 120, 150, 90, 140); F5:F9 empty for the totals; H5:K9 empty for the shares.`,formulas:[{cell:`F5 (fill to F5:F9)`,formula:`=SUM(B5:E5)`},{cell:`H5 (fill to H5:K9)`,formula:`=B5/$F5`,note:`Column F locked so every quarter divides by the total; row free so each outlet uses its own total`}],steps:[`Totals: =SUM(B5:E5) in F5, filled down to F9.`,`Shares: the quarter (B5) moves with the fill, the total stays in column F: $F5.`,`Format H5:K9 as percentages; each row adds up to 100%.`,`For a share of each quarter's column total instead (totals in row 10), the lock flips: =B5/B$10.`],pitfalls:[`Without the $ on F, I5 divides by the empty G5 and shows #DIV/0!.`,`$F$5 divides every outlet by the first outlet's total.`],answer:`F5 = 500; H5:K5 = 24%, 30%, 18%, 28%.`},{id:`data-exact-lookup-iferror-not-found`,topic:`exact-lookup`,question:`A clerk types a product code in F2. In F3 return its unit price from the price list, and show the text Not found when the code is not in the list.`,layout:`Price list A5:C30: headers in row 5, product codes A6:A30 (text such as FF-101), product names B6:B30, unit prices C6:C30 (S$). The code is typed in F2.`,formulas:[{cell:`F3`,formula:`=IFERROR(VLOOKUP(F2,$A$6:$C$30,3,FALSE),"Not found")`,note:`Exact match; the #N/A of a missing code becomes the text`},{cell:`F3 (alternative)`,formula:`=IFERROR(INDEX($C$6:$C$30,MATCH(F2,$A$6:$A$30,0)),"Not found")`}],steps:[`Write the exact lookup first, VLOOKUP(F2,$A$6:$C$30,3,FALSE), and test it with a real code.`,`Wrap it: IFERROR(lookup,"Not found").`,`Test again with a code that is not in the list.`],pitfalls:[`Without FALSE (or with TRUE) VLOOKUP matches approximately and can return a wrong price for a missing code.`,`IFERROR also hides real mistakes such as a wrong column number, so test the bare lookup first.`,`A code stored as a number in one place and as text in the other never matches.`],answer:`F3 shows the price for a listed code and the text Not found otherwise.`},{id:`data-capacity-boxes-and-gst`,topic:`capacity`,question:`A caterer needs the number of curry puffs in B4; each box holds the number in B5 and costs the price in B6. Give in B7 the boxes to buy, in B8 the boxes that will be completely full, in B9 the puffs in the last, part-filled box, in B10 the cost of the boxes, in B11 the GST on B10 at the rate in B3 rounded to the cent, and in B12 the total bill.`,layout:`B3 GST rate: 9%. B4 puffs needed: 250. B5 puffs per box: 24. B6 price per box: 28.40 (S$).`,formulas:[{cell:`B7`,formula:`=ROUNDUP(B4/B5,0)`,note:`Containers always round up`},{cell:`B8`,formula:`=ROUNDDOWN(B4/B5,0)`,note:`=INT(B4/B5) gives the same for positive numbers`},{cell:`B9`,formula:`=MOD(B4,B5)`,note:`Remainder after the full boxes`},{cell:`B10`,formula:`=B7*B6`},{cell:`B11`,formula:`=ROUND(B10*B3,2)`,note:`Rounded to the cent`},{cell:`B12`,formula:`=B10+B11`}],steps:[`Containers to buy: ROUNDUP(amount/size,0).`,`Full containers: ROUNDDOWN or INT; the remainder: MOD(amount,size).`,`Money to the cent: ROUND(value,2); to whole dollars: ROUND(value,0), or ROUNDUP/ROUNDDOWN if the rule says so.`],pitfalls:[`ROUND(B4/B5,0) gives 10 boxes and leaves 10 puffs without a box.`,`Formatting B11 to 2 decimals only changes the display: B12 would still add 28.116. Use ROUND when the question says round.`,`MOD(B4,B5) = 0 means the last box is completely full.`],answer:`B7 = 11, B8 = 10, B9 = 10, B10 = 312.40, B11 = 28.12 (from 28.116), B12 = 340.52.`},{id:`data-exact-lookup-best-seller`,topic:`exact-lookup`,question:`Units sold for eight dishes are in B5:B12, with the dish names in A5:A12. In E2 return the name of the best-selling dish, in E3 its units, in E4 the name of the weakest seller and in E5 the name of the runner-up.`,layout:`A5:A12 dishes: Kaya Toast, Nasi Lemak, Laksa, Chicken Rice, Satay, Roti Prata, Mee Goreng, Char Kway Teow. B5:B12 units sold: 320, 415, 280, 506, 198, 377, 245, 389.`,formulas:[{cell:`E2`,formula:`=INDEX(A5:A12,MATCH(MAX(B5:B12),B5:B12,0))`,note:`Position of the largest value, then the name in that position`},{cell:`E3`,formula:`=MAX(B5:B12)`},{cell:`E4`,formula:`=INDEX(A5:A12,MATCH(MIN(B5:B12),B5:B12,0))`},{cell:`E5`,formula:`=INDEX(A5:A12,MATCH(LARGE(B5:B12,2),B5:B12,0))`,note:`LARGE(range,2) is the second highest`}],steps:[`Find the value: MAX, MIN or LARGE(range,k).`,`MATCH(value,units,0) gives its position in the list.`,`INDEX(names,position) returns the name in that position.`],pitfalls:[`MATCH without the 0 assumes sorted data and can return the wrong dish.`,`If two dishes tie, MATCH returns the first one listed.`,`The INDEX and MATCH ranges must start and end on the same rows (5 to 12).`],answer:`E2 = Chicken Rice, E3 = 506, E4 = Satay (198 units), E5 = Nasi Lemak (415 units).`},{id:`data-dates-quarter-label`,topic:`dates`,question:`Add two helper columns to the order list for a quarterly PivotTable: in L9:L68 (header Quarter in L8) a label Q1 to Q4 from each Order Date, and in M9:M68 (header Period in M8) a label such as 2026-Q3.`,layout:`${A} Columns L and M are empty.`,formulas:[{cell:`L9 (fill to L9:L68)`,formula:`="Q"&ROUNDUP(MONTH(D9)/3,0)`},{cell:`M9 (fill to M9:M68)`,formula:`=YEAR(D9)&"-Q"&ROUNDUP(MONTH(D9)/3,0)`},{cell:`L9 (alternative)`,formula:`=IF(MONTH(D9)<=3,"Q1",IF(MONTH(D9)<=6,"Q2",IF(MONTH(D9)<=9,"Q3","Q4")))`,note:`Same labels with nested IF`}],steps:[`MONTH(D9)/3 rounded up gives 1 for Jan-Mar, 2 for Apr-Jun, 3 for Jul-Sep and 4 for Oct-Dec.`,`Join the text and the number with &: "Q"&...`,`Fill down to row 68, then use Quarter or Period as the PivotTable row field (list range $A$8:$M$68).`],pitfalls:[`ROUND instead of ROUNDUP puts April (4/3 = 1.33) in Q1.`,`Excel has no format code for quarters, so TEXT cannot produce Q1 to Q4.`,`The labels are text: they group and filter well but cannot be added up.`],answer:`An order of 15 Aug 2026 gives Q3 and 2026-Q3; 1 Apr 2026 gives Q2; 31 Mar 2026 gives Q1.`},{id:`data-interpret-formulatext`,topic:`interpret`,question:`The answer template asks you to show, beside each answer, the formula that produced it: show the formula of J4 as text in K4, and the formulas of the model column F6:F20 in G6:G20.`,layout:`J4 holds your answer formula (for example =COUNTIF(D6:D45,">"&J2)). F6:F20 hold a column of formulas. K4 and G6:G20 are empty.`,formulas:[{cell:`K4`,formula:`=FORMULATEXT(J4)`},{cell:`G6 (fill to G6:G20)`,formula:`=FORMULATEXT(F6)`}],steps:[`FORMULATEXT(cell) returns the formula of that cell as text, exactly as typed.`,`Fill it down beside a column of formulas to document them all at once.`,`Keep the working formula in the answer cell itself: FORMULATEXT only displays it.`],pitfalls:[`A cell holding a typed number makes FORMULATEXT return #N/A, which shows that the answer was hard-coded.`,`Typing the formula as text after an apostrophe also shows it, but it does not update when the formula changes.`],answer:`K4 displays the text =COUNTIF(D6:D45,">"&J2) and follows any change made to J4.`},{id:`data-if-logic-probability-check`,topic:`if-logic`,question:`A demand distribution lists demand values in A5:A9 and their probabilities in B5:B9. In B11 show OK if the probabilities add up to 1 and Check otherwise, and in B12 give the expected demand.`,layout:`A5:A9 demand: 10, 20, 30, 40, 50. B5:B9 probabilities: 0.10, 0.25, 0.30, 0.20, 0.15.`,formulas:[{cell:`B11`,formula:`=IF(ROUND(SUM(B5:B9),6)=1,"OK","Check")`},{cell:`B11 (alternative)`,formula:`=ROUND(SUM(B5:B9),6)=1`,note:`Returns TRUE or FALSE`},{cell:`B12`,formula:`=SUMPRODUCT(A5:A9,B5:B9)`,note:`Each value times its probability, added up`}],steps:[`Add the probabilities with SUM.`,`Round the sum to 6 decimals before comparing it with 1, so tiny floating-point errors cannot fail the test.`,`Expected value: SUMPRODUCT of the values and the probabilities.`],pitfalls:[`Without ROUND, a sum stored as 0.9999999999999999 can fail an exact test against 1.`,`Probabilities typed as 25 instead of 25% add up to 100, not 1.`,`Run the check before building a cumulative column for a simulation lookup.`],answer:`B11 = OK (the five probabilities add up to 1); B12 = 30.5.`}],P=[...x,...k,...N];export{b as a,a as c,y as i,o as l,v as n,d as o,p as r,f as s,P as t,l as u};